    'maint.aide_tech_title' => "Le déclarant",
    'maint.aide_tech_sub' => "Qui signale cette intervention ?",
    'maint.aide_tech_body' => <<<'HTML'
<p>Le déclarant est la personne qui ouvre le ticket — celle qui a constaté la panne ou qui a une tâche à faire réaliser.</p>
            <ul class="aide-list">
                <li><i class="fa-solid fa-lock" style="color:var(--accent);"></i> Si vous êtes technicien, ce champ est verrouillé sur votre propre nom.</li>
                <li><i class="fa-solid fa-user-shield" style="color:var(--accent);"></i> Un administrateur peut désigner n'importe quel membre de l'équipe.</li>
            </ul>
HTML,

    'maint.aide_assign_tech_title' => "Intervenants prévus",
    'maint.aide_assign_tech_sub' => "Pré-assigner un ou plusieurs techniciens dès la création (optionnel)",
    'maint.aide_assign_tech_body' => <<<'HTML'
<p>Ce champ, réservé aux administrateurs, permet de cocher à l'avance un ou plusieurs techniciens qui vont s'occuper de cette intervention — pratique pour organiser le planning. Laissez "Non assigné" coché si personne n'est encore désigné : le technicien qui prendra en charge le ticket s'assignera lui-même la tâche.</p>
            <div class="aide-callout aide-callout-info"><i class="fa-solid fa-circle-info"></i><div>Ce n'est qu'une indication : c'est la personne qui pointe réellement du temps sur le ticket qui devient l'intervenant officiel.</div></div>
HTML,

    'maint.aide_sous_traitant_title' => "Intervention sous-traitée",
    'maint.aide_sous_traitant_sub' => "Quand une entreprise extérieure intervient",
    'maint.aide_sous_traitant_body' => <<<'HTML'
<p>Cochez cette case si l'intervention est confiée à un prestataire externe plutôt qu'à l'équipe interne.</p>
            <ul class="aide-list">
                <li><i class="fa-solid fa-list-check" style="color:var(--brand-orange);"></i> Choisissez ensuite l'entreprise dans la liste qui apparaît juste en dessous.</li>
                <li><i class="fa-solid fa-file-pdf" style="color:var(--brand-orange);"></i> Une fois le bon créé, un bouton « Générer PDP » (Plan de Prévention) apparaîtra sur sa fiche.</li>
            </ul>
HTML,

    'maint.aide_localisation_title' => "Localiser la machine",
    'maint.aide_localisation_sub' => "Recherche ou navigation par tuiles",
    'maint.aide_localisation_body' => <<<'HTML'
<p>Deux façons de trouver la machine : tapez son nom (ou une zone, un secteur...) dans la barre de <b>recherche</b>, ou cliquez de proche en proche sur les tuiles <b>Usine → Secteur → Ligne → Zone → Machine</b>.</p>
            <div class="aide-callout aide-callout-tip"><i class="fa-solid fa-lightbulb"></i><div>Le fil d'Ariane au-dessus des tuiles permet de revenir en arrière à tout moment pour changer d'usine, de secteur, etc. Pas de panique si un secteur n'a pas de « Ligne » : cette étape est automatiquement sautée.</div></div>
HTML,

    'maint.aide_machine_title' => "Sélection de la machine",
    'maint.aide_machine_sub' => "Le dernier maillon de la localisation",
    'maint.aide_machine_body' => <<<'HTML'
<p>La barre de recherche filtre instantanément sur toutes les machines (nom, zone, secteur, usine) : idéal quand on connaît déjà la machine. Sinon, les tuiles en dessous permettent de naviguer pas à pas jusqu'à l'équipement concerné. Cela garde un historique de maintenance propre, machine par machine.</p>
            <div class="aide-callout aide-callout-warn"><i class="fa-solid fa-triangle-exclamation"></i><div>Machine introuvable ? Le champ devient une saisie libre — pensez à la faire ajouter au Parc Machine par un administrateur pour la prochaine fois.</div></div>
HTML,

    'maint.aide_date_title' => "Date de l'intervention",
    'maint.aide_date_sub' => "Aujourd'hui par défaut",
    'maint.aide_date_body' => "<p>La date du jour est pré-remplie automatiquement. Vous pouvez la modifier si vous déclarez une intervention passée, par exemple pour rattraper une saisie oubliée.</p>",

    'maint.aide_type_title' => "Type d'intervention",
    'maint.aide_type_sub' => "Curatif, Préventif ou Chantier ?",
    'maint.aide_type_body' => <<<'HTML'
<ul class="aide-list">
                <li><i class="fa-solid fa-screwdriver-wrench" style="color:var(--accent);"></i> <b>Curatif</b> : on répare une panne déjà survenue.</li>
                <li><i class="fa-solid fa-calendar-check" style="color:var(--accent);"></i> <b>Préventif</b> : contrôle ou entretien planifié, avant la panne.</li>
                <li><i class="fa-solid fa-helmet-safety" style="color:var(--accent);"></i> <b>Chantier</b> : un projet d'installation, de modification ou d'amélioration.</li>
            </ul>
HTML,

    'maint.aide_prio_title' => "Priorité",
    'maint.aide_prio_sub' => "Normal ou Urgent ?",
    'maint.aide_prio_body' => <<<'HTML'
<ul class="aide-list">
                <li><i class="fa-solid fa-circle-check" style="color:var(--accent);"></i> <b>Normal</b> : intervention classique, à traiter dans l'ordre.</li>
                <li><i class="fa-solid fa-bell" style="color:var(--danger);"></i> <b>Urgent</b> : ligne à l'arrêt ou danger sécurité.</li>
            </ul>
            <div class="aide-callout aide-callout-warn"><i class="fa-solid fa-bell"></i><div>Un ticket « Urgent » clignote en rouge dans le tableau tant qu'il n'est pas pris en charge — réservez ce niveau aux vraies urgences.</div></div>
HTML,

    'maint.aide_casse_title' => "Casse",
    'maint.aide_casse_sub' => "Bris de matériel accidentel",
    'maint.aide_casse_body' => "<p>À cocher si l'intervention fait suite à une mauvaise manipulation ou à un choc accidentel sur le matériel. Cela permet de suivre le taux de casse dans les statistiques.</p>",

    'maint.aide_verif_vis_title' => "Vérification visserie",
    'maint.aide_verif_vis_sub' => "Exigence Qualité / Audit",
    'maint.aide_verif_vis_body' => <<<'HTML'
<p>En cochant cette case, vous certifiez formellement avoir vérifié l'intégrité de la visserie de l'équipement.</p>
            <div class="aide-callout aide-callout-warn"><i class="fa-solid fa-shield-halved"></i><div>Vous vous engagez à avoir remis en place et correctement serré toutes les vis, écrous et fixations démontés durant l'intervention — écartant tout risque de chute de corps étranger.</div></div>
HTML,

    'maint.aide_desc_title' => "Description",
    'maint.aide_desc_sub' => "Le champ le plus lu par vos collègues",
    'maint.aide_desc_body' => <<<'HTML'
<p>Décrivez le symptôme ou la tâche le plus précisément possible.</p>
            <div class="aide-callout aide-callout-tip"><i class="fa-solid fa-thumbs-up"></i><div><b>Exemple utile :</b> « Vérin de poussée bloqué en position haute »</div></div>
            <div class="aide-callout aide-callout-warn"><i class="fa-solid fa-thumbs-down"></i><div><b>À éviter :</b> « En panne »</div></div>
HTML,

    'maint.aide_duree_title' => "Calcul du temps (centièmes)",
    'maint.aide_duree_sub' => "La GMAO utilise les centièmes d'heure",
    'maint.aide_duree_body' => <<<'HTML'
<ul class="aide-list">
                <li><i class="fa-solid fa-clock" style="color:var(--accent);"></i> 15 min = <b>0.25</b></li>
                <li><i class="fa-solid fa-clock" style="color:var(--accent);"></i> 30 min = <b>0.50</b></li>
                <li><i class="fa-solid fa-clock" style="color:var(--accent);"></i> 45 min = <b>0.75</b></li>
                <li><i class="fa-solid fa-clock" style="color:var(--accent);"></i> 1 heure = <b>1.00</b></li>
            </ul>
