    'aide_connexion.accueil_menu_tip' => "Une fois sur les écrans de la GMAO, un bouton rond en haut à gauche (<i class=\"fa-solid fa-bars\"></i>) ouvre à tout moment le menu latéral complet, pour naviguer sans revenir à l'accueil. (Le bouton rond que vous voyez sur cette page d'aide, lui, ramène simplement en arrière.)",
    'aide_connexion.accueil_service_h3' => "Autres services : le Portail Services",
    'aide_connexion.accueil_service_p' => "Avec un compte de <b>service</b> (Production, Qualité, Sécurité, RH, Comptabilité, Logistique, Agronomie...), vous arrivez sur une page à 4 tuiles bien plus simple, pensée pour vos besoins du quotidien : déposer une demande de travaux, suivre son état, proposer une idée d'amélioration, ou consulter l'aide.",
    'aide_connexion.shot_accueil_service_alt' => "Page d'accueil du Portail Services avec ses 4 tuiles",
    'aide_connexion.shot_accueil_service_cap' => "La page d'accueil du Portail Services — 4 tuiles : Nouvelle demande, Suivi, Idées, Aide.",
    'aide_connexion.accueil_service_tip' => "Cette page ne donne accès à aucune fonction de la GMAO elle-même : c'est une porte d'entrée simplifiée, entièrement guidée. Le détail de chaque tuile est expliqué dans <a href=\"aide_service.php\">l'article dédié au portail de demande</a>, accessible aussi depuis la tuile « Aide & questions fréquentes » du portail lui-même.",

