    'aide_kpi.filtres_lede' => "En haut de l'écran KPI, une barre de filtres agit sur toutes les cartes et graphiques en dessous.",
    'aide_kpi.shot_filtres_alt' => "Barre de filtres de l'écran KPI : dates, technicien, bouton filtrer",
    'aide_kpi.shot_filtres_cap' => "DU / AU pour une période, TECHNICIEN pour se concentrer sur une personne, puis FILTRER (ou RAZ pour tout réinitialiser).",
    'aide_kpi.shot_cartes_alt' => "Cinq cartes KPI : total, taux de réalisation, heures cumulées, taux de casse, interventions récurrentes",
    'aide_kpi.shot_cartes_cap' => "Les 5 cartes : Total d'interventions, Taux de réalisation, Heures cumulées, Taux de Casse (Période), Interventions récurrentes. Capture antérieure à la mise à jour du 03/09/2026 — le libellé affiché à l'écran a changé, voir tableau ci-dessous.",
    'aide_kpi.tbl2_carte' => "Carte",
    'aide_kpi.tbl2_repr' => "Ce qu'elle représente",
    'aide_kpi.card_total_nom' => "Total d'interventions",
    'aide_kpi.card_total_desc' => "Nombre de tickets dans la période/le technicien filtré, tous statuts confondus.",
    'aide_kpi.card_taux_nom' => "Taux de réalisation",
    'aide_kpi.card_taux_desc' => "Pourcentage de tickets dont le statut contient « terminé » sur le total filtré.",
    'aide_kpi.card_heures_nom' => "Heures cumulées",
    'aide_kpi.card_heures_desc' => "Somme de tous les pointages du jeu filtré, tous statuts de ticket confondus.",
    'aide_kpi.card_casse_nom' => "Taux de Casse (Période)",
    'aide_kpi.card_casse_desc' => "Part des tickets « Casse » sur la <b>période filtrée</b> (champs DU/AU) — sur tout l'historique si aucun filtre de dates n'est actif. Suit désormais le même filtre que le reste de l'écran.",
    'aide_kpi.card_panne_nom' => "Panne la plus récurrente",
    'aide_kpi.card_panne_desc' => "L'équipement qui revient le plus souvent en <b>curatif ou chantier</b> dans le jeu filtré (le préventif, qui revient par nature tous les jours/semaines, est exclu de ce classement) ; cliquer ouvre un donut du Top 5.",
    'aide_kpi.filtres_footer_p' => "Chaque carte est cliquable et ouvre une fenêtre d'historique détaillé (N° BI, date, équipement, technicien, statut) du jeu de données correspondant.",
    'aide_kpi.graphiques_callout' => "Les captures de cette section datent d'avant la mise à jour du <b>03/09/2026</b> (ajout de la catégorie Chantier et du carrousel décrit ci-dessous). L'écran réel a légèrement changé d'aspect — le texte qui suit décrit le comportement actuel.",
    'aide_kpi.shot_ratio_alt' => "Barre de répartition Curatif / Préventif / Chantier",
    'aide_kpi.shot_ratio_cap' => "Répartition Curatif / Préventif / Chantier du jeu filtré : nombre de BI, pourcentage et heures pointées pour chacune des 3 catégories.",
    'aide_kpi.graphiques_p1' => "Chacune des 3 pastilles (Curatif, Préventif, Chantier) est cliquable et ouvre la liste complète des bons d'intervention de cette catégorie sur le jeu filtré.",
    'aide_kpi.carrousel_h3' => "Le carrousel Curatif / Préventif / Chantier",
    'aide_kpi.carrousel_intro' => "Juste en dessous de cette barre de répartition, une rangée de 3 pastilles + un bouton Pause pilote l'affichage des panneaux <b>« Pannes récurrentes par secteur »</b>, <b>« Pannes récurrentes par équipement »</b> et <b>« Tendance mensuelle des pannes »</b> :",
    'aide_kpi.carrousel_li1' => "Ces 3 panneaux basculent <b>ensemble</b>, automatiquement, toutes les <b>5 secondes</b> : Curatif → Préventif → Chantier → Curatif…",
    'aide_kpi.carrousel_li2' => "Le badge affiché dans l'en-tête de chaque panneau (ex. « Chantier · Top 15 ») indique toujours la catégorie actuellement montrée.",
    'aide_kpi.carrousel_li3' => "Cliquer sur une pastille (Curatif/Préventif/Chantier) bascule immédiatement dessus et relance le minuteur de 5 secondes à partir de ce moment.",
    'aide_kpi.carrousel_li4' => "Le bouton <b>Pause</b> arrête le défilement automatique pour laisser le temps de lire une catégorie précise ; il redevient <b>Reprendre</b> pour relancer le cycle.",
    'aide_kpi.carrousel_p2' => "Dans « Pannes récurrentes par secteur », cliquer sur une ligne ouvre le détail des bons d'intervention de ce secteur — <b>filtré sur la catégorie actuellement affichée</b> par le carrousel (Curatif, Préventif ou Chantier selon ce qui est sélectionné au moment du clic).",
    'aide_kpi.shot_panneaux_alt' => "Panneaux Pannes récurrentes par secteur et par équipement",
    'aide_kpi.shot_panneaux_cap' => "« Pannes récurrentes par secteur » et « Pannes récurrentes par équipement » (Top 15) — le contenu affiché dépend de la catégorie active du carrousel décrit ci-dessus.",
    'aide_kpi.shot_donut_alt' => "Graphique en anneau du Top 5 des équipements en pannes récurrentes",
    'aide_kpi.shot_donut_cap' => "En cliquant sur la carte « Panne la plus récurrente » : Top 5 des équipements (curatif + chantier) + « Autres », cliquable pour voir le détail d'un secteur. Ce donut est indépendant du carrousel — il reste toujours sur curatif + chantier combinés.",
    'aide_kpi.stats_tech_lede' => "Contrairement à KPI, cet écran <b>n'a aucun filtre</b> : les trois graphiques sont fixes, et se lisent en cliquant dessus pour aller plus loin.",
    'aide_kpi.shot_stats_alt' => "Les trois graphiques de l'écran Stats Techniciens",
    'aide_kpi.shot_stats_cap' => "De haut en bas : évolution des heures (7 derniers jours), répartition par technicien (cumul total), répartition Curatif vs Préventif.",
    'aide_kpi.stats_li1' => "<b>Évolution des heures d'intervention</b> : somme des heures pointées par jour, sur une fenêtre fixe de 7 jours glissants — non paramétrable depuis l'écran.",
    'aide_kpi.stats_li2' => "<b>Répartition par Technicien</b> : cumul de toutes les heures pointées <i>depuis l'origine</i> (aucune limite de date), tous statuts de ticket confondus. Cliquer sur une part ouvre la liste des interventions du technicien.",
    'aide_kpi.stats_li3' => "<b>Répartition Curatif vs Préventif</b> : regardez bien la légende de cette carte dans la capture ci-dessus — voir le piège n°4 juste en dessous.",
    'aide_kpi.export_p' => "Il n'existe <b>aucun export global</b> (PDF/Excel) de l'ensemble d'un tableau de bord. Le seul export possible est individuel : en ouvrant le détail d'un ticket depuis une des fenêtres d'historique, le bouton <b>« EXPORTER EN PDF »</b> génère le rapport de ce bon d'intervention précis.",
    'aide_kpi.pieges_h2' => "Pièges de lecture — à connaître avant d'interpréter un chiffre",
    'aide_kpi.pieges_lede' => "Ces tableaux de bord sont fiables, mais quelques comportements méritent d'être connus pour ne pas mal interpréter un chiffre en réunion.",
    'aide_kpi.pf1_title' => "Les panneaux « Pannes récurrentes » changent de catégorie tout seuls",
    'aide_kpi.pf1_desc' => "« Pannes récurrentes par secteur/équipement » et « Tendance mensuelle des pannes » basculent automatiquement entre Curatif, Préventif et Chantier toutes les 5 secondes. Avant de citer un chiffre de ces panneaux, vérifiez le badge affiché (ex. « Chantier ») — ou cliquez sur Pause pour figer l'affichage sur la catégorie voulue.",
    'aide_kpi.pf2_title' => "Les demandes « En attente » non validées sont comptées",
    'aide_kpi.pf2_desc' => "Le Total d'interventions, le Taux de réalisation et les répartitions incluent aussi les demandes pas encore validées par la maintenance, ce qui peut gonfler le volume apparent et faire baisser le taux de réalisation affiché.",
    'aide_kpi.pf3_title' => "Un type mal renseigné compte comme « Curatif »",
    'aide_kpi.pf3_desc' => "Seul un ticket dont le type est exactement « Préventif » ou « Chantier » est compté comme tel — tout le reste (y compris un champ type vide ou mal orthographié) tombe automatiquement en Curatif.",
    'aide_kpi.pf4_title' => "Le camembert « Curatif vs Préventif » de Stats Techniciens est toujours vide",
    'aide_kpi.pf4_desc' => "Ce n'est pas une absence de données réelle : cette fonctionnalité n'est pas finalisée dans le code actuel. Ne concluez jamais « il n'y a jamais eu de préventif » à partir de ce graphique précis — utilisez plutôt la barre Curatif/Préventif de l'écran KPI.",
    'aide_kpi.pf5_title' => "Les heures cumulées mélangent tous les statuts",
    'aide_kpi.pf5_desc' => "Un ticket encore « à faire » sur lequel du temps a déjà été pointé compte pleinement dans les heures cumulées et dans la charge par technicien.",
    'aide_kpi.pf6_title' => "La liste de techniciens du filtre KPI est fixe",
    'aide_kpi.pf6_desc' => "Un technicien créé après coup n'apparaîtra pas dans le menu déroulant « TECHNICIEN » de l'écran KPI, même si ses heures remontent correctement dans le panneau « Charge par Technicien ».",
    'aide_kpi.pf7_title' => "Un technicien à 0h disparaît, plutôt que d'afficher « 0h »",
    'aide_kpi.pf7_desc' => "Le panneau « Charge par Technicien » masque totalement les techniciens sans heures pointées sur la période — une absence dans la liste ne veut pas dire « pas de données », mais bien « zéro heure ».",
    'aide_kpi.pf8_title' => "Deux logiques temporelles différentes entre les deux écrans",
    'aide_kpi.pf8_desc' => "KPI n'a aucune période par défaut (tout l'historique), alors que la courbe de Stats Techniciens est figée sur 7 jours glissants non modifiables — gardez cette différence en tête en passant de l'un à l'autre.",
    'aide_kpi.gloss_taux_dt' => "Taux de réalisation",
    'aide_kpi.gloss_taux_dd' => "Pourcentage de tickets « terminés » sur le total du jeu filtré.",
    'aide_kpi.gloss_pointage_dt' => "Pointage",
    'aide_kpi.gloss_pointage_dd' => "Une ligne de temps passé par un technicien sur un ticket — base de tous les calculs d'heures.",
    'aide_kpi.gloss_panne_dt' => "Panne la plus récurrente",
    'aide_kpi.gloss_panne_dd' => "L'équipement qui revient le plus souvent en curatif ou chantier (pannes/casses) dans les tickets du jeu filtré — le préventif routinier n'est pas compté.",
    'aide_kpi.gloss_chantier_dt' => "Chantier",
    'aide_kpi.gloss_chantier_dd' => "Troisième catégorie de bon d'intervention, à côté de Curatif et Préventif : un projet d'installation, de modification ou d'amélioration (par opposition à une panne réparée ou un contrôle planifié).",
    'aide_kpi.devnote_summary' => "Note technique (équipe admin / dev)",
    'aide_kpi.devnote_li1' => "<code>stats_tech.php</code> : la requête <code>\$sql3</code> (répartition Curatif/Préventif) est commentée dans le code et <code>dataTypes</code> codé en dur à <code>[0, 0]</code> — le graphique correspondant n'affichera jamais de données tant que ça n'est pas raccordé.",
    'aide_kpi.devnote_li2' => "<code>api.php</code> renvoie toutes les tâches sans filtrer le statut <code>En attente</code>, y compris pour les écrans KPI/Stats — contrairement à ce que suggère le filtre partiel présent (mais inopérant) dans <code>maintenance.php</code>.",

