    'aide_utilisateurs.champ7_d' => "Facultatif — voir la section dédiée.",
    'aide_utilisateurs.creer_footer' => "Le compte créé est <b>toujours actif</b> dès le départ. Si l'identifiant existe déjà : « Erreur : L'identifiant existe déjà. »",
    'aide_utilisateurs.modifier_lede' => "Cliquez sur n'importe quelle carte utilisateur pour ouvrir sa fiche complète. Les champs affichés s'adaptent selon qu'il s'agit d'un compte « portail » (mot de passe) ou « employé » (PIN) : Service/Rôle, Fonction, Email, Téléphone, et selon le cas, mot de passe ou Prénom + Code PIN, ainsi que l'état du compte (actif/désactivé).",
    'aide_utilisateurs.modifier_p2' => "Bouton <b>« METTRE À JOUR »</b> pour valider, icône <b>poubelle</b> pour supprimer, <b>« FERMER »</b> pour quitter sans rien changer.",
    'aide_utilisateurs.mdp_lede' => "Il n'y a pas de bouton « Réinitialiser » séparé : ouvrez la fiche du compte, saisissez la nouvelle valeur dans <b>« Nouveau Mot de passe (Portail) »</b>, puis « METTRE À JOUR ».",
    'aide_utilisateurs.mdp_tip' => "Le champ est <b>facultatif</b> à la modification : si vous le laissez vide (« Laisser vide si inchangé »), le mot de passe existant n'est pas touché.",
    'aide_utilisateurs.pin_lede' => "C'est le code que les employés/opérateurs saisissent pour se faire reconnaître dans le portail de demande de travaux.",
    'aide_utilisateurs.pin_tip' => "<b>Mémorisation automatique :</b> si vous créez un compte employé sans code PIN, ce n'est pas bloquant. La première fois que cette personne saisit un code dans le portail de demande, l'application <b>l'enregistre automatiquement</b> comme son code personnel définitif. Vous pouvez ensuite le consulter ou le modifier ici à tout moment.",
    'aide_utilisateurs.pin_warn' => "Contrairement au mot de passe (toujours masqué et chiffré), le <b>code PIN est visible en clair</b> — dans la fiche d'édition et sous forme de badge rouge directement sur la mini-carte de l'employé. C'est un niveau de sécurité volontairement plus léger, adapté à un simple code d'identification, pas à un vrai mot de passe.",
    'aide_utilisateurs.activer_lede' => "Dans la fiche d'édition, le champ <b>« État du compte »</b> propose deux valeurs : <b>« [ V ] COMPTE ACTIF (Accès autorisé) »</b> ou <b>« [ X ] COMPTE DÉSACTIVÉ (Accès bloqué) »</b>.",
    'aide_utilisateurs.activer_warn' => "Un compte désactivé ne peut plus du tout se connecter (message « Accès refusé : Ce compte a été désactivé. »), mais reste visible ici pour être réactivé plus tard. <b>Aucun badge visuel</b> ne signale un compte désactivé directement sur les cartes de la liste — il faut ouvrir chaque fiche pour vérifier son état.",
    'aide_utilisateurs.supprimer_lede' => "Icône poubelle dans la fiche d'édition, avec une simple confirmation.",
    'aide_utilisateurs.supprimer_warn' => "<b>Suppression définitive</b>, sans vérification des données liées. L'historique (bons d'intervention, journal, plannings passés) reste affiché avec l'ancien nom, mais le compte n'existe plus — il ne pourra plus se reconnecter, et il devient impossible de lui réattribuer quoi que ce soit. Rien n'empêche non plus un administrateur de se rétrograder ou de se supprimer <b>lui-même</b> : il n'y a pas de protection « dernier admin ».",
    'aide_utilisateurs.securite_li1' => "<b>Le mot de passe est toujours chiffré</b> avant d'être stocké — jamais lisible, ni par vous, ni par personne.",
    'aide_utilisateurs.securite_li2' => "<b>Le code PIN, lui, est stocké et affiché en clair</b> — ne l'utilisez jamais comme un vrai mot de passe sensible.",
    'aide_utilisateurs.securite_li3' => "<b>Aucune action de cette page n'est journalisée</b> : créer, modifier, désactiver ou supprimer un compte ne laisse aucune trace dans le <a href=\"aide_logs.php\">Journal d'activité</a>.",
    'aide_utilisateurs.securite_li4' => "L'<b>objectif d'heures annuel</b> d'un technicien (utilisé dans le Planning) ne se règle pas ici — il se modifie directement depuis le <a href=\"aide_planning.php\">Planning annuel</a> de la personne concernée.",
    'aide_utilisateurs.droits_action' => "Action",
    'aide_utilisateurs.droits_tech' => "Technicien",
    'aide_utilisateurs.droits_admin' => "Admin",
    'aide_utilisateurs.droits1' => "Accéder à la page",
    'aide_utilisateurs.droits2' => "Créer / modifier / supprimer un compte",
    'aide_utilisateurs.droits3' => "Changer un mot de passe ou un PIN",
    'aide_utilisateurs.astuces_li1' => "<b>Pensez à vérifier l'état actif/inactif</b> avant de supposer qu'un compte bloqué est visible d'un coup d'œil — il ne l'est pas.",
    'aide_utilisateurs.astuces_li2' => "<b>Laissez le code PIN vide à la création</b> d'un nouvel employé si vous ne le connaissez pas : il se mémorisera tout seul dès sa première demande.",
    'aide_utilisateurs.astuces_li3' => "<b>Ne cherchez pas l'objectif d'heures annuel ici</b> — c'est dans le Planning.",
    'aide_utilisateurs.astuces_li4' => "<b>Réfléchissez avant de supprimer</b> un compte ayant un historique important : préférez le désactiver, c'est réversible.",
    'aide_utilisateurs.gloss1_dt' => "Compte portail",
    'aide_utilisateurs.gloss1_dd' => "Compte protégé par mot de passe (équipe maintenance ou service).",
    'aide_utilisateurs.gloss2_dt' => "Compte employé / opérateur",
    'aide_utilisateurs.gloss2_dd' => "Compte identifié par un code PIN, utilisé côté portail de demande.",
    'aide_utilisateurs.gloss3_dt' => "Code PIN",
    'aide_utilisateurs.gloss3_dd' => "Code personnel numérique, stocké en clair, qui identifie un demandeur.",
    'aide_utilisateurs.gloss4_dt' => "Mémorisation automatique",
    'aide_utilisateurs.gloss4_dd' => "Le PIN se définit tout seul dès la première saisie de l'employé s'il n'était pas encore renseigné.",
    'aide_utilisateurs.devnote_intro' => "Points relevés en analysant le code, à garder en tête côté administration :",
    'aide_utilisateurs.devnote_li1' => "Le champ mot de passe est un <code>&lt;input type=\"text\"&gt;</code> dans les deux modales (pas <code>type=\"password\"</code>) — la saisie n'est donc pas masquée à l'écran.",
    'aide_utilisateurs.devnote_li2' => "Aucun appel à <code>ajouterLog()</code> dans ce fichier : contrairement à <code>login.php</code> ou <code>parametres.php</code>, aucune action d'administration des comptes n'est tracée dans <code>logs.php</code>.",
    'aide_utilisateurs.devnote_li3' => "La suppression (<code>DELETE FROM utilisateurs</code>) ne vérifie aucune dépendance — les tickets/logs référencent l'utilisateur par son <code>username</code> en texte libre, pas par clé étrangère, donc rien ne bloque techniquement la suppression.",
    'aide_utilisateurs.devnote_li4' => "Aucune protection « dernier admin » ni « ne pas se modifier soi-même ».",

    // --- aide_logs.php ---
    'aide_logs.page_title_tag' => "Consulter le Journal d'activité - Aide GMAO",
    'aide_logs.hero_tagline' => "Qui a fait quoi, et quand — l'historique des actions importantes de la GMAO.",
    'aide_logs.pill_version' => "Version <b>1.0</b>",
    'aide_logs.pill_updated' => "Mis à jour le <b>20/08/2026</b>",
    'aide_logs.pill_ecran' => "Écran concerné <b>Journal d'activité</b>",
    'aide_logs.toc_vue_ensemble' => "Vue d'ensemble",
    'aide_logs.toc_lire' => "Lire une ligne du journal",
    'aide_logs.toc_quoi' => "Ce qui est (et n'est pas) journalisé",
    'aide_logs.toc_filtrer' => "Filtrer et rechercher",
    'aide_logs.toc_limites' => "Limites à connaître",
    'aide_logs.toc_vider' => "Vider le journal",
    'aide_logs.toc_droits' => "Qui peut faire quoi",
    'aide_logs.toc_astuces' => "Astuces & pièges",
    'aide_logs.toc_glossaire' => "Glossaire",
    'aide_logs.vue_ensemble_lede' => "Le <b>Journal d'activité</b> affiche, sous forme de tableau, l'historique des actions importantes réalisées dans la GMAO : qui a fait quoi, et à quel moment. C'est l'outil à consulter en cas de doute sur « qui a modifié ça ? » ou « quand cette machine a-t-elle été ajoutée ? ».",
    'aide_logs.vue_ensemble_lock' => "Cette page est <b>entièrement réservée aux administrateurs</b>. Un technicien ou un membre de la maintenance n'y a pas accès et ne voit même pas la tuile sur l'accueil.",
    'aide_logs.lire_lede' => "Chaque ligne du tableau correspond à un événement, avec 4 colonnes.",
    'aide_logs.col_colonne' => "Colonne",
    'aide_logs.col_contenu' => "Contenu",
    'aide_logs.col1_nom' => "Date & Heure",
    'aide_logs.col1_desc' => "Horodatage exact de l'action, au format <code>jj/mm/aaaa hh:mm</code> (ex. <code>20/08/2026 14:32</code>).",
    'aide_logs.col2_nom' => "Utilisateur",
    'aide_logs.col2_desc' => "Le nom de la personne connectée qui a réalisé l'action.",
    'aide_logs.col3_nom' => "Action",
    'aide_logs.col3_desc' => "Un libellé court affiché dans un badge coloré (voir plus bas), ex. « Ajout Machine », « Paramètres », « Connexion ».",
    'aide_logs.col4_nom' => "Détails",
    'aide_logs.col4_desc' => "Une description en texte libre qui précise l'action, ex. « A ajouté la machine : Convoyeur B12 ».",
    'aide_logs.badges_intro' => "La couleur du badge « Action » dépend de mots-clés détectés dans son libellé :",
    'aide_logs.badge_add_label' => "Ajout / création",
    'aide_logs.badge_add_suffix' => "— badge vert",
    'aide_logs.badge_edit_label' => "Modification",
    'aide_logs.badge_edit_suffix' => "— badge bleu",
    'aide_logs.badge_delete_label' => "Suppression",
    'aide_logs.badge_delete_suffix' => "— badge rouge",
    'aide_logs.badge_login_label' => "Connexion",
    'aide_logs.badge_login_suffix' => "— badge orange",
    'aide_logs.badge_default_label' => "Autre",
    'aide_logs.badge_default_suffix' => "— badge gris, pour tout événement qui ne correspond à aucun des cas ci-dessus",
    'aide_logs.lire_footer' => "Les entrées sont triées <b>de la plus récente à la plus ancienne</b>, sans possibilité de changer ce tri.",
    'aide_logs.quoi_lede' => "Le journal ne couvre pas toute l'application — seules certaines actions, jugées importantes à tracer, y sont enregistrées.",
    'aide_logs.trace_tag' => "Tracé",
    'aide_logs.trace_h3' => "Ce qui apparaît dans le journal",
    'aide_logs.trace_li1' => "Les connexions à l'application",
    'aide_logs.trace_li2' => "Les ajouts et modifications de machines (Parc Machine)",
    'aide_logs.trace_li3' => "Les idées d'amélioration proposées et leur traitement",
    'aide_logs.trace_li4' => "Les imports de planning",
    'aide_logs.trace_li5' => "Toute modification faite depuis la page <b>Paramètres</b> : catégories, statuts, tuiles d'accueil, habillage du planning, objectifs annuels, etc.",
    'aide_logs.non_trace_tag' => "Non tracé",
    'aide_logs.non_trace_h3' => "Ce qui n'apparaît pas",
    'aide_logs.non_trace_li1' => "La création, la prise en charge ou la clôture d'un bon d'intervention (BI)",
    'aide_logs.non_trace_li2' => "Les saisies du Planning (postes, congés, heures...)",
    'aide_logs.non_trace_li3' => "<b>Les déconnexions</b> — seule la connexion est enregistrée",
    'aide_logs.non_trace_li4' => "Le vidage du journal lui-même (voir plus bas)",
    'aide_logs.quoi_warn' => "Ne comptez pas sur ce journal pour retracer l'historique d'un bon d'intervention ou d'un pointage — utilisez plutôt la fiche détaillée du BI concerné (voir <a href=\"aide_ot.php\">le guide des BI</a>), qui garde son propre historique de statuts et de rapports.",
    'aide_logs.filtrer_lede' => "Trois filtres, combinables entre eux, permettent de retrouver rapidement une entrée précise. Ils agissent instantanément, sans recharger la page.",
    'aide_logs.shot_filtres_alt' => "Barre de filtres du Journal d'activité : utilisateur, action, recherche",
    'aide_logs.shot_filtres_cap' => "La barre de filtres en haut du tableau, et le bouton RAZ pour tout réinitialiser.",
    'aide_logs.case_user_h4' => "Utilisateur",
    'aide_logs.case_user_p' => "Tapez un nom (ou une partie de nom) pour ne garder que les entrées de cette personne.",
    'aide_logs.case_action_h4' => "Action",
    'aide_logs.case_action_p' => "Liste déroulante : Toutes les actions / Ajouts / Créations / Modifications / Suppressions / Connexions.",
    'aide_logs.case_recherche_h4' => "Recherche",
    'aide_logs.case_recherche_p' => "Cherche un mot-clé dans la colonne Détails uniquement (ex. le nom d'une machine).",
    'aide_logs.filtrer_footer' => "Le bouton <b>« RAZ »</b> réinitialise les trois filtres d'un coup et réaffiche toutes les lignes chargées.",
    'aide_logs.limites_li1' => "<b>Seules les 200 entrées les plus récentes</b> sont chargées et affichées. Au-delà, l'historique plus ancien reste stocké en base mais n'apparaît plus à l'écran.",
    'aide_logs.limites_li2' => "<b>Aucun export</b> (PDF, Excel, CSV) n'est disponible depuis cette page.",
    'aide_logs.limites_li3' => "<b>Aucune purge automatique</b> par ancienneté : les entrées s'accumulent indéfiniment jusqu'à un vidage manuel (voir ci-dessous).",
    'aide_logs.vider_lede' => "Le bouton rouge <b>« VIDER LE JOURNAL »</b>, en haut à droite, supprime <b>l'intégralité</b> de l'historique.",
    'aide_logs.vider_step1_title' => "Cliquez sur « VIDER LE JOURNAL »",
    'aide_logs.vider_step1_desc' => "Une fenêtre de confirmation s'ouvre : « Vider le journal ? — Êtes-vous sûr de vouloir vider TOUT le journal des logs ? Cette action est définitive et irréversible. »",
    'aide_logs.vider_step2_title' => "Confirmez avec « TOUT VIDER »",
    'aide_logs.vider_step2_desc' => "Toutes les entrées sont supprimées immédiatement. Le bouton « ANNULER » ferme la fenêtre sans rien faire.",
    'aide_logs.vider_warn' => "<b>Action définitive :</b> une fois confirmée, il n'existe aucun moyen de récupérer l'historique effacé — ni sauvegarde automatique, ni corbeille. Et par ironie, cette suppression totale n'est elle-même pas journalisée : après un vidage, il n'y a plus aucune trace de qui a vidé le journal ni quand.",
    'aide_logs.droits_action' => "Action",
    'aide_logs.droits_tech' => "Technicien",
    'aide_logs.droits_admin' => "Admin",
    'aide_logs.droits1' => "Accéder à la page",
    'aide_logs.droits2' => "Filtrer / rechercher",
    'aide_logs.droits3' => "Vider le journal",
    'aide_logs.astuces_li1' => "<b>Ne cherchez pas les déconnexions</b> : elles ne sont jamais enregistrées, seule la connexion l'est.",
    'aide_logs.astuces_li2' => "<b>Ne cherchez pas l'historique d'un BI ou d'un pointage</b> ici — ce n'est pas ce que ce journal trace. Reportez-vous à la fiche du BI concerné.",
    'aide_logs.astuces_li3' => "<b>Réfléchissez avant de vider le journal</b> : c'est irréversible, et l'action de vidage elle-même ne laisse aucune trace derrière elle.",
    'aide_logs.astuces_li4' => "<b>Combinez les filtres</b> pour retrouver vite une entrée précise, par exemple « Utilisateur = Dupont » + « Action = Modifications » pour voir tout ce qu'il a modifié récemment.",
    'aide_logs.gloss1_dt' => "Journal d'activité",
    'aide_logs.gloss1_dd' => "Le tableau qui liste les actions importantes réalisées dans la GMAO, avec date, auteur et détails.",
    'aide_logs.gloss2_dt' => "Action",
    'aide_logs.gloss2_dd' => "Le type d'événement enregistré (ajout, modification, suppression, connexion...).",
    'aide_logs.gloss3_dt' => "Détails",
    'aide_logs.gloss3_dd' => "La description en texte libre qui accompagne chaque entrée du journal.",
    'aide_logs.gloss4_dt' => "Purge / vidage",
    'aide_logs.gloss4_dd' => "La suppression totale et irréversible de tout l'historique du journal.",
    'aide_logs.devnote_intro' => "Points relevés en analysant le code, à garder en tête côté administration :",
    'aide_logs.devnote_li1' => "La journalisation (<code>ajouterLog()</code> dans <code>db.php</code>) avale silencieusement toute erreur SQL (try/catch vide) « pour ne pas bloquer l'application » — une écriture de log peut donc échouer sans qu'aucune alerte ne le signale.",
    'aide_logs.devnote_li2' => "La création/clôture des BI et les saisies du Planning n'appellent pas <code>ajouterLog()</code> : seuls Parc Machine, Idées, Import Planning, Paramètres et la connexion le font.",
    'aide_logs.devnote_li3' => "Le vidage du journal (<code>logs.php?action=clear</code>) est déclenché par un simple lien GET protégé uniquement par la vérification de rôle en session — pas de jeton CSRF. À durcir si un jour cette page est exposée plus largement.",

