    'aide_parametres.vue_ensemble_lede' => "<b>Paramètres</b> centralise tous les réglages de la GMAO, répartis en 7 onglets. C'est ici que vous alimentez les listes utilisées partout ailleurs — types d'équipement, services, statuts, couleurs du planning, tuiles de l'accueil.",
    'aide_parametres.vue_ensemble_tip' => "La plupart des listes de cette page se réordonnent avec des <b>flèches Monter / Descendre</b> sur chaque ligne (pas de glisser-déposer ici), et ne proposent <b>aucune recherche</b> — vous parcourez la liste entière à l'œil.",
    'aide_parametres.general_h2' => "Onglet Général",
