    'aide_parametres.general_champ2_nom' => "Logo",
    'aide_parametres.general_champ2_d' => "PNG, JPG, SVG ou WEBP uniquement. Remplace le logo de l'en-tête et du menu.",
    'aide_parametres.types_h2' => "Onglet Types d'équipement",
    'aide_parametres.types_lede' => "La liste utilisée pour classer les machines du <a href=\"aide_parc_machine.php\">Parc Machine</a> (Mécanique, Électrique, Froid...).",
    'aide_parametres.types_step1_title' => "Ajouter",
