    'aide_parametres.types_step3_title' => "Supprimer",
    'aide_parametres.types_step3_desc' => "<b>Bloqué</b> si au moins une machine utilise encore ce type : « Impossible de supprimer : ce type est encore utilisé par au moins une machine. »",
    'aide_parametres.services_h2' => "Onglet Services",
