    'aide_parametres.services_row1_action' => "Ajouter",
    'aide_parametres.services_row1_regle' => "Un seul champ : le nom. Une clé technique interne est générée automatiquement et ne change plus jamais.",
    'aide_parametres.services_row2_action' => "Modifier",
    'aide_parametres.services_row2_regle' => "Seul le libellé affiché peut changer, pas la clé technique.",
    'aide_parametres.services_row3_action' => "Supprimer",
    'aide_parametres.services_row3_regle' => "<b>Bloqué</b> si au moins un compte utilisateur a ce service comme rôle.",
    'aide_parametres.categories_h2' => "Onglet Catégories de préventif",
    'aide_parametres.categories_lede' => "Les catégories qui classent les gammes de maintenance préventive (Process, Qualité, Réglementaire, Quotidien par défaut).",
    'aide_parametres.categories_p' => "Formulaire d'ajout/modification : Nom, Description (affichée sur la vignette d'accueil du module Préventif), Icône (grille de 20) et Couleur (30 couleurs prédéfinies + une pipette pour choisir n'importe quelle teinte).",
    'aide_parametres.categories_warn' => "Double protection à la suppression : <b>impossible de descendre sous 1 catégorie</b> restante, et <b>bloqué</b> si la catégorie est encore utilisée par au moins une règle préventive.",
    'aide_parametres.statuts_h2' => "Onglet Statuts & priorités",
    'aide_parametres.statuts_lede' => "Renomme et recolore l'affichage des statuts (En attente, À faire, En cours, Terminée, Refusée) et des priorités (Normal, Urgent) <b>dans toute l'application</b>.",
    'aide_parametres.statuts_lock' => "C'est un ensemble <b>fermé</b> : il n'y a ni bouton « Ajouter » ni bouton « Supprimer » sur cet onglet. Seuls le <b>libellé</b> et la <b>couleur</b> de chaque statut/priorité existant sont modifiables — la valeur réellement enregistrée sur chaque intervention, elle, ne change jamais. C'est purement de l'habillage visuel.",
    'aide_parametres.statuts_tip' => "Tant que vous ne touchez qu'à la <b>couleur</b> (le champ libellé reste tel qu'il était pré-rempli), l'affichage continue de suivre automatiquement la langue choisie par chaque utilisateur (FR/EN/NL). Dès que vous <b>tapez un nouveau texte</b> dans le libellé, ce texte remplace la traduction automatique et s'affiche à l'identique dans toutes les langues.",
    'aide_parametres.planning_h2' => "Onglet Planning",
    'aide_parametres.planning_lede' => "Le plus riche des 7 onglets : l'habillage du <a href=\"aide_planning.php\">Planning</a>, les objectifs d'heures annuels, et les outils d'import/réinitialisation.",
    'aide_parametres.shot_planning_alt' => "Onglet Planning de Paramètres : pastilles de couleur des postes et événements",
    'aide_parametres.shot_planning_cap' => "L'onglet Planning : chaque poste/événement a sa pastille de couleur et son bouton Modifier — la liste elle-même est fermée.",
    'aide_parametres.planning_h3_listes' => "Postes, Événements, Astreintes",
    'aide_parametres.planning_listes_p' => "Trois listes fermées (mêmes règles que Statuts & priorités : seuls libellé et couleur sont modifiables, pas d'ajout/suppression) :",
    'aide_parametres.planning_li_postes' => "<b>Postes</b> : Matin, Après-midi, Nuit, Journée, Jour férié.",
    'aide_parametres.planning_li_evenements' => "<b>Événements</b> : Demi-congé payé, Congé payé, Maladie, RTT, Repos.",
    'aide_parametres.planning_li_astreintes' => "<b>Astreintes</b> : Astreinte, Astreinte froid.",
    'aide_parametres.planning_h3_objectifs' => "Objectifs annuels d'heures",
    'aide_parametres.planning_objectifs_p' => "Une liste de tous les techniciens avec leur objectif d'heures actuel (1607h par défaut). Modifiable individuellement — utile pour un temps partiel. C'est le même réglage que celui accessible directement depuis le <a href=\"aide_planning.php\">Planning annuel</a> d'un technicien.",
    'aide_parametres.planning_h3_import' => "Import et réinitialisation du planning",
    'aide_parametres.reset_planning_tag' => "Destructif",
    'aide_parametres.reset_planning_h3' => "Réinitialiser le planning",
    'aide_parametres.reset_planning_p' => "Supprime <b>tout</b> ce qui a été importé (postes, astreintes, heures, notes), toutes périodes confondues. Irréversible.",
    'aide_parametres.reset_heures_tag' => "Destructif, plus ciblé",
    'aide_parametres.reset_heures_h3' => "Réinitialiser les heures",
    'aide_parametres.reset_heures_p' => "Remet uniquement les <b>heures</b> à zéro, en conservant postes, astreintes et notes déjà affichés. Irréversible aussi, mais bien moins radical.",
    'aide_parametres.planning_warn' => "Ne confondez pas les deux boutons : « Réinitialiser le planning » efface tout, « Réinitialiser les heures » ne touche qu'aux heures. Les deux sont <b>définitifs</b>, sans sauvegarde automatique.",
    'aide_parametres.tuiles_h2' => "Onglet Tuiles d'accueil",
    'aide_parametres.tuiles_lede' => "Personnalise le titre, la description et la couleur de chaque tuile affichée sur la page d'accueil.",
    'aide_parametres.tuiles_fixes_h4' => "Les 13 tuiles fixes",
    'aide_parametres.tuiles_fixes_p' => "Saisie & Historique, Planning, Sous-traitants, Préventif, Stats Technicien, KPI, Parc Machine, Gestion Utilisateurs, Idées reçues, Paramètres, Journal d'activité, Portail Services, Aide. Chacune a un titre et une couleur par défaut, remplaçables ici.",
    'aide_parametres.dossiers_h4' => "Mes dossiers",
    'aide_parametres.dossiers_p' => "Les dossiers personnels que <b>vous</b> avez créés sur votre propre accueil (bouton « + Ajouter » depuis l'accueil, pas depuis Paramètres). Cet onglet ne permet que de <b>modifier</b> un dossier existant — titre, description, icône, couleur — et il est propre à votre compte, invisible pour les autres admins.",
    'aide_parametres.tuiles_tip' => "Toute personnalisation enregistrée ici <b>remplace</b> le titre/description/couleur par défaut d'une tuile, pour tous les utilisateurs de l'application.",
    'aide_parametres.droits_action' => "Action",
    'aide_parametres.droits_tech' => "Technicien",
    'aide_parametres.droits_admin' => "Admin",
    'aide_parametres.droits1' => "Accéder à la page",
    'aide_parametres.droits2' => "Modifier n'importe quel onglet",
    'aide_parametres.astuces_li1' => "<b>Statuts, priorités, postes, événements et astreintes forment des listes fermées</b> : vous ne pouvez que les renommer/recolorer, jamais en ajouter ou en supprimer.",
    'aide_parametres.astuces_li2' => "<b>Renommer un type d'équipement ou un statut ne casse rien</b> — les machines et interventions déjà classées suivent automatiquement.",
    'aide_parametres.astuces_li3' => "<b>Vérifiez bien lequel des deux boutons planning vous cliquez</b> : « heures » (ciblé) ou « planning » (tout effacer) — les deux sont irréversibles.",
    'aide_parametres.astuces_li4' => "<b>Il n'existe pas de recherche</b> sur cette page : pour une longue liste (beaucoup de types ou de catégories), il faut la parcourir manuellement.",
    'aide_parametres.astuces_li5' => "<b>Une catégorie de préventif ne peut jamais descendre à zéro</b> — il en restera toujours au moins une, même si elle est inutilisée.",
    'aide_parametres.gloss1_dt' => "Habillage",
    'aide_parametres.gloss1_dd' => "Le libellé et la couleur affichés pour un statut, une priorité ou une case du planning — purement visuel, sans changer la donnée réelle enregistrée.",
    'aide_parametres.gloss2_dt' => "Ensemble fermé",
    'aide_parametres.gloss2_dd' => "Une liste dont les éléments sont fixes (pas d'ajout/suppression possible), seuls leur nom et leur couleur sont réglables.",
    'aide_parametres.gloss3_dt' => "Tuile",
    'aide_parametres.gloss3_dd' => "Un des blocs cliquables de la page d'accueil, chacun menant à une fonction de la GMAO.",
    'aide_parametres.gloss4_dt' => "Objectif annuel",
    'aide_parametres.gloss4_dd' => "Le nombre d'heures qu'un technicien doit atteindre sur la période d'annualisation, réglable ici ou depuis le Planning.",
    'aide_parametres.devnote_intro' => "Points relevés en analysant le code, à garder en tête côté administration :",
    'aide_parametres.devnote_li1' => "Le compte <code>Directeur</code> est explicitement exclu de la liste des objectifs d'heures annuels modifiables (exclusion en dur dans le code).",
    'aide_parametres.devnote_li2' => "Le texte de l'onglet Tuiles annonce « l'icône n'est pas modifiable ici » pour les tuiles fixes, mais la modale et le traitement serveur <code>edit_tuile</code> acceptent et persistent bien un changement d'icône — incohérence texte/comportement à corriger ou à assumer.",
    'aide_parametres.devnote_li3' => "L'ancien fichier logo n'est jamais supprimé du disque lors d'un remplacement (accumulation de fichiers <code>logo_&lt;timestamp&gt;.&lt;ext&gt;</code> dans <code>img/</code>).",
    'aide_parametres.devnote_li4' => "Toute modification réussie sur cette page est journalisée (<code>ajouterLog</code>, action « Paramètres »), visible dans le <a href=\"aide_logs.php\">Journal d'activité</a>.",

    // --- aide_preventif.php ---
    'aide_preventif.page_title_tag' => "Préventif & Planning - Aide GMAO",
    'aide_preventif.hero_tagline' => "Programmer une gamme de contrôle, comprendre sa mise en BI automatique, et lire le planning de la semaine.",
    'aide_preventif.pill_version' => "Version <b>1.0</b>",
    'aide_preventif.pill_updated' => "Mis à jour le <b>08/08/2026</b>",
    'aide_preventif.pill_ecrans' => "Écrans concernés <b>Préventif</b> & <b>Planning</b>",
    'aide_preventif.toc_vue_ensemble' => "Vue d'ensemble & accès",
    'aide_preventif.toc_liste' => "La liste des règles",
    'aide_preventif.toc_creer' => "Créer une règle préventive",
    'aide_preventif.toc_travaux_divers' => "L'onglet « Travaux Hiver »",
    'aide_preventif.toc_generation' => "De la règle au BI",
    'aide_preventif.toc_gestion' => "Modifier, mettre en pause, supprimer",
    'aide_preventif.toc_planning' => "Lire & utiliser le Planning",
    'aide_preventif.toc_astuces' => "Astuces & pièges",
    'aide_preventif.toc_glossaire' => "Glossaire",
    'aide_preventif.vue_ensemble_lede' => "Deux écrans complémentaires : <b>Préventif</b> pour programmer les contrôles récurrents (graissage, inspections réglementaires, vérifications…), et <b>Planning</b> pour visualiser qui fait quoi, jour par jour.",
    'aide_preventif.tbl_ecran' => "Écran",
    'aide_preventif.tbl_qui' => "Qui y accède",
    'aide_preventif.tbl_pourquoi' => "Pour quoi faire",
    'aide_preventif.row_preventif_ecran' => "Préventif",
    'aide_preventif.row_preventif_pourquoi' => "Créer, modifier, mettre en pause ou supprimer une règle de maintenance préventive.",
    'aide_preventif.row_planning_ecran' => "Planning",
    'aide_preventif.row_planning_pourquoi' => "Consulter et réorganiser les tâches de la semaine par technicien.",
    'aide_preventif.vue_ensemble_lock' => "Si vous êtes technicien, l'onglet « Préventif » n'apparaît même pas dans votre menu — c'est normal, seule la maintenance/l'administration programme les gammes. En revanche, vous voyez et utilisez le Planning normalement.",
    'aide_preventif.liste_lede' => "L'écran Préventif affiche toutes les gammes existantes, avec leur fréquence et leur échéance.",
    'aide_preventif.shot_liste_alt' => "Liste des règles de maintenance préventive avec compteurs et filtres",
    'aide_preventif.shot_liste_cap' => "En haut : compteurs (règles actives, en retard, échéance proche). Chips de filtre : Tous / En retard / Bientôt / À jour / En pause.",
    'aide_preventif.liste_li1' => "Un clic sur une ligne ouvre la fiche détaillée de la règle (lecture seule, avec un bouton « Modifier »).",
    'aide_preventif.liste_li2' => "Le bouton <b>« Registre imprimable »</b> génère une vue imprimable de l'ensemble du programme préventif.",
    'aide_preventif.liste_li3' => "Le bouton <b>« Historique »</b> d'une règle liste tous les BI déjà générés à partir d'elle.",
    'aide_preventif.creer_lede' => "Le bouton <b>« NOUVELLE RÈGLE »</b> ouvre un assistant en 4 étapes.",
    'aide_preventif.creer_tip' => "Pour une demande ponctuelle (une seule fois, pas de récurrence), n'utilisez pas cet assistant : le bouton <b>« Vers le préventif »</b> du <a href=\"aide_ot.php#portes\">sas de validation</a> l'ajoute directement à l'onglet <a href=\"#travaux-divers\">« Travaux Hiver »</a> ci-dessous, sans créer de règle.",
    'aide_preventif.step1_title' => "Quoi & Quand",
    'aide_preventif.step1_desc' => "Type d'opération, priorité, puis le <b>mode de planification</b> : soit une <b>fréquence en jours</b> (quotidien, hebdo, 15 jours, mensuel, trimestriel, semestriel, annuel), soit des <b>jours de la semaine</b> fixes (lundi à vendredi). Ajoutez la durée estimée et, si besoin, une échéance butoir et une alerte anticipée.",
    'aide_preventif.step2_title' => "Localisation",
    'aide_preventif.step2_desc' => "Même cascade que pour un BI classique : Usine → Secteur → Ligne → Zone → Équipement. La machine doit exister dans le Parc Machine.",
    'aide_preventif.step3_title' => "Impact & Équipe",
    'aide_preventif.step3_desc' => "Impact sur la production (aucun, arrêt total, réduction de cadence, impact qualité, risque sécurité), durée d'arrêt, déclarant, et surtout le <b>technicien intervenant</b> — c'est lui qui recevra automatiquement les BI générés sur son planning. Alternative : la case <b>« Assigner automatiquement au technicien du poste Matin »</b> ignore l'intervenant fixe et choisit, à chaque génération, la personne au poste « Matin » ce jour-là dans le <a href=\"planning.php\">Planning</a> — pratique pour une tâche qui doit toujours revenir à celui qui est présent le matin, quel qu'il soit.",
    'aide_preventif.step4_title' => "Détails",
    'aide_preventif.step4_desc' => "Description précise de l'opération (obligatoire), cause identifiée, pièces utilisées, commentaires, puis un récapitulatif avant validation.",
    'aide_preventif.shot_e1_alt' => "Assistant nouvelle règle préventive, étape 1 Quoi et Quand",
    'aide_preventif.shot_e1_cap' => "Étape 1 — Quoi & Quand",
    'aide_preventif.shot_e2_alt' => "Assistant nouvelle règle préventive, étape 2 Localisation",
    'aide_preventif.shot_e2_cap' => "Étape 2 — Localisation",
    'aide_preventif.shot_e3_alt' => "Assistant nouvelle règle préventive, étape 3 Impact et Équipe",
    'aide_preventif.shot_e3_cap' => "Étape 3 — Impact & Équipe",
    'aide_preventif.shot_e4_alt' => "Assistant nouvelle règle préventive, étape 4 Détails et récapitulatif",
    'aide_preventif.shot_e4_cap' => "Étape 4 — Détails & récapitulatif",
    'aide_preventif.creer_warn' => "Sans <b>technicien intervenant</b> renseigné à l'étape 3 — ou si « Auto matin » est cochée mais que personne n'est au poste Matin ce jour-là —, les BI générés par cette règle <b>n'apparaîtront pas sur le Planning</b> (ils resteront visibles uniquement dans les listes de tickets classiques). Pensez toujours à assigner un intervenant si vous voulez que la tâche soit planifiée.",
    'aide_preventif.travaux_lede' => "Sur la page d'une catégorie, un deuxième onglet à côté de « Règles automatiques » : une liste de tâches <b>ponctuelles</b> à cocher, sans fréquence ni génération automatique de BI — pour tout ce qui n'a pas besoin de revenir chaque année.",
    'aide_preventif.travaux_tip' => "Une tâche arrive ici de deux façons : ajoutée à la main via <b>« + Ajouter une tâche »</b>, ou transférée depuis une demande en attente du <a href=\"aide_ot.php#portes\">sas de validation</a> (bouton « Vers le préventif »).",
    'aide_preventif.travaux_champs_title' => "Les champs d'une tâche",
    'aide_preventif.travaux_champs_desc' => "Équipement, description, <b>signalé par</b> (équipe maintenance ou service), <b>intervenant(s)</b> — cases à cocher de l'équipe, plusieurs personnes possibles, plus une ligne de saisie libre pour un renfort saisonnier de la production sans compte GMAO —, date prévue et priorité (1 à 4, 1 étant la plus urgente).",
    'aide_preventif.travaux_statut_title' => "Le statut",
    'aide_preventif.travaux_statut_desc' => "Un badge cliquable par tâche : chaque clic fait avancer <b>À faire → En cours → Terminé</b> (puis retour à À faire). Les tâches terminées passent en vert et les plus récemment cochées remontent en haut de leur groupe.",
    'aide_preventif.travaux_recherche_title' => "Recherche & filtres",
    'aide_preventif.travaux_recherche_desc' => "Barre de recherche (équipement, tâche, intervenant), filtres Intervenant et Priorité, et les onglets Toutes / À faire / En cours / Terminées. Les colonnes Équipement, Intervenant, Date et Priorité se trient au clic sur leur en-tête.",
    'aide_preventif.travaux_warn' => "<b>Saisons :</b> les tâches sont groupées par saison (ex. « 2026-2027 »), calculée automatiquement mais modifiable. En fin de saison, cochez les tâches pas terminées (colonne de gauche du tableau) puis <b>« Reporter la sélection »</b> : elles sont recopiées vers la saison choisie (existante ou nouvelle), statut remis à « À faire ». Rien n'est reporté automatiquement — sans cette action, une tâche non terminée reste sur l'ancienne saison.",
    'aide_preventif.generation_lede' => "Une règle préventive ne fait rien par elle-même : c'est un mécanisme de génération qui, à intervalle régulier, transforme les règles arrivées à échéance en véritables BI.",
    'aide_preventif.generation_li1' => "Le BI généré porte automatiquement le préfixe <code>[PRÉVENTIF]</code> dans sa description, un statut <span class=\"pill pill-all\"><span class=\"pill-dot\"></span>À faire</span>, et le type <b>« Préventif »</b> (badge bleu, différent du curatif en rouge).",
    'aide_preventif.generation_li2' => "Il suit ensuite <b>exactement le même cycle de vie</b> qu'un BI curatif classique : À faire → En cours → Terminée, avec le même rapport de clôture obligatoire (voir <a href=\"aide_ot.php\">l'article « Créer & clôturer un BI »</a>).",
    'aide_preventif.generation_li3' => "Il reste tracé : depuis la règle d'origine, le bouton « Historique » retrouve tous les BI qu'elle a générés.",
    'aide_preventif.generation_lock' => "Au jour et à l'heure prévus, cette génération se déclenche automatiquement via une tâche planifiée côté serveur, indépendamment de vos clics dans l'interface. Si une échéance normale ne s'est pas transformée en BI sans que personne n'y ait touché, contactez l'administrateur système plutôt que de chercher pourquoi dans l'écran Préventif.",
    'aide_preventif.generation_tip1' => "Le bouton <b>⚡ « Générer une demande »</b> (sur chaque ligne de règle, et dans sa fiche détaillée) déclenche cette même génération tout de suite, à la demande — sans attendre l'échéance normale. Utile pour recréer une demande accidentellement effacée, ou tester une règle qui vient d'être créée. Comme la génération automatique, il crée une <b>demande dans le SAS de validation</b> (voir <a href=\"aide_ot.php#portes\">l'article « Créer & clôturer un BI »</a>) — jamais un bon d'intervention directement : il reste à la valider normalement.",
    'aide_preventif.generation_tip2' => "Aucune case à cocher n'existe sur un BI préventif : les consignes saisies à l'étape 4 (description, cause, pièces) sont simplement injectées en texte libre dans la description du BI, à lire comme n'importe quel autre ticket.",
    'aide_preventif.gestion_lede' => "Sur chaque ligne de la liste des règles :",
    'aide_preventif.gestion_modifier_h4' => "Modifier",
    'aide_preventif.gestion_modifier_p' => "Cliquez sur la ligne pour ouvrir la fiche détaillée, puis « Modifier » pour rouvrir l'assistant pré-rempli et changer n'importe quel champ.",
    'aide_preventif.gestion_pause_h4' => "Mettre en pause (Hiver)",
    'aide_preventif.gestion_pause_p' => "Suspend la règle sans la supprimer : elle est grisée dans la liste et ne génère plus aucun BI tant qu'elle n'est pas réactivée.",
    'aide_preventif.gestion_supprimer_h4' => "Supprimer",
    'aide_preventif.gestion_supprimer_p' => "Suppression <b>définitive</b> de la règle, avec confirmation. Les BI déjà générés restent dans l'historique — seule la planification future s'arrête.",
    'aide_preventif.gestion_historique_h4' => "Historique",
    'aide_preventif.gestion_historique_p' => "Retrouve toutes les occurrences déjà générées pour cette règle, avec leur statut de traitement.",
    'aide_preventif.planning_lede' => "Une grille hebdomadaire : une ligne par technicien, une colonne par jour (lundi à dimanche).",
    'aide_preventif.shot_grille_alt' => "Grille du planning hebdomadaire par technicien",
    'aide_preventif.shot_grille_cap' => "Chaque carte colorée représente un BI sur lequel le technicien a un pointage ce jour-là, avec son numéro de BI et le temps prévu.",
    'aide_preventif.planning_li1' => "Les flèches ◀ ▶ (dans la barre au-dessus de la grille) changent de semaine.",
    'aide_preventif.planning_li2' => "<b>Glisser-déposer</b> une carte vers une autre case pour réassigner un technicien et/ou déplacer la date.",
    'aide_preventif.planning_li3' => "Cliquer sur une carte ouvre le détail complet du bon d'intervention, comme sur l'écran Saisie & Historique.",
    'aide_preventif.planning_li4' => "Cliquer sur une case vide (admin) ouvre la création d'un nouveau BI, technicien et jour déjà pré-remplis, type pré-rempli sur « Préventif ».",
    'aide_preventif.planning_warn' => "<b>À savoir :</b> le glisser-déposer d'une carte fonctionne actuellement pour tout le monde, technicien comme admin — un technicien peut donc réassigner une tâche à un collègue en la faisant glisser, alors que la création depuis une case vide et la suppression restent, elles, réservées aux admins. Bon à savoir pour éviter les réassignations accidentelles.",
    'aide_preventif.planning_tip' => "Cet écran sert aussi à poser vos <b>congés payés, RTT, jours fériés et arrêts maladie</b>, et à suivre votre annualisation (objectif 1607h). Pour comprendre en détail comment chaque type de jour est compté — avec la formule légale et des exemples chiffrés — voir <a href=\"aide_annualisation.php\">l'article « Congés, RTT & Annualisation »</a>.",
    'aide_preventif.astuces_li1' => "<b>Toujours assigner un intervenant</b> à une règle si vous voulez la voir apparaître sur le Planning.",
    'aide_preventif.astuces_li2' => "<b>Utilisez « Mettre en pause »</b> plutôt que « Supprimer » pour les contrôles saisonniers (ex. hivernage) — vous gardez l'historique et pourrez la réactiver plus tard.",
    'aide_preventif.astuces_li3' => "<b>Vérifiez les chips de filtre</b> (« En retard », « Bientôt ») régulièrement : c'est le moyen le plus rapide de repérer les échéances qui glissent.",
    'aide_preventif.astuces_li4' => "<b>Un BI préventif se traite exactement comme un curatif</b> : même clôture, même rapport obligatoire — pas de raccourci spécifique à chercher.",
    'aide_preventif.astuces_li5' => "<b>BI préventif effacé par erreur ?</b> Retrouvez la règle d'origine sur l'écran Préventif et cliquez sur ⚡ « Générer une demande » pour la recréer dans le SAS de validation, sans attendre la prochaine échéance automatique.",
    'aide_preventif.gloss1_dt' => "Règle / Gamme préventive",
    'aide_preventif.gloss1_dd' => "La définition d'un contrôle récurrent : quoi, où, à quelle fréquence, pour qui.",
    'aide_preventif.gloss2_dt' => "Mode de planification",
    'aide_preventif.gloss2_dd' => "Fréquence en jours (ex. tous les 30 jours) ou jours de semaine fixes (ex. tous les lundis).",
    'aide_preventif.gloss3_dt' => "Échéance",
    'aide_preventif.gloss3_dd' => "La date à laquelle le prochain contrôle est attendu.",
    'aide_preventif.gloss4_dt' => "Pointage",
    'aide_preventif.gloss4_dd' => "Une ligne de temps enregistrée pour un technicien sur un BI — c'est elle qui fait apparaître une carte sur le Planning.",
    'aide_preventif.devnote_li1' => "La génération auto (<code>cron_preventif.php</code>) dépend d'une tâche planifiée externe (cron système) à vérifier côté serveur si des échéances normales ne se transforment pas en BI. Le bouton ⚡ « Générer une demande » (action <code>generer_demande</code> dans <code>preventif_liste.php</code>) reproduit le même INSERT à la demande, hors cycle du cron, sans jamais renseigner <code>num_bi</code>.",
    'aide_preventif.devnote_li2' => "La case « Auto matin » (colonne <code>preventif_regles.auto_matin</code>) fait choisir, à la génération (cron ou bouton manuel), le premier technicien par ordre alphabétique au poste « Matin » du jour dans <code>planning_shifts</code> — vide si personne ou plusieurs, sans repli sur l'intervenant fixe de la règle.",
    'aide_preventif.devnote_li3' => "Sur le Planning, le glisser-déposer (<code>action=update_pointage_planif</code>) n'est pas restreint côté serveur aux admins — seule la création depuis une case vide et la suppression le sont côté client.",

    'aide_ot.page_title_tag' => "Créer & Clôturer un BI - Aide GMAO",
    'aide_ot.hero_tagline' => "Le guide complet du bon d'intervention, de la panne signalée au rapport clôturé.",
    'aide_ot.pill_version' => "Version <b>1.4</b>",
    'aide_ot.pill_updated' => "Mis à jour le <b>11/09/2026</b>",
    'aide_ot.pill_ecrans' => "Écran concerné <b>Saisie &amp; Historique</b>",
    'aide_ot.toc_vue_ensemble' => "Vue d'ensemble",
    'aide_ot.toc_portes' => "Les 2 façons de créer un BI",
    'aide_ot.toc_formulaire' => "Utiliser l'assistant de création",
    'aide_ot.toc_assistant_intelligent' => "Le guide intelligent (doublons)",
    'aide_ot.toc_cycle' => "Le cycle de vie d'un BI",
    'aide_ot.toc_prise_en_charge' => "Prendre en charge",
    'aide_ot.toc_cloture' => "Clôturer un BI",
    'aide_ot.toc_cas_particuliers' => "Cas particuliers",
    'aide_ot.toc_droits' => "Qui peut faire quoi",
    'aide_ot.toc_astuces' => "Astuces & pièges",
    'aide_ot.toc_glossaire' => "Glossaire",
    'aide_ot.vue_ensemble_lede' => "Un <b>BI</b> (Bon d'Intervention) — c'est la fiche qui suit une intervention de maintenance du tout début (une panne signalée) jusqu'à la fin (le rapport rédigé). Ce guide vous montre, écran par écran, comment le créer, le prendre en charge, et le clôturer correctement.",
    'aide_ot.journey_creer' => "Créer",
    'aide_ot.journey_prendre' => "Prendre en charge",
    'aide_ot.journey_intervenir' => "Intervenir",
    'aide_ot.journey_cloturer' => "Clôturer",
    'aide_ot.shot_cartes_alt' => "Cartes de synthèse par technicien sur l'écran Saisie & Historique",
    'aide_ot.shot_cartes_cap' => "En haut de l'écran « Saisie & Historique », une carte par technicien résume sa charge : urgences, à faire, en cours, terminés, et le temps déjà pointé.",
    'aide_ot.callout_numero_bi' => "<b>Le numéro de BI</b> est généré automatiquement à la création, au format <code>BI</code> + année + numéro, par exemple <code>BI26-014</code>. Vous n'avez jamais à l'inventer : notez-le simplement quand vous devez en parler à quelqu'un (téléphone, atelier, réunion).",
    'aide_ot.portes_lede' => "Un BI peut arriver dans votre tableau de deux manières différentes. Il est important de savoir les distinguer.",
    'aide_ot.route1_tag' => "Écran Saisie & Historique",
    'aide_ot.route1_titre' => "Création directe",
    'aide_ot.route1_p1' => "Vous (technicien ou admin) créez vous-même le bon d'intervention en cliquant sur la tuile <b>« Créer un bon d'intervention »</b>, qui ouvre un assistant guidé en 4 étapes. C'est la méthode à utiliser quand <b>vous</b> constatez une panne ou une tâche à faire.",
    'aide_ot.route1_p2' => "Le ticket apparaît immédiatement dans le tableau avec le statut <span class=\"pill pill-afaire\"><span class=\"pill-dot\"></span>À faire</span> — prêt à être traité.",
    'aide_ot.route2_tag' => "Portail « Demande de Travaux »",
    'aide_ot.route2_titre' => "Demande d'un autre service",
    'aide_ot.route2_p1' => "Un opérateur, la Production, la Qualité ou un autre service dépose une demande avec son nom et un code PIN personnel (voir <a href=\"aide_service.php#demande\">l'article dédié</a>). Le ticket arrive avec le statut <span class=\"pill pill-attente\"><span class=\"pill-dot\"></span>En attente</span>, <b>sans numéro de BI</b>.",
    'aide_ot.route2_p2' => "Il apparaît dans le bandeau rouge <b>« demande(s) en attente de validation »</b>. C'est à vous de l'ouvrir et de la valider pour qu'elle devienne un vrai BI.",
    'aide_ot.shot_bandeau_alt' => "Bandeau d'alerte rouge indiquant des demandes en attente de validation",
    'aide_ot.shot_bandeau_cap' => "Ce bandeau apparaît en haut de l'écran dès qu'une demande externe attend d'être transformée en BI.",
    'aide_ot.shot_sas_alt' => "Fenêtre du sas de validation listant les demandes en attente",
    'aide_ot.shot_sas_cap' => "Le « sas de validation » : chaque dossier affiche la description, les photos jointes et un badge Urgent si signalé comme tel, puis propose Refuser, Messagerie, Créer le BI (avec le technicien et la date pré-remplis) — et pour un admin, Vers le préventif.",
    'aide_ot.callout_photos' => "La fiche d'un dossier affiche désormais tout ce que le demandeur a fourni : les <b>photos jointes</b> (avec zoom au clic), un badge <b>« Urgent »</b> bien visible si la demande a été signalée comme telle, et le nombre de messages déjà échangés directement sur le bouton <b>Messagerie</b> — de quoi juger la situation sans avoir à ouvrir chaque onglet.",
    'aide_ot.callout_mobile' => "Sur téléphone et tablette, le sas s'ouvre d'abord sur une liste de <b>badges</b> compacts (numéro de dossier, demandeur, équipement, description de la panne, date/heure, pastille rouge si urgent) plutôt que la fiche complète. Un tap sur un badge affiche la fiche en plein écran, avec un bouton <b>« Retour à la liste »</b> en haut pour revenir en arrière sans perdre les autres dossiers.",
    'aide_ot.callout_refuser' => "<b>Refuser</b> n'efface rien : le dossier reçoit un vrai numéro de BI (statut <span class=\"pill pill-refuse\"><span class=\"pill-dot\"></span>Refusée</span>) et reste visible dans l'Historique Global, avec le nom de la personne qui a refusé et un motif obligatoire d'au moins 20 caractères — un vrai compte-rendu (« usine en dégivrage total, pas de production ce jour-là »), pas « RAS » ou « ok ». C'est ce qui garantit qu'un audit retrouve une trace pour <b>chaque</b> tâche préventive générée, même celles qui n'ont pas donné lieu à une intervention.",
    'aide_ot.callout_vers_preventif' => "<b>Vers le préventif</b> (réservé aux admins) : pour une demande ponctuelle qui n'a pas besoin de devenir un BI tout de suite (ex. « descendre le panneau de 2 mètres »), ce bouton l'ajoute directement à l'onglet <b>« Travaux Hiver »</b> de la catégorie « Maintenance hivernal » du <a href=\"preventif.php\">Plan Préventif</a> — une checklist de tâches à cocher, sans fréquence ni génération automatique de BI (voir <a href=\"aide_preventif.php#travaux-divers\">le détail dans l'aide Préventif</a>). La demande d'origine est supprimée une fois ajoutée à cette liste. Pour un vrai besoin récurrent (rare depuis une demande), créez plutôt une règle classique via « Nouvelle règle » sur la page Préventif.",
    'aide_ot.callout_warn_etiquette' => "Sur le portail « Demande de Travaux », vous verrez parfois l'étiquette <b>« En attente de validation »</b>. C'est un texte d'affichage plus explicite pour le demandeur — en base, le statut réel reste <code>En attente</code>, celui que vous traitez via le bandeau rouge.",
    'aide_ot.formulaire_lede' => "Un clic sur la tuile <b>« Créer un bon d'intervention »</b> ouvre une fenêtre en 4 étapes. Chaque étape peut être révisée à tout moment via la sidebar, et chaque champ dispose d'une petite bulle d'aide <i class=\"fa-solid fa-circle-question\" style=\"color:var(--accent);\"></i> à cliquer en cas de doute.",
    'aide_ot.callout_lock_assistant' => "Tant que la fenêtre est ouverte, cliquer à côté ne l'annule <b>jamais</b> — seuls le bouton <b>« Annuler »</b> ou la croix en haut à droite ferment l'assistant (et perdent la saisie en cours). C'est volontaire, pour éviter de perdre un bon à moitié rempli d'un clic malheureux.",
    'aide_ot.step1_titre' => "Qui",
    'aide_ot.step1_desc' => "Le déclarant, et si besoin, l'entreprise extérieure en charge de l'intervention.",
    'aide_ot.step2_titre' => "Localisation",
    'aide_ot.step2_desc' => "La cascade Usine → Secteur → Ligne → Zone → Machine.",
    'aide_ot.step3_titre' => "Détails",
    'aide_ot.step3_desc' => "Date, type, priorité, casse, vérification visserie et description.",
    'aide_ot.step4_titre' => "Récapitulatif",
    'aide_ot.step4_desc' => "Relecture de tous les champs, puis clic sur « Créer le ticket d'intervention ».",
    'aide_ot.shot_etape1_alt' => "Étape 1 de l'assistant : le déclarant",
    'aide_ot.shot_etape1_cap' => "Étape 1 — Qui déclare l'intervention.",
    'aide_ot.shot_etape2_alt' => "Étape 2 de l'assistant : la localisation",
    'aide_ot.shot_etape2_cap' => "Étape 2 — La cascade de localisation.",
    'aide_ot.shot_etape3_alt' => "Étape 3 de l'assistant : les détails de l'intervention",
    'aide_ot.shot_etape3_cap' => "Étape 3 — Type, priorité et description.",
    'aide_ot.shot_etape4_alt' => "Étape 4 de l'assistant : le récapitulatif",
    'aide_ot.shot_etape4_cap' => "Étape 4 — Le récapitulatif avant validation.",
    'aide_ot.tbl_th_champ' => "Champ",
    'aide_ot.tbl_th_etape' => "Étape",
    'aide_ot.tbl_th_description' => "Description",
    'aide_ot.tbl_th_obligatoire' => "Obligatoire ?",
    'aide_ot.req_auto' => "Auto",
    'aide_ot.req_si_besoin' => "Si besoin",
    'aide_ot.req_conseille' => "Conseillé*",
    'aide_ot.row1_champ' => "Déclarant",
    'aide_ot.row1_desc' => "Votre nom. Pré-rempli et verrouillé pour un technicien ; un admin peut choisir n'importe qui.",
    'aide_ot.row2_champ' => "Intervenant prévu",
    'aide_ot.row2_desc' => "Réservé aux admins : pré-assigner quelqu'un dès la création.",
    'aide_ot.row3_champ' => "Entreprise extérieure",
    'aide_ot.row3_desc' => "Coche « intervention sous-traitée » puis choisissez l'entreprise si la tâche est confiée à un prestataire externe.",
    'aide_ot.row4_champ' => "Lieu → Secteur → Ligne → Zone → Machine",
    'aide_ot.row4_desc' => "Localisation en cascade : chaque menu se débloque quand le précédent est rempli. Si la machine n'existe pas encore en base, le champ devient une saisie libre.",
    'aide_ot.row5_champ' => "Date",
    'aide_ot.row5_desc' => "Date de l'intervention, aujourd'hui par défaut.",
    'aide_ot.row6_champ' => "Type",
    'aide_ot.row6_desc' => "Curatif / Préventif / Chantier.",
    'aide_ot.row7_champ' => "Priorité",
    'aide_ot.row7_desc' => "Normal ou Urgent — l'urgent fait clignoter le ticket dans le tableau.",
    'aide_ot.row8_champ' => "Casse",
    'aide_ot.row8_desc' => "À cocher si l'intervention concerne un bris de matériel.",
    'aide_ot.row9_champ' => "Vérification visserie",
    'aide_ot.row9_desc' => "À cocher si l'intervention inclut un contrôle de serrage/visserie.",
    'aide_ot.row10_champ' => "Description",
    'aide_ot.row10_desc' => "Le texte qui explique la panne ou la tâche à faire.",
    'aide_ot.callout_warn_champs' => "<b>* Aucun champ n'est techniquement bloqué</b> — l'assistant vous laisse avancer d'étape en étape même en laissant machine ou description vides. Ce n'est pas parce que c'est possible que c'est une bonne idée : un BI sans machine ni description est illisible pour le collègue qui le reprendra. Renseignez toujours au minimum <b>Machine</b>, <b>Type</b> et <b>Description</b>.",
    'aide_ot.callout_tip_bulle' => "Un doute sur un champ ? Cliquez sur son icône <i class=\"fa-solid fa-circle-question\"></i> — une bulle d'aide illustrée s'ouvre avec des exemples concrets, sans quitter l'assistant.",
    'aide_ot.assistant_intelligent_lede' => "Pendant que vous remplissez l'assistant, deux encarts contextuels apparaissent automatiquement pour vous aider à ne pas recréer un bon qui existe déjà sur la même machine.",
    'aide_ot.step_historique_titre' => "Étape 2 — Historique de la machine",
    'aide_ot.step_historique_desc' => "Dès qu'une machine est sélectionnée, un encart bleu liste tous les bons déjà enregistrés dessus (combien au total, combien encore ouverts), avec le statut et la date de chacun. La liste défile si elle est longue.",
    'aide_ot.step_similaires_titre' => "Étape 3 — Bons similaires",
    'aide_ot.step_similaires_desc' => "Pendant la saisie de la description, un encart orange apparaît si un ou plusieurs bons existants ont une description proche (recoupement de mots-clés, machine identique en priorité) — jusqu'à 3 suggestions, les plus proches en premier.",
    'aide_ot.callout_tip_clic_suggestion' => "Cliquer sur un bon suggéré demande confirmation, puis <b>ferme l'assistant en cours</b> et ouvre le bon existant : l'assistant d'édition s'il est encore actif, ou directement <b>la fenêtre de rapport / clôture</b> s'il est déjà terminé — pour voir ce qui a déjà été fait avant de décider de continuer dessus plutôt que d'en créer un nouveau.",
    'aide_ot.callout_warn_aide_pas_ia' => "C'est une <b>aide, pas une IA</b> : le recoupement se fait uniquement par mots-clés partagés dans la description, sans envoi à un service externe. Rien n'est jamais bloquant — ces encarts n'empêchent pas de créer un nouveau bon, ils aident juste à repérer un doublon avant de valider.",
    'aide_ot.cycle_lede' => "Un BI passe par une série de statuts, affichés sous forme de badges colorés dans le tableau. Voici le parcours complet, et qui déclenche chaque étape.",
    'aide_ot.pill_en_attente' => "En attente",
    'aide_ot.pill_a_faire' => "À faire",
    'aide_ot.pill_en_cours' => "En cours",
    'aide_ot.pill_terminee' => "Terminée",
    'aide_ot.pill_urgent' => "Urgent",
    'aide_ot.pill_refusee' => "Refusée",
    'aide_ot.cy_attente_trig' => "Demande créée par un autre service",
    'aide_ot.cy_attente_who' => "Via le portail",
    'aide_ot.cy_afaire_trig' => "Validation dans le bandeau rouge → numéro de BI attribué",
    'aide_ot.cy_afaire_who' => "Maintenance",
    'aide_ot.cy_cours_trig' => "Clic sur le badge de statut dans le tableau",
    'aide_ot.cy_cours_who' => "Technicien",
    'aide_ot.cy_termine_trig' => "Nouveau clic + rapport d'intervention rempli",
    'aide_ot.cy_termine_who' => "Technicien",
    'aide_ot.shot_tableau_alt' => "Tableau des interventions avec les badges de statut colorés",
    'aide_ot.shot_tableau_cap' => "Le tableau des interventions : chaque badge de statut est cliquable pour faire avancer le BI à l'étape suivante. Notez le cadenas « Saisie close » une fois le ticket terminé.",
    'aide_ot.callout_lock_reouverture' => "<b>Réouverture :</b> un BI « Terminée » peut être remis en « À faire » d'un simple clic sur son badge de statut, après confirmation — mais uniquement par un <b>administrateur</b>. Si vous êtes technicien et devez rouvrir un dossier clôturé par erreur, demandez à un admin. Cette règle s'applique aussi quand vous ouvrez un bon déjà clôturé depuis le <a href=\"#assistant-intelligent\">guide intelligent</a> du wizard : un technicien y voit le rapport en <b>lecture seule</b> (rapport et boutons « + TEMPS » / « Enregistrer, laisser ouvert » désactivés), seul un admin peut le modifier ou le rouvrir depuis cette fenêtre.",
    'aide_ot.callout_tip_urgent' => "<b>« Urgent » n'est pas un statut à part</b> : c'est une priorité posée à la création, qui fait clignoter en rouge le badge <span class=\"pill pill-urgent pulse-badge\"><span class=\"pill-dot\"></span>Urgent</span> tant que le ticket est à l'état « À faire ». Une fois pris en charge, il redevient un badge « En cours » classique.",
    'aide_ot.prise_en_charge_lede' => "Rien de plus simple : dans le tableau des interventions, repérez le badge de statut de la ligne concernée.",
    'aide_ot.pec_step1_titre' => "Repérez un ticket « À faire »",
    'aide_ot.pec_step1_desc' => "Utilisez les compteurs en haut de tableau (Urgent / À faire / En cours / Terminé) pour filtrer rapidement, ou parcourez la liste.",
    'aide_ot.pec_step2_titre' => "Cliquez directement sur le badge de statut",
    'aide_ot.pec_step2_desc' => "Un simple clic sur le badge fait passer le ticket à « En cours ». Aucune fenêtre de confirmation.",
    'aide_ot.pec_step3_titre' => "Un pointage à 0h est créé pour vous automatiquement",
    'aide_ot.pec_step3_desc' => "Si aucun temps n'était encore enregistré sur ce ticket, l'application crée un pointage à votre nom (0h, date du ticket). C'est ce pointage qui vous fait apparaître comme intervenant sur la fiche — pensez ensuite à mettre à jour votre temps réel via le bouton <b>« + TEMPS »</b>.",
    'aide_ot.callout_warn_pec' => "Passer un ticket en « En cours » <b>ne l'assigne pas formellement</b> à vous — le champ « déclarant » d'origine ne change pas, et aucune heure de prise en charge n'est horodatée. C'est votre pointage de temps qui fait foi si plusieurs personnes interviennent sur le même BI.",
    'aide_ot.cloture_lede' => "C'est l'étape la plus importante : c'est ici que votre travail devient un vrai historique de maintenance exploitable.",
    'aide_ot.clo_step1_titre' => "Cliquez à nouveau sur le badge de statut",
    'aide_ot.clo_step1_desc' => "Sur un ticket « En cours », ce second clic ouvre la fenêtre de clôture au lieu de changer directement le statut.",
    'aide_ot.clo_step2_titre' => "Vérifiez le rappel affiché",
    'aide_ot.clo_step2_desc' => "N° de BI, localisation/machine, temps total déjà pointé, demandeur, intervenant(s) et description de la panne s'affichent en lecture seule en haut de la fenêtre.",
    'aide_ot.clo_step3_titre' => "Rédigez le « Rapport d'Intervention Technique »",
    'aide_ot.clo_step3_desc' => "C'est <b>le seul champ obligatoire de tout le parcours d'un BI.</b> Décrivez les actions correctives menées : diagnostic, pièces remplacées, réglages, essais effectués. Soyez concret — c'est ce texte que relira un collègue en cas de panne récurrente.",
    'aide_ot.clo_step4_titre' => "Cliquez sur « Confirmer la Clôture »",
    'aide_ot.clo_step4_desc' => "Le statut passe à « Terminée », un message de confirmation s'affiche, et la saisie de temps se verrouille dans le tableau (badge <b>« 🔒 Saisie close »</b> à la place du bouton « + TEMPS »).",
    'aide_ot.shot_modale_alt' => "Fenêtre de clôture d'intervention avec le champ rapport obligatoire",
    'aide_ot.shot_modale_cap' => "La fenêtre de clôture : localisation, temps cumulé, demandeur et intervenants sont rappelés en lecture seule au-dessus du champ « Rapport d'Intervention Technique ».",
    'aide_ot.callout_warn_rapport_vide' => "Si vous laissez le rapport vide, l'application refuse la clôture avec le message <b>« Veuillez saisir un compte-rendu technique avant de clôturer »</b>. C'est normal : sans ce texte, le BI n'aurait aucune valeur d'historique.",
    'aide_ot.callout_tip_enregistrer_ouvert' => "<b>Pas fini ? Un bouton « Enregistrer, laisser ouvert »</b> est disponible juste à côté de « Confirmer la Clôture ». Il sauvegarde le rapport déjà rédigé et remet le bon en « En cours », sans exiger un texte terminé — utile pour noter où vous en êtes sans forcer une clôture prématurée. Un bouton <b>« + TEMPS »</b> est aussi présent directement dans cette fenêtre pour ajouter un pointage sans la fermer.",
    'aide_ot.callout_tip_carnet' => "<b>Le carnet de bord :</b> tant que le BI n'est pas terminé, la fiche détaillée propose une zone <b>« note intermédiaire »</b> (ex : « pièce commandée ce matin, en attente de livraison »). Utilisez-la pour laisser des traces d'avancement au fil de l'eau — une fois le BI clôturé, ces notes deviennent un historique en lecture seule, séparé du rapport final.",
    'aide_ot.callout_tip_demandeur_voit' => "<b>Le demandeur voit plus de détails une fois le BI terminé :</b> pour un ticket créé depuis le portail « Demande de Travaux », le service à l'origine de la demande retrouve dans son propre suivi les <b>heures d'intervention</b> cumulées (le total des pointages), la <b>date de réalisation</b> (date du dernier pointage), ainsi que toute <b>photo</b> jointe au BI — gardez ça en tête, ces informations ne restent pas cantonnées à vos outils internes.",
    'aide_ot.callout_lock_pdf' => "Depuis la fiche détaillée, le bouton <b>« EXPORTER EN PDF »</b> génère à tout moment un rapport imprimable nommé <code>RI_&lt;n° de BI&gt;.pdf</code>.",
    'aide_ot.cas_particuliers_lede' => "Quelques situations qui sortent du parcours standard.",
    'aide_ot.case_soustraitance_titre' => "Intervention sous-traitée",
    'aide_ot.case_soustraitance_desc' => "Cochez « intervention sous-traitée » à la création et choisissez l'entreprise extérieure. La fiche affiche alors « Sous-traitant : … » et un bouton <b>« GÉNÉRER PDP »</b> (plan de prévention) apparaît.",
    'aide_ot.case_urgent_titre' => "Priorité Urgent",
    'aide_ot.case_urgent_desc' => "Un ticket « À faire » marqué Urgent affiche une cloche rouge clignotante dans le tableau. Traitez-le en priorité — le clignotement s'arrête dès qu'il passe « En cours ».",
    'aide_ot.case_messagerie_titre' => "Messagerie sur un ticket",
    'aide_ot.case_messagerie_desc' => "Pour les tickets issus d'une demande externe, un bouton « MESSAGERIE » permet d'échanger avec le demandeur directement sur le ticket. Les messages non lus affichent une pastille rouge et un filtre dédié dans le tableau.",
    'aide_ot.case_suppression_titre' => "Suppression d'un BI",
    'aide_ot.case_suppression_desc' => "Possible en individuel (icône corbeille) ou en masse (sélection multiple). <b>Réservé aux administrateurs</b> — un technicien qui essaie voit un message de refus.",
    'aide_ot.case_impression_titre' => "Imprimer une fiche pour le tableau",
    'aide_ot.case_impression_desc' => "L'icône imprimante sur un BI génère une fiche compacte — machine, localisation, description, technicien(s) assigné(s), carnet de bord — à punaiser sur le tableau d'atelier. Pour en imprimer plusieurs d'un coup, cochez les BI puis cliquez sur <b>« Imprimer la sélection »</b> : chaque fiche s'imprime à taille identique, 2 par ligne. <b>Sélection multiple réservée aux administrateurs</b>, comme pour la suppression.",
    'aide_ot.droits_lede' => "L'écran s'adapte selon votre rôle. Voici le récapitulatif.",
    'aide_ot.tbl_th_action' => "Action",
    'aide_ot.tbl_th_technicien' => "Technicien",
    'aide_ot.tbl_th_admin' => "Admin",
    'aide_ot.droit1_action' => "Créer un BI",
    'aide_ot.droit2_action' => "Choisir librement le déclarant",
    'aide_ot.droit2_tech' => "Verrouillé sur soi",
    'aide_ot.droit3_action' => "Pré-assigner un intervenant à la création",
    'aide_ot.droit4_action' => "Prendre en charge / clôturer un BI",
    'aide_ot.droit5_action' => "Modifier le pointage d'un collègue",
    'aide_ot.droit5_tech' => "Ses pointages uniquement",
    'aide_ot.droit6_action' => "Supprimer un BI",
    'aide_ot.droit7_action' => "Rouvrir un BI clôturé",
    'aide_ot.droit8_action' => "Ajouter du temps / modifier le rapport d'un BI déjà clôturé",
    'aide_ot.droit8_tech' => "Lecture seule",
    'aide_ot.droit9_action' => "Accès Préventif, KPI, Stats, Parc Machine, Utilisateurs",
    'aide_ot.droit9_tech' => "Menus masqués",
    'aide_ot.astuces_li1' => "<b>Remplissez toujours la description</b>, même brièvement — c'est le champ le plus lu par vos collègues et par vous-même trois mois plus tard.",
    'aide_ot.astuces_li2' => "<b>Pointez votre temps au fur et à mesure</b> plutôt qu'au dernier moment : une fois le BI clôturé, la saisie de temps se verrouille.",
    'aide_ot.astuces_li3' => "<b>Ne laissez pas un BI « En cours » indéfiniment</b> — utilisez le carnet de bord (note intermédiaire) pour indiquer où vous en êtes si l'intervention s'étale sur plusieurs jours.",
    'aide_ot.astuces_li4' => "<b>Un BI sans machine sélectionnée</b> reste exploitable mais complique les statistiques par équipement — privilégiez toujours la cascade Usine → Secteur → Ligne → Zone → Machine.",
    'aide_ot.astuces_li5' => "<b>Une demande externe non traitée</b> reste invisible pour le demandeur tant qu'elle n'a pas de numéro de BI : pensez à vérifier régulièrement le bandeau rouge de validation.",
    'aide_ot.astuces_li6' => "<b>Avant de valider un nouveau bon</b>, jetez un œil aux encarts du <a href=\"#assistant-intelligent\">guide intelligent</a> (étapes 2 et 3) : si un bon très proche existe déjà et n'est pas terminé, autant continuer dessus plutôt que d'ouvrir un doublon.",
    'aide_ot.gloss1_dt' => "BI",
    'aide_ot.gloss1_dd' => "Bon d'Intervention — le nom générique de toute intervention suivie dans la GMAO, une fois qu'elle a un numéro (ex. BI26-014).",
    'aide_ot.gloss2_dt' => "Déclarant",
    'aide_ot.gloss2_dd' => "La personne qui a créé le ticket ou signalé la panne.",
    'aide_ot.gloss3_dt' => "Pointage",
    'aide_ot.gloss3_dd' => "Une ligne de temps passé, associée à un technicien et un ticket.",
    'aide_ot.gloss4_dt' => "Sas de validation",
    'aide_ot.gloss4_dd' => "Le bandeau rouge qui liste les demandes externes « En attente » à transformer en BI.",
    'aide_ot.gloss5_dt' => "PDP",
    'aide_ot.gloss5_dd' => "Plan de Prévention — document généré pour une intervention confiée à une entreprise extérieure.",
    'aide_ot.gloss6_dt' => "Carnet de bord",
    'aide_ot.gloss6_dd' => "La note intermédiaire d'un BI en cours, visible tant qu'il n'est pas clôturé.",
    'aide_ot.gloss7_dt' => "Rapport d'intervention",
    'aide_ot.gloss7_dd' => "Le compte-rendu final, seul champ obligatoire pour clôturer un BI.",
    'aide_ot.devnote_intro' => "Points relevés en analysant le code, à garder en tête côté administration :",
    'aide_ot.devnote_li1' => "Aucun champ de l'assistant de création n'est bloqué côté application (pas d'attribut <code>required</code>, la navigation entre étapes n'impose aucune validation) — la discipline de saisie repose entièrement sur l'équipe.",
    'aide_ot.devnote_li2' => "Le contrôle des droits (suppression, réouverture, édition des pointages d'autrui) est fait <b>uniquement côté navigateur</b> : <code>api.php</code> ne revérifie pas le rôle sur ces actions. Le verrou lecture-seule de la fenêtre de clôture pour un BI déjà terminé (nouveau avec le guide intelligent) suit la même logique — c'est une protection d'interface, pas serveur.",
    'aide_ot.devnote_li3' => "Le statut affiché « En attente de validation » sur le portail demandeur correspond en base au statut <code>En attente</code> — pas de valeur distincte stockée.",
    'aide_ot.devnote_li4' => "La détection de doublons du wizard (<code>#assistant-intelligent</code>) tourne entièrement côté navigateur sur les données déjà chargées (<code>tasks</code>) : recoupement de mots-clés (score de Jaccard, seuil 0.25), aucun appel réseau ni service externe.",

    'aide_planning.page_title_tag' => "Comprendre & remplir le Planning - Aide GMAO",
    'aide_planning.hero_tagline' => "La grille de la semaine, les cases à cocher, et comment elles font bouger votre avance ou votre retard.",
    'aide_planning.pill_version' => "Version <b>1.0</b>",
    'aide_planning.pill_updated' => "Mis à jour le <b>18/09/2026</b>",
    'aide_planning.pill_ecrans' => "Écran concerné <b>Planning</b>",
    'aide_planning.toc_vue_ensemble' => "Vue d'ensemble",
    'aide_planning.toc_naviguer' => "Naviguer dans les semaines",
    'aide_planning.toc_remplir_case' => "Remplir une case",
    'aide_planning.toc_cases_evenements' => "Chaque case, en détail",
    'aide_planning.toc_avance_retard' => "L'avance / le retard expliqué",
    'aide_planning.toc_exemple' => "Exemple chiffré, semaine par semaine",
    'aide_planning.toc_remplissage_rapide' => "Remplir plusieurs jours d'un coup",
    'aide_planning.toc_bons_intervention' => "Les bons d'intervention sur le planning",
    'aide_planning.toc_planning_annuel' => "Le Planning annuel",
    'aide_planning.toc_droits' => "Qui peut faire quoi",
    'aide_planning.toc_astuces' => "Astuces & pièges",
    'aide_planning.toc_glossaire' => "Glossaire",
    'aide_planning.vue_ensemble_lede' => "Le <b>Planning</b> est une grille : une ligne par technicien, une colonne par jour de la semaine. Chaque case peut recevoir un <b>poste travaillé</b> (matin, après-midi, nuit...), un <b>événement</b> (congé, RTT, maladie...), une <b>astreinte</b>, et le nombre d'<b>heures effectuées</b>. C'est cette même saisie qui alimente automatiquement votre compteur d'heures annualisées et l'indicateur « en avance / en retard » que vous voyez sur votre fiche.",
    'aide_planning.shot_grille_alt' => "Grille hebdomadaire du planning avec une ligne par technicien",
    'aide_planning.shot_grille_cap' => "La grille de la semaine : à gauche, chaque technicien avec son total d'heures de la semaine et son total annualisé ; au centre, une case par jour.",
    'aide_planning.vue_ensemble_p2' => "Dans chaque case, vous pouvez voir jusqu'à trois choses :",
    'aide_planning.vue_li1' => "<b>Un badge de poste/événement</b> — couleur + libellé (ex. « Matin · 7h », « CP », « RTT »).",
    'aide_planning.vue_li2' => "<b>Un ou plusieurs bons d'intervention (BI)</b> — les petites étiquettes numérotées, si le technicien a pointé du temps sur une intervention ce jour-là.",
    'aide_planning.vue_li3' => "<b>Une icône de note</b> <i class=\"fa-solid fa-note-sticky\" style=\"color:var(--brand-orange);\"></i> — si une remarque a été laissée (ex. « arrivé à 9h, parti à 15h30 »).",
    'aide_planning.callout_annuel' => "Cliquer sur le nom, l'avatar ou le total d'un technicien (le bloc de gauche) ouvre directement son <a href=\"#planning-annuel\"><b>Planning annuel</b></a> — le calendrier complet de l'année, pas seulement la semaine affichée.",
    'aide_planning.toc_vues_affichage' => "Vue Jour / Semaine / Mois",
    'aide_planning.vues_affichage_lede' => "Un sélecteur en haut de la page permet de changer complètement d'affichage, sans changer de page :",
    'aide_planning.vue_jour_titre' => "Vue Jour",
    'aide_planning.vue_jour_desc' => "Tous les techniciens sur une seule journée, l'un sous l'autre — pratique pour voir d'un coup d'œil qui est disponible aujourd'hui.",
    'aide_planning.vue_semaine_titre' => "Vue Semaine",
    'aide_planning.vue_semaine_desc' => "L'affichage habituel, inchangé : la grille de la semaine, technicien par technicien.",
    'aide_planning.vue_mois_titre' => "Vue Mois",
    'aide_planning.vue_mois_desc' => "Un calendrier par technicien sur tout le mois. On peut y glisser-déposer un bon d'intervention comme en vue Semaine (mêmes droits), et cliquer dessus pour ouvrir son rapport.",
    'aide_planning.callout_vues_affichage' => "Changer de vue ne modifie aucune donnée : c'est juste une autre façon d'afficher le même planning.",
    'aide_planning.naviguer_lede' => "Trois façons de changer de semaine, toutes équivalentes :",
    'aide_planning.case_fleches_titre' => "Les flèches sur les bords",
    'aide_planning.case_fleches_desc' => "Deux flèches semi-transparentes sont collées sur le bord gauche et le bord droit de l'écran. Un clic recule ou avance d'une semaine.",
    'aide_planning.case_glisser_titre' => "Glisser un bon d'intervention vers le bord",
    'aide_planning.case_glisser_desc' => "En cours de glisser-déposer d'un BI, approchez-le du bord gauche ou droit de l'écran : la semaine défile automatiquement (avec un repère « Semaine XX » à l'écran) pour déposer le BI sur une autre semaine sans lâcher la souris.",
    'aide_planning.case_repere_titre' => "Le repère « Semaine XX »",
    'aide_planning.case_repere_desc' => "En haut de l'écran, le numéro de semaine et les dates exactes (« du ... au ... ») affichés vous confirment toujours la période consultée.",
    'aide_planning.remplir_case_lede' => "Cliquez n'importe où dans une case vide (ou sur son badge existant) pour ouvrir la fenêtre de planification. C'est l'écran central de toute cette fiche.",
    'aide_planning.shot_modal_alt' => "Fenêtre de planification d'une case : Poste, Événement, Astreinte, Heures, Note",
    'aide_planning.shot_modal_cap' => "La fenêtre qui s'ouvre au clic sur une case : trois groupes de « puces » à cliquer (Poste, Événement, Astreinte), puis les heures effectuées et une note libre.",
    'aide_planning.rc_step1_titre' => "Choisissez un Poste (si le technicien a travaillé)",
    'aide_planning.rc_step1_desc' => "Matin, Après-midi, Nuit ou Journée — une seule puce à la fois peut être active. Cliquer sur une puce déjà active la désélectionne.",
    'aide_planning.rc_step2_titre' => "Ou choisissez un Événement (si le technicien est absent)",
    'aide_planning.rc_step2_desc' => "Congé payé (CP), RTT, Maladie, Repos — un seul actif à la fois, et il efface automatiquement le Poste choisi (on ne peut pas être « en congé » et « au travail » le même jour). Demi-congé et Jour férié fonctionnent différemment : voir la section suivante.",
    'aide_planning.rc_step3_titre' => "Ajoutez une Astreinte si besoin",
    'aide_planning.rc_step3_desc' => "Astreinte classique ou Astreinte froid — purement informatif, ça n'a aucun effet sur les heures dues ou l'avance/retard, seul le badge s'affiche dans le planning.",
    'aide_planning.rc_step4_titre' => "Saisissez les heures effectuées",
    'aide_planning.rc_step4_desc' => "Avec les boutons <b>−</b> / <b>+</b> (pas de 0,5h) ou en tapant directement le nombre. C'est ce chiffre qui remonte dans le total réel de la semaine et de l'année.",
    'aide_planning.rc_step5_titre' => "Ajoutez une note si nécessaire",
    'aide_planning.rc_step5_desc' => "Un retard, un départ anticipé, un événement particulier... Cette note n'est visible que par le technicien concerné et par les administrateurs — jamais par les autres collègues.",
    'aide_planning.rc_step6_titre' => "Enregistrez",
    'aide_planning.rc_step6_desc' => "Le bouton <b>« Enregistrer »</b> valide la case. Le bouton <b>« Effacer »</b> vide entièrement la case (poste, événement, astreinte, heures et note).",
    'aide_planning.callout_objectif_direct' => "Pendant que vous remplissez la fenêtre, la barre <b>« Objectif annualisé »</b> en bas à droite se met à jour <b>en direct</b> — vous voyez immédiatement l'effet de votre saisie sur votre compteur d'heures avant même d'enregistrer.",
    'aide_planning.cases_evenements_lede' => "Toutes les cases ne se valent pas : certaines sont exclusives entre elles, d'autres se cumulent. Voici le détail complet, poste par poste et événement par événement.",
    'aide_planning.tbl2_th_case' => "Case",
    'aide_planning.tbl2_th_groupe' => "Groupe",
    'aide_planning.tbl2_th_heures_dues' => "Heures « dues » ce jour-là",
    'aide_planning.tbl2_th_cumule' => "Se cumule avec",
    'aide_planning.row1_case' => "Matin / Après-midi / Nuit / Journée",
    'aide_planning.row1_groupe' => "Poste",
    'aide_planning.row1_heures' => "7h (jour normal)",
    'aide_planning.row1_cumule' => "Demi-congé, Jour férié",
    'aide_planning.row2_case' => "Demi-congé (½ CP)",
    'aide_planning.row2_groupe' => "Événement à cocher",
    'aide_planning.row2_heures' => "3,5h au lieu de 7h",
    'aide_planning.row2_cumule' => "Un poste travaillé uniquement",
    'aide_planning.row3_case' => "Congé payé (CP)",
    'aide_planning.row3_groupe' => "Événement",
    'aide_planning.row3_heures' => "0h",
    'aide_planning.row3_cumule' => "Rien (exclusif)",
    'aide_planning.row4_case' => "Jour férié",
    'aide_planning.row4_groupe' => "Événement à cocher",
    'aide_planning.row4_heures' => "0h si non travaillé · 7h normalement s'il est travaillé",
    'aide_planning.row4_cumule' => "Un poste travaillé",
    'aide_planning.row5_case' => "RTT",
    'aide_planning.row5_groupe' => "Événement",
    'aide_planning.row5_heures' => "7h (mais 0h faites)",
    'aide_planning.row5_cumule' => "Rien (exclusif)",
    'aide_planning.row6_case' => "Maladie",
    'aide_planning.row6_groupe' => "Événement",
    'aide_planning.row6_heures' => "7h, créditées automatiquement",
    'aide_planning.row6_cumule' => "Rien (exclusif)",
    'aide_planning.row7_case' => "Repos",
    'aide_planning.row7_groupe' => "Événement",
    'aide_planning.row7_heures' => "0h",
    'aide_planning.row7_cumule' => "Rien (exclusif)",
    'aide_planning.row8_case' => "Case vide (jour de semaine)",
    'aide_planning.row8_heures' => "7h quand même",
    'aide_planning.row9_case' => "Case vide (samedi/dimanche)",
    'aide_planning.row9_heures' => "0h",
    'aide_planning.card_poste_titre' => "Poste (Matin / Après-midi / Nuit / Journée)",
    'aide_planning.card_poste_desc' => "Le rythme de travail réellement fait ce jour-là. Compté comme un jour normal : <b>7h dues</b>, comparées aux heures que vous saisissez juste en dessous.",
    'aide_planning.card_cp_titre' => "Congé payé (CP)",
    'aide_planning.card_cp_desc' => "0h dues : un jour de CP n'est jamais compté comme « à rattraper ». Il consomme un jour du quota annuel — <b>25 jours</b> en semaine, <b>5 jours</b> supplémentaires réservés au samedi (30 au total, deux compteurs séparés). Posé un dimanche, il ne consomme rien puisque le dimanche n'est de toute façon jamais travaillé.",
    'aide_planning.card_demiconge_titre' => "Demi-congé (½ CP)",
    'aide_planning.card_demiconge_desc' => "Une case à cocher <b>à part</b>, pas un poste : elle réduit le nombre d'heures dues à 3,5h au lieu de 7h. Elle ne peut se cocher qu'en complément d'un vrai poste travaillé (matin, après-midi...) — cocher un événement pleine journée (CP, RTT, Maladie, Repos) la décoche automatiquement, et inversement.",
    'aide_planning.card_ferie_titre' => "Jour férié",
    'aide_planning.card_ferie_desc' => "Se coche comme le demi-congé, en plus d'un poste. <b>Non travaillé</b> : 0h dues. <b>Travaillé</b> (un poste est aussi coché) : compté comme un jour normal, 7h dues — travailler un jour férié ne crée pas de bonus caché dans ce compteur (la majoration de salaire, elle, est un sujet de paie séparé). Les jours fériés français reconnus sont <b>pré-cochés automatiquement</b> tant que personne n'a rien saisi ce jour-là pour vous.",
    'aide_planning.card_rtt_titre' => "RTT",
    'aide_planning.card_rtt_desc' => "Attention, piège classique : contrairement au CP, un RTT reste compté comme <b>7h dues</b>, avec 0h faites. Concrètement, poser un RTT <b>débite 7h de votre avance</b> — c'est normal, un RTT « consomme » des heures que vous avez déjà accumulées en travaillant plus que 35h certaines semaines.",
    'aide_planning.card_maladie_titre' => "Maladie",
    'aide_planning.card_maladie_desc' => "7h dues, mais l'application les <b>crédite automatiquement</b> comme si elles avaient été travaillées (même si vous ne saisissez aucune heure). Résultat : un arrêt maladie est totalement <b>neutre</b> sur votre compteur — il ne vous pénalise pas, mais ne vous fait pas non plus avancer.",
    'aide_planning.card_repos_titre' => "Repos",
    'aide_planning.card_repos_desc' => "Le jour de repos hebdomadaire légal, sur une rotation qui peut tomber n'importe quel jour de la semaine (pas forcément samedi/dimanche). 0h dues : ce jour n'a jamais été « à travailler », donc il ne coûte rien de le poser.",
    'aide_planning.card_astreinte_titre' => "Astreinte (classique / froid)",
    'aide_planning.card_astreinte_desc' => "Purement informatif : n'affecte <b>ni</b> les heures dues, <b>ni</b> les heures faites, <b>ni</b> l'avance/retard. Juste un badge visuel dans le planning pour savoir qui est d'astreinte.",
    'aide_planning.callout_warn_case_vide' => "<b>La première cause de « faux retard » : une case de semaine laissée totalement vide.</b> Même si le technicien a réellement travaillé, l'application ne peut compter que ce qui est saisi. Un jour de semaine sans aucune case cochée reste dû à 7h par défaut (sauf s'il s'agit d'un jour férié reconnu automatiquement) — sans saisie en face, ça se traduit par <b>-7h</b> sur le compteur d'avance, comme si le technicien n'avait rien fait.",
    'aide_planning.avance_retard_lede' => "Vous avez sûrement déjà vu la phrase <b>« +12h d'avance sur 35h/semaine »</b> ou <b>« 8h de retard sur 35h/semaine »</b> sous une barre de progression. Voici comment ce chiffre est calculé, sans jargon.",
    'aide_planning.journey2_dues' => "Heures dues",
    'aide_planning.journey2_faites' => "Heures faites",
    'aide_planning.journey2_ecart' => "Écart (avance ou retard)",
    'aide_planning.ar_p1' => "<b>Les heures « dues »</b> sont ce que vous devriez avoir accumulé à la date d'aujourd'hui si vous travailliez très exactement 35h par semaine (soit 7h par jour ouvré) depuis le début de la période — le 1<sup>er</sup> avril. Chaque jour de semaine compte 7h de « dû », sauf ceux couverts par le tableau de la section précédente (CP = 0h, Repos = 0h, Jour férié non travaillé = 0h, Demi-congé = 3,5h). Le week-end ne doit par défaut rien, sauf s'il a été réellement travaillé.",
    'aide_planning.ar_p2' => "<b>Les heures « faites »</b> sont la somme de toutes les heures que vous avez saisies dans vos cases, plus les 7h « comme si » créditées automatiquement chaque jour de maladie.",
    'aide_planning.ar_p3' => "<b>L'écart</b> = heures faites − heures dues. Positif, vous êtes <span class=\"chip-key\"><span class=\"chip-dot\" style=\"background:var(--success);\"></span>en avance</span>. Négatif, vous êtes <span class=\"chip-key\"><span class=\"chip-dot\" style=\"background:var(--danger);\"></span>en retard</span>.",
    'aide_planning.shot_ecart_alt' => "Fenêtre « Comprendre mon avance/retard » avec le détail mois par mois",
    'aide_planning.shot_ecart_cap' => "La bulle d'aide « i » à côté du repère 35h/semaine ouvre ce détail : heures dues, heures faites, écart total, écart mois par mois, et surtout la liste des jours de semaine restés sans aucune saisie.",
    'aide_planning.callout_tip_jours_sans_saisie' => "Cette bulle d'aide liste explicitement les <b>jours de semaine sans aucune saisie</b> (ni poste, ni CP, ni RTT, ni férié). C'est presque toujours la vraie explication d'un retard qui paraît injustifié : remplissez ces jours (poste travaillé ou congé posé) et le compteur remonte immédiatement.",
    'aide_planning.ar_p4' => "Deux ajustements supplémentaires réduisent le nombre d'heures dues sur l'année entière (donc font remonter l'avance) :",
    'aide_planning.card_fractionnement_titre' => "Fractionnement (Art. 6)",
    'aide_planning.card_fractionnement_desc' => "Des jours accordés au cas par cas par la RH selon les conditions de prise du congé principal — <b>1 jour = -7h</b>, <b>2 jours = -14h</b> sur l'objectif annuel. Se règle dans le <a href=\"#planning-annuel\">Planning annuel</a>, menu déroulant « Fractionnement ».",
    'aide_planning.card_semaine48_titre' => "Semaines à 48h (Art. 3)",
    'aide_planning.card_semaine48_desc' => "Toute semaine où le total d'heures saisies atteint 48h ou plus donne droit à <b>-4h</b> sur l'objectif annuel — détecté automatiquement, aucune saisie particulière à faire.",
    'aide_planning.exemple_lede' => "Un exemple fictif pour bien voir l'effet concret de chaque case. Imaginons la semaine d'un technicien remplie ainsi :",
    'aide_planning.tbl3_th_jour' => "Jour",
    'aide_planning.tbl3_th_case' => "Case cochée",
    'aide_planning.tbl3_th_heures_dues' => "Heures dues",
    'aide_planning.tbl3_th_heures_faites' => "Heures faites",
    'aide_planning.tbl3_th_ecart' => "Écart du jour",
    'aide_planning.ex_lundi' => "Lundi",
    'aide_planning.ex_lundi_case' => "Matin, 7h saisies",
    'aide_planning.ex_mardi' => "Mardi",
    'aide_planning.ex_mardi_case' => "<i>Rien saisi, oublié</i>",
    'aide_planning.ex_mercredi' => "Mercredi",
    'aide_planning.ex_mercredi_case' => "RTT",
    'aide_planning.ex_jeudi' => "Jeudi",
    'aide_planning.ex_jeudi_case' => "CP",
    'aide_planning.ex_vendredi' => "Vendredi",
    'aide_planning.ex_vendredi_case' => "Matin + Jour férié travaillé, 7h saisies",
    'aide_planning.ex_samedi' => "Samedi",
    'aide_planning.ex_dimanche' => "Dimanche",
    'aide_planning.ex_rien_non_travaille' => "<i>Rien (non travaillé)</i>",
    'aide_planning.ex_total_label' => "Total de la semaine",
    'aide_planning.exemple_conclusion' => "Résultat : <b>-7h sur la semaine</b>, malgré deux jours effectivement travaillés à 7h et un CP correctement posé. La cause n'est <b>pas</b> le CP (0h dû, neutre) : c'est la combinaison du <b>mardi oublié</b> (-7h, un pur trou de saisie) et du <b>RTT du mercredi</b> qui, lui, débite normalement 7h de l'avance déjà accumulée. En remplissant simplement le mardi, l'écart de la semaine remonterait immédiatement à 0h.",
    'aide_planning.remplissage_rapide_lede' => "Pour poser une semaine de CP ou une série de postes identiques sans ouvrir chaque jour un par un, utilisez le bouton <b>« Remplir plusieurs jours »</b> en bas de la fenêtre de planification.",
    'aide_planning.shot_bulk_alt' => "Fenêtre de remplissage rapide sur une période de dates",
    'aide_planning.shot_bulk_cap' => "Choisissez une période de dates, cochez éventuellement « Exclure les week-ends », composez la même case (Poste/Événement/Astreinte/Heures) qu'en saisie individuelle, puis « Appliquer ».",
    'aide_planning.rr_step1_titre' => "Choisissez la période",
    'aide_planning.rr_step1_desc' => "Une date de début et une date de fin. La case « Exclure les week-ends » est cochée par défaut — décochez-la si vous devez aussi couvrir des samedis/dimanches.",
    'aide_planning.rr_step2_titre' => "Composez la case à appliquer",
    'aide_planning.rr_step2_desc' => "Exactement les mêmes puces Poste / Événement / Astreinte et le même champ Heures que pour une case individuelle, avec les mêmes règles de cumul.",
    'aide_planning.rr_step3_titre' => "Vérifiez l'aperçu, puis Appliquer",
    'aide_planning.rr_step3_desc' => "Un aperçu résume ce qui va être écrit avant validation.",
    'aide_planning.callout_warn_ecrase' => "Le remplissage rapide <b>écrase</b> tout ce qui existait déjà sur les jours concernés (poste, événement, astreinte, heures) — vérifiez bien la période avant de cliquer sur « Appliquer ».",
    'aide_planning.bons_intervention_lede' => "Le planning affiche aussi, à côté du poste du jour, une petite étiquette par bon d'intervention (BI) sur lequel le technicien a un pointage de temps ce jour-là (voir <a href=\"aide_ot.php\">le guide des BI</a> pour la création et le pointage).",
    'aide_planning.bi_li1' => "<b>Cliquer sur une étiquette de BI</b> ouvre directement sa fiche détaillée.",
    'aide_planning.bi_li2' => "<b>Glisser-déposer une étiquette</b> vers une autre case déplace le BI (et son pointage) vers un autre jour ou un autre technicien — réservé aux administrateurs. Un technicien voit ses propres BI mais ne peut pas les faire glisser chez un collègue.",
    'aide_planning.bi_li3' => "Dans la fenêtre de planification elle-même, la section <b>« Bons d'intervention du jour »</b> liste en haut tous les BI du technicien pour cette date précise, avec statut coloré et un clic pour ouvrir le détail.",
    'aide_planning.planning_annuel_lede' => "Accessible en cliquant sur le nom d'un technicien dans la grille, ou sur le bouton <b>« Voir le planning annuel complet »</b> dans la fenêtre de planification. C'est le calendrier complet de la période en cours (du 1<sup>er</sup> avril au 31 mars suivant), mois par mois.",
    'aide_planning.shot_annuel_alt' => "Planning annuel : calendrier complet avec récapitulatif des quotas",
    'aide_planning.shot_annuel_cap' => "En haut : la barre de progression de l'objectif annuel et le repère 35h/semaine. En dessous : le récapitulatif des quotas (CP, CP samedi, RTT, Maladie, postes, astreintes). Plus bas : le calendrier mois par mois.",
    'aide_planning.card_objectif_titre' => "Objectif annuel",
    'aide_planning.card_objectif_desc' => "1607h par défaut (le seuil légal français), mais personnalisable par technicien. <b>Chacun peut modifier son propre objectif</b> (ou un admin, celui de n'importe qui) via le petit champ numérique et le bouton <i class=\"fa-solid fa-check\"></i>.",
    'aide_planning.card_fractionnement2_titre' => "Fractionnement",
    'aide_planning.card_fractionnement2_desc' => "Menu déroulant 0j / 1j (-7h) / 2j (-14h) — mêmes droits que l'objectif : le technicien concerné ou un admin.",
    'aide_planning.card_recap_titre' => "Récapitulatif des quotas",
    'aide_planning.card_recap_desc' => "Une tuile par catégorie : CP (25j), CP samedi (5j), RTT et Maladie (sans quota fixe, juste un compteur), et les postes/astreintes déjà planifiés sur l'année.",
    'aide_planning.card_alerte_cp_titre' => "Alerte CP d'été",
    'aide_planning.card_alerte_cp_desc' => "Si plus de <b>12 jours ouvrables de CP consécutifs</b> chevauchent la période du 15 juillet au 30 septembre, un badge d'alerte apparaît sur la tuile CP (plafond conventionnel, Art. 6 de l'accord d'annualisation).",
    'aide_planning.pa_p_calendrier' => "Dans le calendrier lui-même, chaque jour affiche un mini-badge de poste/événement et, pour les jours déjà passés, un petit badge vert (avance) ou rouge (retard) indiquant l'écart de ce jour précis. Chaque mois totalise ses heures et son propre écart.",
    'aide_planning.callout_tip_bulle_ecart' => "Le bouton <i class=\"fa-solid fa-circle-info\"></i> à côté du repère 35h/semaine ouvre la bulle <b>« Comprendre mon avance/retard »</b> détaillée dans la section <a href=\"#avance-retard\">précédente</a>.",
    'aide_planning.callout_lock_annualisation' => "Pour la formule légale complète des 1607h (calcul détaillé, congés, jours fériés) et les règles de l'accord d'annualisation, voir l'article dédié <a href=\"aide_annualisation.php\">Congés, RTT &amp; Annualisation</a>.",
    'aide_planning.droits_lede' => "Le planning s'adapte selon votre rôle. Voici le récapitulatif.",
    'aide_planning.tbl4_th_action' => "Action",
    'aide_planning.tbl4_th_technicien' => "Technicien",
    'aide_planning.tbl4_th_admin' => "Admin",
    'aide_planning.droit1_action' => "Voir la grille de la semaine",
    'aide_planning.txt_toute_equipe' => "Toute l'équipe",
    'aide_planning.droit2_action' => "Remplir/modifier une case",
    'aide_planning.txt_ses_cases' => "Ses propres cases uniquement",
    'aide_planning.txt_nimporte_qui' => "N'importe qui",
    'aide_planning.droit3_action' => "Voir le planning annuel",
    'aide_planning.txt_le_sien' => "Le sien uniquement",
    'aide_planning.droit4_action' => "Modifier l'objectif annuel / le fractionnement",
    'aide_planning.txt_les_siens' => "Les siens uniquement",
    'aide_planning.droit5_action' => "Lire la note d'une case",
    'aide_planning.txt_ses_notes' => "Ses propres notes uniquement",
    'aide_planning.txt_toutes_notes' => "Toutes les notes",
    'aide_planning.droit6_action' => "Déplacer un BI d'un technicien à un autre",
    'aide_planning.astuces_li1' => "<b>Ne laissez jamais un jour de semaine vide</b> — même une petite journée normale doit avoir un poste et des heures, sinon le compteur d'avance considère 7h « dues » et 0h « faites », soit -7h qui paraissent injustifiées.",
    'aide_planning.astuces_li2' => "<b>RTT ≠ Repos ≠ CP</b> : le CP et le Repos sont neutres (0h dues), mais le RTT reste dû à 7h — poser un RTT débite réellement votre avance. Ne confondez pas les trois si vous voulez un compteur juste.",
    'aide_planning.astuces_li3' => "<b>Un jour férié travaillé doit être coché ET avoir un poste</b> : cocher seulement « Jour férié » sans poste laisse croire que vous n'avez pas travaillé ce jour-là.",
    'aide_planning.astuces_li4' => "<b>La maladie n'a pas besoin d'heures saisies</b> : cochez simplement la case, les 7h sont créditées automatiquement.",
    'aide_planning.astuces_li5' => "<b>Consultez régulièrement la bulle « Comprendre mon avance/retard »</b> — elle liste très précisément les jours qu'il vous reste à remplir, plutôt que de deviner.",
    'aide_planning.astuces_li6' => "<b>Le remplissage rapide écrase les cases existantes</b> sur la période choisie : vérifiez toujours les dates avant de cliquer sur « Appliquer ».",
    'aide_planning.gloss1_dt' => "Poste",
    'aide_planning.gloss1_dd' => "Le rythme de travail réel d'un jour : Matin, Après-midi, Nuit ou Journée.",
    'aide_planning.gloss2_dt' => "Événement",
    'aide_planning.gloss2_dd' => "Une absence ou un aménagement de journée : CP, RTT, Maladie, Repos, Demi-congé, Jour férié.",
    'aide_planning.gloss3_dt' => "Astreinte",
    'aide_planning.gloss3_dd' => "Information affichée en badge, sans effet sur les heures dues/faites.",
    'aide_planning.gloss4_dt' => "Heures dues",
    'aide_planning.gloss4_dd' => "Ce que le technicien devrait avoir travaillé ce jour (7h, 3,5h ou 0h selon la case cochée).",
    'aide_planning.gloss5_dt' => "Heures faites",
    'aide_planning.gloss5_dd' => "Les heures réellement saisies, plus le crédit automatique de 7h pour un jour de maladie.",
    'aide_planning.gloss6_dt' => "Repère 35h/semaine",
    'aide_planning.gloss6_dd' => "Le cumul des heures dues depuis le 1<sup>er</sup> avril jusqu'à aujourd'hui — la référence de comparaison de l'avance/retard.",
    'aide_planning.gloss7_dt' => "Objectif annualisé",
    'aide_planning.gloss7_dd' => "Le total d'heures à atteindre sur l'année (1607h par défaut), affiché en barre de progression.",
    'aide_planning.gloss8_dt' => "Fractionnement",
    'aide_planning.gloss8_dd' => "Jours accordés par la RH qui réduisent l'objectif annuel de 7h ou 14h (Art. 6 de l'accord d'annualisation).",
    'aide_planning.gloss9_dt' => "Semaine à 48h",
    'aide_planning.gloss9_dd' => "Une semaine où le total d'heures saisies atteint 48h ou plus, réduisant automatiquement l'objectif de 4h (Art. 3).",
    'aide_planning.gloss10_dt' => "CP samedi",
    'aide_planning.gloss10_dd' => "Quota séparé de 5 jours de congé payé réservés au samedi, distinct des 25 CP de semaine.",
    'aide_planning.devnote_intro' => "Points relevés en analysant le code, à garder en tête côté administration :",
    'aide_planning.devnote_li1' => "La logique d'avance/retard (<code>referenceDuJour</code>, <code>calculerReferenceHeures35h</code>) est calculée <b>côté navigateur</b> à partir de <code>planning_shifts</code> — aucun recalcul serveur, donc toute modification de cette règle doit être répercutée dans le JS de <code>planning.php</code>.",
    'aide_planning.devnote_li2' => "L'objectif annuel et le fractionnement sont modifiables par le technicien concerné lui-même (pas seulement par un admin) — décision assumée du code (« chacun gère ses propres heures »), à reconfirmer si la politique RH change.",
    'aide_planning.devnote_li3' => "Le contrôle des droits (édition des cases d'autrui, déplacement de BI) est fait uniquement côté navigateur : les actions <code>save_shift</code>, <code>save_objectif</code> et <code>save_fractionnement</code> de <code>maintenance.php</code> ne revérifient pas le rôle.",

    'aide_service.page_title_tag' => "Aide - Portail Services",
    'aide_service.crumb_portail_services' => "Portail Services",
    'aide_service.crumb_aide' => "Aide",
