    'aide_service.hero_eyebrow' => "Guide du Portail Services",
    'aide_service.hero_h1' => "Utiliser le portail services",
    'aide_service.hero_tagline' => "Tout ce qu'il faut savoir pour signaler une panne, suivre vos demandes et faire remonter vos idées.",
    'aide_service.pill_updated' => "Mis à jour le <b>04/09/2026</b>",
