    'aide_service.toc_annualisation' => "Congés, RTT & Annualisation",
    'aide_service.toc_planning' => "Planning (bientôt)",
    'aide_service.toc_astuces' => "Astuces & pièges",
    'aide_service.toc_glossaire' => "Glossaire",
    'aide_service.toc_faq' => "Questions fréquentes",
    'aide_service.connexion_lede' => "Pas d'adresse e-mail ni de mot de passe classique : vous sélectionnez le nom de votre service dans une liste, puis vous saisissez le code qui va avec.",
    'aide_service.shot_login_alt' => "Page de connexion de la GMAO",
    'aide_service.shot_login_cap' => "L'écran de connexion : un nom, un code, un bouton.",
    'aide_service.co_step1_titre' => "Sélectionnez le nom de votre service",
    'aide_service.co_step1_desc' => "Dans la liste déroulante « Qui êtes-vous ? », choisissez votre service (ex : « S. Production »), pas un nom personnel.",
    'aide_service.co_step2_titre' => "Saisissez le code général du service",
    'aide_service.co_step2_desc' => "C'est le même code pour toute votre équipe — différent du code personnel que vous saisirez ensuite dans chaque demande.",
    'aide_service.co_step3_titre' => "Cliquez sur « SE CONNECTER »",
    'aide_service.co_step3_desc' => "Vous arrivez directement sur votre page d'accueil, avec les tuiles du portail.",
    'aide_service.callout_warn_code_perso' => "Le code du service ouvre juste le portail. Pour <b>chaque demande</b> que vous déposez, une étape supplémentaire vous demandera votre <b>nom</b> et un <b>code personnel</b> à vous — différent du code de connexion du service. Ce code personnel sert de signature électronique et sert aussi à ouvrir la messagerie sur vos tickets.",
    'aide_service.shot_erreur_alt' => "Message d'erreur : identifiant ou code incorrect",
    'aide_service.shot_erreur_cap' => "En cas d'erreur, vérifiez le nom sélectionné, le code (sans espace) et le Verr. Maj.",
    'aide_service.accueil_lede' => "Une fois connecté, vous arrivez sur une page à 4 tuiles : c'est le point de départ vers toutes les fonctions du portail.",
    'aide_service.tile1_titre' => "Nouvelle demande de travaux",
    'aide_service.tile1_desc' => "Signaler une panne ou demander une intervention à l'équipe maintenance.",
    'aide_service.tile2_titre' => "Suivi de mes demandes",
    'aide_service.tile2_desc' => "Voir l'état de vos tickets, les retours (ou refus) de la maintenance.",
    'aide_service.tile3_titre' => "Idées pour améliorer la GMAO",
    'aide_service.tile3_desc' => "Proposer une suggestion, un bug ou une fonctionnalité manquante.",
    'aide_service.tile4_titre' => "Aide & questions fréquentes",
    'aide_service.tile4_desc' => "Ce guide que vous êtes en train de lire.",
    'aide_service.callout_tip_badge_rouge' => "Un badge rouge peut apparaître sur <b>deux</b> tuiles : sur <b>Suivi de mes demandes</b>, il indique un nombre de nouveaux messages ou retours de la maintenance ; sur <b>Idées pour améliorer la GMAO</b>, il indique une ou plusieurs réponses de l'administrateur non encore lues sur vos idées envoyées.",
    'aide_service.demande_lede' => "Le formulaire se présente comme un petit assistant guidé, en 4 étapes affichées dans la colonne de gauche. Chaque étape propose une bulle d'aide illustrée, et des icônes <i class=\"fa-solid fa-circle-question\" style=\"color:var(--accent);\"></i> à côté des champs les plus importants ouvrent une explication détaillée.",
    'aide_service.shot_etape1_alt' => "Étape 1 du formulaire de demande : identité et code personnel",
    'aide_service.shot_etape1_cap' => "Étape 1 — Identité : poste, nom, et code personnel.",
    'aide_service.d_step1_titre' => "Identité",
    'aide_service.d_step1_desc' => "Choisissez votre fonction / poste, puis votre nom, puis saisissez votre code personnel (4 caractères minimum).",
    'aide_service.d_step2_titre' => "Lieu",
    'aide_service.d_step2_desc' => "Ce n'est pas une simple liste déroulante : c'est un vrai sélecteur visuel. Une barre <b>« Recherche rapide »</b> (« Nom de machine, zone, secteur, usine... ») permet de taper directement le nom d'une machine ; sinon, vous naviguez par tuiles cliquables (Usine → Secteur → Ligne → Zone → Machine) avec un fil d'Ariane pour revenir en arrière. Une fois la machine choisie, une carte de confirmation s'affiche avec un bouton <b>« Changer de machine »</b> si besoin. Si elle n'existe pas dans la liste, choisissez <b>« Autre / Non listé »</b> (uniquement proposé au niveau Machine) et décrivez-la à l'étape suivante.",
    'aide_service.d_step3_titre' => "Problème",
    'aide_service.d_step3_desc' => "Décrivez la panne (quoi, depuis quand, gravité) et indiquez si c'est urgent — réservé aux arrêts de ligne ou dangers réels. La description doit faire <b>au moins 10 caractères</b> : un compteur sous le champ vous guide en direct (« encore un peu de détail... » puis « ✓ c'est clair ! » une fois le seuil atteint).",
    'aide_service.d_step4_titre' => "Envoi",
    'aide_service.d_step4_desc' => "Un récapitulatif complet s'affiche avant l'envoi définitif à la maintenance. Vous pouvez encore tout modifier via « Modifier ». Une fois envoyée, une fenêtre <b>« Ticket envoyé ! »</b> confirme la transmission, avec deux boutons : <b>« Nouvelle demande »</b> ou <b>« Voir le suivi »</b>.",
    'aide_service.shot_etape2_alt' => "Étape 2 : localisation en cascade",
    'aide_service.shot_etape2_cap' => "Étape 2 — Lieu",
    'aide_service.shot_etape3_alt' => "Étape 3 : description du problème et urgence",
    'aide_service.shot_etape3_cap' => "Étape 3 — Problème",
    'aide_service.callout_tip_envoyee' => "Une fois envoyée, votre demande part immédiatement vers la maintenance avec le statut <span class=\"pill pill-attente\"><span class=\"pill-dot\"></span>En attente</span>. Retrouvez-la à tout moment depuis la tuile <b>« Suivi de mes demandes »</b> sur l'accueil.",
    'aide_service.suivi_lede' => "Pas besoin de rappeler la maintenance pour savoir où en est votre demande : tout est visible sur la page « Suivi de mes demandes », accessible depuis l'accueil.",
    'aide_service.shot_suivi_alt' => "Panneau de suivi des demandes envoyées",
    'aide_service.shot_suivi_cap' => "Vignettes de statistiques, filtres et liste des tickets — cliquez sur une ligne pour voir le détail.",
    'aide_service.h3_5_statuts' => "Les 5 statuts",
    'aide_service.pill_attente_label' => "En attente",
    'aide_service.pill_attente_desc' => "votre demande n'a pas encore été validée par la maintenance.",
    'aide_service.pill_afaire_label' => "À faire",
    'aide_service.pill_afaire_desc' => "validée, un numéro de BI lui a été attribué, elle attend d'être prise en charge.",
    'aide_service.pill_cours_label' => "En cours",
    'aide_service.pill_cours_desc' => "un technicien est dessus.",
    'aide_service.pill_termine_label' => "Terminée",
    'aide_service.pill_termine_desc' => "l'intervention est close, un compte-rendu a été rédigé.",
    'aide_service.pill_refuse_label' => "Refusée",
    'aide_service.pill_refuse_desc' => "la maintenance n'a pas donné suite ; le motif du refus est indiqué dans le détail du ticket.",
    'aide_service.callout_lock_renommage' => "Ces 5 noms sont ceux utilisés par défaut, mais un administrateur peut les <b>renommer</b> depuis Paramètres. Si vous voyez des libellés légèrement différents, c'est normal — l'ordre et le sens restent les mêmes.",
    'aide_service.h3_vignettes' => "Vignettes, recherche et filtres",
    'aide_service.vignettes_p1' => "En haut de la page, <b>5 vignettes cliquables</b> reprennent les 5 statuts avec un compteur — cliquer dessus filtre instantanément la liste. En dessous, une barre de filtres combine :",
    'aide_service.vf_li1' => "une <b>recherche libre</b> (« Rechercher (description, machine, N° BI)... ») qui cherche dans la description, la machine, le numéro de BI et la localisation ;",
    'aide_service.vf_li2' => "un filtre par <b>demandeur</b> et un filtre par <b>statut</b> ;",
    'aide_service.vf_li3' => "un filtre spécifique <b>« Messages non lus »</b>, pour retrouver d'un clic tous les tickets qui attendent votre lecture ;",
    'aide_service.vf_li4' => "un bouton <b>« Réinitialiser »</b> qui efface tous les filtres actifs.",
    'aide_service.vignettes_p2' => "La liste est paginée par blocs de <b>8 tickets</b>, avec des boutons « Précédent » / « Suivant ».",
    'aide_service.h3_carte' => "Ce qu'affiche une carte ou le détail d'un ticket",
    'aide_service.carte_lede' => "Au-delà du statut, plusieurs indicateurs peuvent apparaître sur un ticket :",
    'aide_service.tile_urgent_titre' => "Urgent",
    'aide_service.tile_urgent_desc' => "La priorité choisie à la création de la demande.",
    'aide_service.tile_soustraite_titre' => "Sous-traité",
    'aide_service.tile_soustraite_desc' => "L'intervention est confiée à une entreprise extérieure ; son nom est indiqué.",
    'aide_service.tile_bris_titre' => "Bris de matériel",
    'aide_service.tile_bris_desc' => "La demande concerne une casse accidentelle.",
    'aide_service.tile_visserie_titre' => "Vérif. visserie",
    'aide_service.tile_visserie_desc' => "Un contrôle de serrage a été demandé ou réalisé.",
    'aide_service.frise_p' => "Le détail d'un ticket affiche aussi une <b>frise de parcours</b> en 4 étapes — <i>Envoyée → Validée → Prise en charge → Terminée</i> — une vue simplifiée et complémentaire aux 5 statuts détaillés ci-dessus : chaque étape déjà acquise s'affiche en vert, et seule la prochaine étape attendue reste en bleu. Le champ <b>« Technicien intervenant »</b> se base sur les pointages réels de temps (pas seulement sur le technicien assigné à la création) : il affiche « Aucun pointage enregistré » tant que personne n'a encore pointé de temps dessus.",
    'aide_service.heures_p' => "Dès qu'au moins une heure a été pointée sur le ticket, deux informations supplémentaires apparaissent : les <b>heures d'intervention</b> (le cumul des temps pointés par la maintenance) et la <b>date de réalisation</b> (le jour du dernier pointage). Si la maintenance a joint des photos au ticket, elles s'affichent aussi dans une galerie <b>« Photos jointes »</b> — cliquez sur une photo pour l'agrandir.",
    'aide_service.callout_tip_carnet' => "Tant que l'intervention est en cours, un <b>Carnet de bord</b> peut afficher des notes intermédiaires laissées par le technicien (ex. « pièce commandée, en attente de livraison ») — distinct du <b>rapport final</b> de clôture, qui n'apparaît qu'une fois le ticket Terminé.",
    'aide_service.h3_messagerie' => "La messagerie",
    'aide_service.callout_tip_messagerie' => "Un bouton <b>Messagerie</b> permet d'échanger directement avec le technicien sur votre demande. La fenêtre <b>« Sécurité Messagerie »</b> vous demande de vous identifier avant d'écrire : <b>resélectionnez votre nom</b> dans la liste « Qui êtes-vous ? » <b>et</b> ressaisissez votre code personnel — pas seulement le code seul. C'est aussi via ce canal que vous êtes averti d'un refus.",
    'aide_service.callout_warn_badge_rouge' => "Un badge rouge sur un ticket ou sur la tuile d'accueil signale un <b>message non lu</b> : un retour de la maintenance, ou la notification d'un refus avec son motif.",
    'aide_service.idees_lede' => "Une fonctionnalité qui manque, un bug qui vous embête, une amélioration pratique ? La tuile <b>« Idées pour améliorer la GMAO »</b> est faite pour ça.",
    'aide_service.i_step1_titre' => "Remplissez le formulaire",
    'aide_service.i_step1_desc' => "Votre nom, une catégorie (fonctionnalité, ergonomie, bug, autre), un titre court et une description.",
    'aide_service.i_step2_titre' => "Suivez son statut",
    'aide_service.i_step2_desc' => "Sous le formulaire, retrouvez toutes les idées déjà envoyées par votre service, avec leur statut : Nouvelle, À l'étude, Acceptée, Réalisée, ou Rejetée.",
    'aide_service.i_step3_titre' => "Discutez avec l'administrateur",
    'aide_service.i_step3_desc' => "Chaque idée dépliée ouvre un vrai <b>fil de discussion</b> : l'administrateur peut vous répondre, et vous pouvez répondre à votre tour depuis un champ « Écrire une réponse à l'administrateur... ». Tant qu'aucune réponse n'a été donnée, vous verrez « Pas encore de réponse de l'administrateur. »",
    'aide_service.callout_tip_nouveau' => "Une réponse de l'administrateur non encore lue fait apparaître un badge <b>« NOUVEAU »</b> sur l'idée concernée, et alimente le badge rouge de la tuile <b>« Idées pour améliorer la GMAO »</b> sur votre accueil.",
    'aide_service.annualisation_lede' => "Vos congés payés, RTT, jours fériés et arrêts maladie sont décomptés sur une année complète, pas semaine par semaine — un principe qui s'applique à tous les salariés, pas seulement à l'équipe maintenance. Voici l'essentiel à connaître.",
    'aide_service.h3_1607h' => "Le repère légal : 1607h par an",
    'aide_service.p_1607h' => "La durée légale de travail sur une année est de <b>1607h</b> (35h/semaine en moyenne, journée de solidarité comprise). Ce chiffre est calculé en retirant déjà, sur les 365 jours de l'année, les week-ends, les <b>25 jours de congés payés légaux</b> et les <b>jours fériés</b> — ces jours ne sont donc jamais recomptés une seconde fois dans le total d'heures travaillées.",
    'aide_service.tbl_th_type_jour' => "Type de jour",
    'aide_service.tbl_th_heures_dues' => "Heures dues ce jour-là",
    'aide_service.tbl_th_debite' => "Débite votre avance ?",
    'aide_service.tbl_th_pourquoi' => "Pourquoi",
    'aide_service.row_cp_type' => "Congé payé (CP)",
    'aide_service.row_cp_heures' => "0h",
    'aide_service.row_cp_debite' => "Non",
    'aide_service.row_cp_pourquoi' => "Déjà retiré du calcul des 1607h : ce n'est pas dû, donc jamais décompté une seconde fois.",
    'aide_service.row_demicp_type' => "Demi-congé payé",
    'aide_service.row_demicp_heures' => "3,5h",
    'aide_service.row_demicp_debite' => "Non (demi-journée)",
    'aide_service.row_demicp_pourquoi' => "Même principe que le CP, appliqué à une demi-journée.",
    'aide_service.row_rtt_type' => "RTT",
    'aide_service.row_rtt_heures' => "<b>7h</b>",
    'aide_service.row_rtt_debite' => "<b>Oui</b>",
    'aide_service.row_rtt_pourquoi' => "Contrairement au CP, un RTT « dépense » un crédit d'heures déjà accumulé (vous avez fait plus de 35h en moyenne certaines semaines) : le jour reste dû normalement, ce qui débite bien 7h de votre avance — c'est le principe même du RTT.",
    'aide_service.row_repos_type' => "Repos",
    'aide_service.row_repos_heures' => "0h",
    'aide_service.row_repos_debite' => "Non",
    'aide_service.row_repos_pourquoi' => "Contrepartie légale du repos hebdomadaire d'une rotation variable — ce jour n'a jamais été « gagné » par un surplus d'heures, donc rien n'est dû, et contrairement au RTT il ne consomme aucun crédit.",
    'aide_service.row_ferienontrav_type' => "Jour férié <i>(non travaillé)</i>",
    'aide_service.row_ferienontrav_heures' => "0h",
    'aide_service.row_ferienontrav_debite' => "Non",
    'aide_service.row_ferienontrav_pourquoi' => "Comme le CP, déjà retiré du calcul des 1607h.",
    'aide_service.row_ferietrav_type' => "Jour férié <i>(travaillé)</i>",
    'aide_service.row_ferietrav_heures' => "7h",
    'aide_service.row_ferietrav_debite' => "Non (jour normal)",
    'aide_service.row_ferietrav_pourquoi' => "Compte comme un jour de travail classique, comparé à 7h — pas un « bonus » intégral des heures faites. La majoration de salaire pour un jour férié travaillé est un sujet de paie, distinct de ce compteur.",
    'aide_service.row_maladie_type' => "Arrêt maladie",
    'aide_service.row_maladie_heures' => "7h",
    'aide_service.row_maladie_debite' => "Non (neutre)",
    'aide_service.row_maladie_pourquoi' => "Principe de « neutralisation » : les 7h dues sont automatiquement créditées comme si la journée habituelle avait été faite, pour ne pas pénaliser un salarié qui ne peut pas rattraper une absence subie.",
    'aide_service.callout_warn_piege_rtt' => "<b>Piège fréquent :</b> le RTT n'est pas neutre comme le CP ou le Repos — poser un RTT débite réellement 7h de votre compteur d'avance. Ne le confondez pas avec le Repos, qui lui reste à 0h sans jamais rien débiter.",
    'aide_service.callout_tip_suivi_detaille' => "Aujourd'hui, le suivi détaillé (planning des équipes, objectif annuel, heures réalisées) se fait sur les écrans de l'équipe maintenance, auxquels le portail services n'a pas encore accès directement. Pour connaître votre propre situation (jours posés, compteur d'heures), rapprochez-vous de votre responsable ou du service RH.",
    'aide_service.callout_lock_pedagogique' => "Cet article est une explication pédagogique générale, pas un document contractuel — en cas de doute sur votre situation personnelle, votre responsable ou la RH reste la référence.",
    'aide_service.planning_lede' => "Cette fonction n'existe pas encore pour le portail services — cette section décrit ce qui est envisagé, à titre d'aperçu.",
    'aide_service.callout_lock_pas_dispo' => "<b>Pas encore disponible.</b> L'équipe maintenance dispose déjà d'un planning ; l'objectif est d'ouvrir, à terme, un outil équivalent pour créer et suivre l'emploi du temps de vos équipes directement depuis le portail services.",
    'aide_service.planning_p2' => "Le principe envisagé est celui déjà utilisé côté maintenance : un planning manuel, présenté sous forme de grille journalière — une case par jour et par personne. Un clic sur une case permettrait de poser :",
    'aide_service.planning_li1' => "un <b>poste travaillé</b> (matin, après-midi, nuit ou journée complète), ou",
    'aide_service.planning_li2' => "une <b>absence</b> (congé payé, RTT, maladie, jour férié).",
    'aide_service.shot_planning_alt' => "Grille de planning hebdomadaire utilisée par l'équipe maintenance",
    'aide_service.shot_planning_cap' => "Aperçu de la grille utilisée aujourd'hui par l'équipe maintenance — le même principe est envisagé pour le portail services.",
    'aide_service.callout_tip_bientot' => "Cette section sera complétée par un vrai mode d'emploi dès que la fonction sera mise en service pour le portail services.",
    'aide_service.astuces_li1' => "<b>Retenez bien votre code personnel</b> : c'est lui qui prouve que c'est vous à chaque nouvelle demande, et qui ouvre la messagerie.",
    'aide_service.astuces_li2' => "<b>Soyez précis dans la description</b> : plus elle est claire, plus vite la maintenance peut prioriser et intervenir.",
    'aide_service.astuces_li3' => "<b>Une demande « En attente » n'est pas oubliée</b> : elle attend simplement que la maintenance la valide — ce délai dépend de la charge de l'équipe.",
    'aide_service.astuces_li4' => "<b>N'utilisez « Urgent » que pour un vrai arrêt ou un danger</b>, pour que les priorités restent lisibles pour tout le monde.",
    'aide_service.astuces_li5' => "<b>Une demande refusée n'est pas une erreur de votre part</b> : le motif indiqué explique toujours pourquoi, et vous pouvez recréer une nouvelle demande si besoin.",
    'aide_service.gloss1_dt' => "Code personnel",
    'aide_service.gloss1_dd' => "Suite de 4 caractères minimum qui vous identifie à chaque demande, comme une signature électronique.",
    'aide_service.gloss2_dt' => "Code du service",
    'aide_service.gloss2_dd' => "Le code général utilisé par toute votre équipe pour se connecter au portail — différent du code personnel.",
    'aide_service.gloss3_dt' => "BI",
    'aide_service.gloss3_dd' => "Bon d'Intervention — le numéro attribué à votre demande une fois validée par la maintenance.",
    'aide_service.gloss4_dt' => "Motif du refus",
    'aide_service.gloss4_dd' => "Le texte saisi par un administrateur lorsqu'une demande n'est pas donnée suite, visible dans le détail du ticket refusé.",
    'aide_service.gloss5_dt' => "Carnet de bord",
    'aide_service.gloss5_dd' => "Les notes intermédiaires laissées par le technicien pendant qu'un ticket est encore en cours — distinctes du rapport final de clôture.",
    'aide_service.gloss6_dt' => "Sous-traité",
    'aide_service.gloss6_dd' => "Une intervention confiée à une entreprise extérieure plutôt qu'à un technicien interne ; son nom est indiqué sur le ticket.",
    'aide_service.faq_lede' => "Les réponses courtes, pour aller vite.",
    'aide_service.faq1_q' => "À quoi sert le code personnel ?",
    'aide_service.faq1_li1' => "<b>1ère demande :</b> inventez un code (4 caractères minimum) — il sera mémorisé automatiquement, comme une signature.",
    'aide_service.faq1_li2' => "<b>Demandes suivantes :</b> ressaisissez toujours le même code pour confirmer que c'est bien vous.",
    'aide_service.faq1_li3' => "Il vous sert aussi à vous identifier pour discuter avec la maintenance sur vos tickets (messagerie).",
    'aide_service.faq2_q' => "Je ne trouve pas la machine dans la liste",
    'aide_service.faq2_a' => "Choisissez <b>« Autre / Non listé »</b> à la dernière étape de localisation, puis décrivez précisément la machine et son emplacement dans le champ description.",
    'aide_service.faq3_q' => "Comment bien décrire mon problème ?",
    'aide_service.faq3_li1' => "<b>Quoi :</b> que se passe-t-il ? (bruit, fuite, casse, panne électrique...)",
    'aide_service.faq3_li2' => "<b>Depuis quand :</b> juste maintenant, depuis ce matin...",
    'aide_service.faq3_li3' => "<b>Gravité :</b> la production est-elle arrêtée ? Y a-t-il un danger ?",
    'aide_service.faq4_q' => "Quelle différence entre \"Normal\" et \"Urgent\" ?",
    'aide_service.faq4_a' => "Choisissez <b>Urgent</b> uniquement en cas d'arrêt de ligne ou de danger immédiat. Pour toute intervention classique, laissez <b>Normal</b> — la maintenance priorise ses interventions sur cette base.",
    'aide_service.faq5_q' => "Que veulent dire les statuts de mes tickets ?",
    'aide_service.faq5_a' => "<span class=\"pill pill-attente\" style=\"margin:2px 4px 2px 0;\"><span class=\"pill-dot\"></span>En attente</span> votre demande vient d'être envoyée.<br>\n<span class=\"pill pill-afaire\" style=\"margin:2px 4px 2px 0;\"><span class=\"pill-dot\"></span>À faire</span> validée et planifiée.<br>\n<span class=\"pill pill-cours\" style=\"margin:2px 4px 2px 0;\"><span class=\"pill-dot\"></span>En cours</span> un technicien intervient.<br>\n<span class=\"pill pill-termine\" style=\"margin:2px 4px 2px 0;\"><span class=\"pill-dot\"></span>Terminé</span> intervention close, compte-rendu disponible.<br>\n<span class=\"pill pill-refuse\" style=\"margin:2px 4px 2px 0;\"><span class=\"pill-dot\"></span>Refusée</span> non retenue, motif visible dans le détail.",
    'aide_service.faq6_q' => "Comment échanger avec le technicien sur un ticket ?",
    'aide_service.faq6_a' => "Ouvrez le ticket depuis la page <b>Suivi de mes demandes</b>, puis cliquez sur <b>Messagerie</b>. Vous devrez indiquer votre nom et votre code personnel pour envoyer un message.",
    'aide_service.faq7_q' => "Pourquoi ma demande a-t-elle été refusée ?",
    'aide_service.faq7_a' => "Un administrateur a choisi de ne pas y donner suite (doublon, hors périmètre maintenance...). Le motif exact est toujours indiqué : ouvrez le ticket dans <b>Suivi de mes demandes</b> pour le lire dans l'encart rouge « Motif du refus ».",
    'aide_service.faq8_q' => "Comment proposer une idée pour la GMAO ?",
    'aide_service.faq8_a' => "Depuis l'accueil, cliquez sur la tuile <b>Idées pour améliorer la GMAO</b>. Remplissez le petit formulaire (titre, catégorie, description) : votre idée est transmise à l'équipe GMAO, et vous pouvez suivre son statut — et discuter avec l'administrateur — directement sur la même page.",
    'aide_service.faq9_q' => "Comment retrouver rapidement mes tickets avec un message non lu ?",
    'aide_service.faq9_a' => "Sur <b>Suivi de mes demandes</b>, ouvrez le filtre de statut et choisissez <b>« Messages non lus »</b> — la liste ne garde alors que les tickets qui attendent votre lecture.",
    'aide_service.callout_contact' => "Une question qui ne trouve pas de réponse ici, ou un souci technique avec le portail lui-même ? Contactez l'équipe maintenance / GMAO directement.",

    'aide_annualisation.page_title_tag' => "Congés, RTT & Annualisation - Aide GMAO",
    'aide_annualisation.hero_h1' => "Congés, RTT, maladie & Annualisation",
    'aide_annualisation.hero_tagline' => "Comprendre comment vos heures sont comptées sur l'année — et pourquoi, selon la loi.",
    'aide_annualisation.pill_version' => "Version <b>1.0</b>",
    'aide_annualisation.pill_updated' => "Mis à jour le <b>18/08/2026</b>",
    'aide_annualisation.pill_ecrans' => "Écran concerné <b>Planning</b>",
    'aide_annualisation.pill_sourced' => "Sourcé droit du travail",
    'aide_annualisation.toc_vue_ensemble' => "Vue d'ensemble",
    'aide_annualisation.toc_saisir' => "Poser un CP, RTT, jour férié…",
    'aide_annualisation.toc_formule' => "D'où viennent les 1607h ?",
    'aide_annualisation.toc_traitement' => "Comment chaque absence est comptée",
    'aide_annualisation.toc_ajustements' => "Ajustements de l'objectif (fractionnement, 48h)",
    'aide_annualisation.toc_exemples' => "Exemples concrets chiffrés",
    'aide_annualisation.toc_repere' => "Le repère « 35h/semaine »",
    'aide_annualisation.toc_faq' => "Questions fréquentes",
    'aide_annualisation.toc_glossaire' => "Glossaire",
    'aide_annualisation.toc_sources' => "Sources légales",
    'aide_annualisation.vue_lede' => "L'<b>annualisation</b> du temps de travail, c'est le fait de compter vos heures non pas semaine par semaine, mais sur une année complète — ici, du <b>1er avril au 31 mars</b>. L'objectif à atteindre sur cette période est de <b>1607h</b> (sauf accord individuel différent, réglable en Paramètres). Cet article explique comment ce total est calculé, et surtout comment chaque type de jour non travaillé (congé, RTT, férié, maladie) y est traité.",
    'aide_annualisation.tbl1_th_ou' => "Où ça se passe",
    'aide_annualisation.tbl1_th_usage' => "À quoi ça sert",
    'aide_annualisation.row_planning_label' => "Planning",
    'aide_annualisation.row_planning_desc' => "Pour chaque jour, un clic ouvre une fenêtre où poser un <b>poste</b> travaillé (matin / après-midi / nuit / journée) et/ou un <b>événement</b> (congé payé, demi-congé, RTT, maladie, jour férié), avec les heures effectuées si besoin.",
    'aide_annualisation.row_planning_annuel_label' => "Planning annuel",
    'aide_annualisation.row_planning_annuel_desc' => "Depuis le Planning, un calendrier complet mois par mois avec le détail de chaque jour posé, le total cumulé, l'objectif (modifiable), le fractionnement, et la bulle d'aide qui détaille votre avance/retard.",
    'aide_annualisation.callout_tip_pas_calculer' => "Vous n'avez pas besoin de calculer quoi que ce soit vous-même : posez vos jours normalement, l'outil applique automatiquement les bonnes règles décrites plus bas.",
    'aide_annualisation.saisir_lede' => "Sur l'écran Planning, cliquez sur la case du jour concerné pour votre nom.",
    'aide_annualisation.s_step1_titre' => "Choisissez un poste (si vous travaillez ce jour-là)",
    'aide_annualisation.s_step1_desc' => "Matin, après-midi, nuit ou journée. Renseignez les heures effectuées si elles diffèrent de l'horaire habituel.",
    'aide_annualisation.s_step2_titre' => "Ou choisissez un événement (si vous êtes absent)",
    'aide_annualisation.s_step2_desc' => "Congé payé, RTT, Repos ou Maladie — ces quatre cases sont mutuellement exclusives avec un poste travaillé : vous ne pouvez pas être « en congé » et « en poste matin » le même jour. RTT et Repos se ressemblent mais ne sont pas interchangeables : voir la section suivante pour la différence.",
    'aide_annualisation.s_step3_titre' => "Cas particuliers : demi-congé et jour férié",
    'aide_annualisation.s_step3_desc' => "Contrairement aux autres événements, le <b>demi-congé payé</b> et le <b>jour férié</b> sont des cases à cocher indépendantes qui peuvent se cumuler avec un poste réellement travaillé : c'est le cas d'une journée où vous travaillez la matinée et posez un demi-CP l'après-midi, ou d'un jour férié où vous cochez quand même le poste « Nuit » parce que vous avez travaillé cette nuit-là.",
    'aide_annualisation.callout_warn_ferie_travaille' => "<b>Jour férié travaillé :</b> si vous êtes exceptionnellement amené à travailler un jour férié (cas courant en maintenance industrielle), cochez le poste réellement travaillé (matin/après-midi/nuit/journée) <b>et</b> cochez en plus la case <b>« Jour férié »</b>, puis indiquez les heures réellement effectuées (ex. 8h) — l'outil les comptera normalement dans votre total, en plus du fait que ce jour n'était de toute façon pas dû (voir plus bas). Cocher « Jour férié » ne décoche plus le poste choisi.",
    'aide_annualisation.formule_lede' => "1607h n'est pas un chiffre choisi au hasard : c'est le résultat d'un calcul légal précis, qui part d'une année complète et retire tout ce qui n'est pas un jour de travail dû.",
    'aide_annualisation.donut_num' => "228",
    'aide_annualisation.donut_label' => "jours travaillés<br>sur 365",
    'aide_annualisation.leg_weekends_label' => "Week-ends",
    'aide_annualisation.leg_weekends_jours' => "104 jours",
    'aide_annualisation.leg_cp_label' => "Congés payés",
    'aide_annualisation.leg_cp_jours' => "25 jours",
    'aide_annualisation.leg_feries_label' => "Jours fériés",
    'aide_annualisation.leg_feries_jours' => "8 jours",
    'aide_annualisation.leg_travailles_label' => "Jours travaillés",
    'aide_annualisation.leg_travailles_jours' => "228 jours",
    'aide_annualisation.donut_note' => "228 jours travaillés × 7h = 1596h, + 7h de journée de solidarité = <b>1607h</b> — le détail du calcul juste en dessous.",
    'aide_annualisation.formula_box' => "365 jours calendaires<br>\n<span class=\"op\">−</span> 104 jours de repos hebdomadaire (52 samedis + 52 dimanches)<br>\n<span class=\"op\">−</span> 25 jours de congés payés légaux<br>\n<span class=\"op\">−</span> 8 jours fériés en moyenne tombant sur un jour ouvré<br>\n<span class=\"res\">= 228 jours réellement travaillés</span><br>\n<br>\n228 jours <span class=\"op\">×</span> 7h (35h/semaine ÷ 5 jours) <span class=\"res\">= 1596h</span><br>\n<span class=\"op\">+</span> 7h de journée de solidarité<br>\n<span class=\"res\">= 1607h</span>",
    'aide_annualisation.formule_p2' => "Le point important : <b>les congés payés et les jours fériés sont déjà retirés en amont</b> dans ce calcul. Votre objectif de 1607h n'est donc pas « 1607h de travail plus vos congés en plus » — les congés sont déjà dedans. C'est pour ça que les compter une seconde fois (comme du temps travaillé en plus) ferait dépasser artificiellement l'objectif.",
    'aide_annualisation.callout_law_samedi_p1' => "Une règle d'équipe peut s'ajouter à la loi générale : en plus des <b>25 jours de CP légaux</b>, certaines équipes accordent <b>5 jours supplémentaires à poser uniquement un samedi</b> — ce ne sont pas 5 des 25 jours normaux, mais 5 jours en plus, soit <b>30 jours de congé au total sur l'année</b>. Dans l'outil, ces deux quotas sont suivis séparément dans le récapitulatif du Planning annuel : « Congés payés » (/25) et « CP samedi » (/5).",
    'aide_annualisation.callout_law_samedi_p2' => "Ce type de règle existe généralement dans les entreprises dont l'activité connaît une <b>période haute</b> (par exemple l'été), où travailler le samedi devient possible, voire nécessaire : ces 5 jours supplémentaires compensent cette disponibilité en garantissant des jours de repos posés sur cette journée-là. Ce n'est pas une règle du Code du travail — la raison exacte retenue peut varier selon l'organisation, à confirmer auprès de votre encadrement en cas de doute. Si votre entreprise applique ces 30 jours, pensez à ajuster votre objectif annuel en conséquence depuis Planning annuel ou Paramètres, puisque le seuil par défaut de 1607h suppose la base légale de 25 jours.",
    'aide_annualisation.traitement_lede' => "C'est le cœur du sujet : chaque type de jour non travaillé suit une règle différente, et ce n'est pas arbitraire — chacune vient d'un principe légal précis.",
    'aide_annualisation.tbl2_th_type' => "Type de jour",
    'aide_annualisation.tbl2_th_total' => "Compte dans mon total réel",
    'aide_annualisation.tbl2_th_du' => "Est « dû » (repère 35h/sem.)",
    'aide_annualisation.tbl2_th_pourquoi' => "Pourquoi",
    'aide_annualisation.row2_cp_type' => "Congé payé (CP)",
    'aide_annualisation.row2_cp_total' => "<b>0h</b>",
    'aide_annualisation.row2_cp_du' => "Non",
    'aide_annualisation.row2_cp_pourquoi' => "Déjà déduit dans le calcul des 1607h (voir formule ci-dessus) — un jour de CP n'est simplement pas dû.",
    'aide_annualisation.row2_demicp_type' => "Demi-congé payé",
    'aide_annualisation.row2_demicp_total' => "<b>0h</b>",
    'aide_annualisation.row2_demicp_du' => "Non (moitié de journée)",
    'aide_annualisation.row2_demicp_pourquoi' => "Même principe que le CP, appliqué à une demi-journée.",
    'aide_annualisation.row2_rtt_type' => "RTT",
    'aide_annualisation.row2_rtt_total' => "<b>0h</b>",
    'aide_annualisation.row2_rtt_du' => "<b>Oui (7h)</b>",
    'aide_annualisation.row2_rtt_pourquoi' => "Un RTT « dépense » un crédit d'heures déjà accumulé (vous avez fait plus de 35h en moyenne, la loi vous doit ce jour en échange) : le jour reste dû normalement, ce qui débite bien votre avance de 7h — c'est le principe même du RTT.",
    'aide_annualisation.row2_repos_type' => "Repos",
    'aide_annualisation.row2_repos_total' => "<b>0h</b>",
    'aide_annualisation.row2_repos_du' => "Non",
    'aide_annualisation.row2_repos_pourquoi' => "Contrepartie légale du repos hebdomadaire pour une rotation variable (samedi/dimanche/n'importe quel jour de semaine selon le planning) : ce jour n'a jamais été « gagné » par un surplus d'heures, donc il n'est pas dû — contrairement au RTT, il ne consomme aucun crédit.",
    'aide_annualisation.row2_ferienontrav_type' => "Jour férié <i>(non travaillé)</i>",
    'aide_annualisation.row2_ferienontrav_total' => "0h",
    'aide_annualisation.row2_ferienontrav_du' => "Non",
    'aide_annualisation.row2_ferienontrav_pourquoi' => "Comme le CP, les jours fériés moyens sont déjà retirés dans le calcul des 1607h.",
    'aide_annualisation.row2_ferietrav_type' => "Jour férié <i>(travaillé)</i>",
    'aide_annualisation.row2_ferietrav_total' => "<b>Heures réellement saisies</b>",
    'aide_annualisation.row2_ferietrav_du' => "<b>Oui (7h)</b>",
    'aide_annualisation.row2_ferietrav_pourquoi' => "Un jour férié travaillé compte comme un jour normal dans l'annualisation : 8h travaillées restent 8h, comparées à 7h dues comme n'importe quel autre jour. La majoration de salaire pour un jour férié travaillé est un sujet de paie, distinct de ce compteur.",
    'aide_annualisation.row2_maladie_type' => "Maladie",
    'aide_annualisation.row2_maladie_total' => "<b>7h (crédit automatique)</b>",
    'aide_annualisation.row2_maladie_du' => "Oui (7h, comme un jour normal)",
    'aide_annualisation.row2_maladie_pourquoi' => "Principe de « neutralisation » retenu par la Cour de cassation en annualisation : une absence maladie est comptée comme si le salarié avait fait sa journée habituelle, pour ne pas le pénaliser d'un temps qu'il ne peut pas rattraper.",
    'aide_annualisation.callout_law_rtt_repos' => "<b>RTT et Repos ne sont pas la même chose</b>, malgré des noms proches. Le RTT compense un temps de travail hebdomadaire supérieur à 35h : le poser revient à dépenser un crédit d'heures que vous avez déjà accumulé, donc le jour reste « dû » et débite votre avance de 7h. Le Repos est simplement le repos hebdomadaire auquel tout salarié a droit — chez les équipes en rotation variable (matin/après-midi/nuit, avec des jours de repos qui tombent n'importe quel jour de la semaine selon le cycle), il n'a jamais été « acheté » par des heures en plus, donc il n'est jamais dû.",
    'aide_annualisation.callout_tip_logique' => "Retenez la logique en une phrase : <b>CP, demi-CP, Repos et jours fériés non travaillés sont des jours « non dus »</b> (ils n'apparaissent ni comme dette ni comme crédit) — un jour férié réellement travaillé, lui, redevient un jour normal comparé à 7h, et un <b>RTT reste dû (il débite votre avance)</b> puisqu'il consomme un crédit déjà acquis — alors que <b>la maladie est neutralisée « comme si »</b> — elle est créditée pour ne pas créer de dette que vous ne pourriez pas rattraper.",
    'aide_annualisation.ajustements_lede' => "Au-delà des 1607h de base, deux situations prévues par l'accord d'annualisation réduisent le nombre d'heures réellement dues sur l'année. Elles se règlent depuis la fenêtre <b>Planning annuel</b> (cliquez sur « Voir le planning annuel complet » depuis la fenêtre de planification).",
    'aide_annualisation.tbl3_th_ajustement' => "Ajustement",
    'aide_annualisation.tbl3_th_effet' => "Effet sur l'objectif",
    'aide_annualisation.tbl3_th_qui' => "Qui le règle",
    'aide_annualisation.row3_objectif_ajustement' => "Objectif annuel de base",
    'aide_annualisation.row3_objectif_effet' => "1607h par défaut",
    'aide_annualisation.row3_objectif_qui' => "Vous-même ou un admin, directement depuis Planning annuel (un admin peut aussi le régler pour n'importe qui depuis Paramètres).",
    'aide_annualisation.row3_fractionnement_ajustement' => "Jours de fractionnement",
    'aide_annualisation.row3_fractionnement_effet' => "<b>−7h</b> (1 jour) ou <b>−14h</b> (2 jours)",
    'aide_annualisation.row3_fractionnement_qui' => "Vous-même ou un admin, selon les conditions de prise du congé principal (Art. 6).",
    'aide_annualisation.row3_48h_ajustement' => "Semaines à 48h",
    'aide_annualisation.row3_48h_effet' => "<b>−4h</b> par semaine concernée, détecté automatiquement",
    'aide_annualisation.row3_48h_qui' => "Personne — calculé à partir des heures que vous saisissez.",
    'aide_annualisation.callout_law_fractionnement_p1' => "<b>Fractionnement</b> (Art. 6 de l'accord) : si votre congé principal est pris en une seule fois sur au moins 12 jours ouvrables (dont 2 repos hebdomadaires), la loi vous accorde des jours de repos supplémentaires. Comme ça dépend des conditions exactes de prise du congé, ce n'est pas calculable automatiquement : c'est la RH qui détermine si vous avez droit à 1 ou 2 jours, et un admin le renseigne dans l'outil — l'objectif affiché diminue alors du nombre d'heures correspondant.",
    'aide_annualisation.callout_law_fractionnement_p2' => "<b>Semaines à 48h</b> (Art. 3, périodes de pointe) : les semaines où vous avez réellement travaillé 48h ou plus donnent droit à 4h de repos, déduites automatiquement de l'objectif — l'outil détecte ces semaines lui-même à partir de vos heures saisies, aucune saisie supplémentaire n'est nécessaire.",
    'aide_annualisation.callout_tip_plafond_cp' => "L'accord plafonne aussi le congé principal continu à <b>12 jours ouvrables</b> lorsqu'il chevauche la période du <b>15 juillet au 30 septembre</b> (Art. 6). Si vous dépassez ce plafond, un badge d'alerte apparaît sur la tuile « Congés payés » du récapitulatif annuel, avec le détail au survol.",
    'aide_annualisation.exemples_lede' => "Pour bien visualiser, voici quatre situations types avec le détail du calcul. Le technicien « Léa » est un exemple fictif.",
    'aide_annualisation.ex1_titre' => "Exemple 1 — Une semaine de congés payés",
    'aide_annualisation.ex1_desc' => "Léa pose 5 jours de CP (du lundi au vendredi) sur une semaine où elle aurait normalement travaillé 5 journées de 8h.",
    'aide_annualisation.ex1_calc' => "Total réel de la semaine : 5 × 0h = <b>0h</b><br>\nRepère 35h/semaine de cette semaine : 5 × 0h dû = <b>0h</b><br>\nÉcart : 0h — aucun faux retard créé.",
    'aide_annualisation.ex1_verdict' => "Prendre des congés n'est jamais pénalisant",
    'aide_annualisation.ex2_titre' => "Exemple 2 — Trois jours de maladie",
    'aide_annualisation.ex2_desc' => "Léa est en arrêt maladie 3 jours, sur une semaine où elle était planifiée à 7h/jour.",
    'aide_annualisation.ex2_calc' => "Total réel : 3 × 7h (crédit automatique) = <b>+21h</b><br>\nRepère : 3 × 7h dû = <b>21h</b><br>\nÉcart : 0h — elle reste exactement dans le rythme, sans avoir pu travailler.",
    'aide_annualisation.ex2_verdict' => "Aucune dette d'heures créée par la maladie",
    'aide_annualisation.ex3_titre' => "Exemple 3 — Un jour férié travaillé",
    'aide_annualisation.ex3_desc' => "Le 14 juillet (jour férié), Léa est exceptionnellement mobilisée et travaille 8h de nuit : elle coche le poste « Nuit » <b>et</b> la case « Jour férié », avec 8h saisies.",
    'aide_annualisation.ex3_calc' => "Total réel : <b>+8h</b> (les heures réellement saisies)<br>\nRepère : jour férié mais réellement travaillé, compté comme un jour normal = <b>7h</b><br>\nÉcart : <b>+1h</b> — comme n'importe quelle journée où elle aurait fait 8h au lieu de 7h. La majoration de salaire pour ce jour férié travaillé reste due, mais c'est un sujet de paie, pas de ce compteur.",
    'aide_annualisation.ex3_verdict' => "+1h d'avance, comme un jour normal fait à 8h",
    'aide_annualisation.ex4_titre' => "Exemple 4 — Des journées à 8h au lieu de 7h",
    'aide_annualisation.ex4_desc' => "Léa travaille 20 journées « journée » à 8h chacune (poste habituel de l'équipe), sur une période où le repère légal attend 7h/jour.",
    'aide_annualisation.ex4_calc' => "Total réel : 20 × 8h = <b>160h</b><br>\nRepère : 20 × 7h dû = <b>140h</b><br>\nÉcart : <b>+20h d'avance</b>, simplement parce que sa journée type dure 8h et non 7h.",
    'aide_annualisation.ex4_verdict' => "C'est normal et attendu quand la journée type dure 8h",
    'aide_annualisation.repere_lede' => "Sur votre barre de progression annuelle, un petit repère indique où vous devriez en être <b>aujourd'hui</b> si vous suiviez un rythme régulier de 35h/semaine depuis le 1er avril.",
    'aide_annualisation.repere_li1' => "Du lundi au vendredi, chaque jour écoulé depuis le 1er avril est compté comme dû à raison de 7h/jour.",
    'aide_annualisation.repere_li2' => "Le samedi et le dimanche ne sont dus à rien par défaut (jour de repos) — <b>sauf s'ils sont réellement travaillés</b> (poste + heures saisis), auquel cas ils sont comparés à 7h exactement comme un jour de semaine. Un samedi travaillé 8h ne donne donc que +1h d'avance, pas +8h.",
    'aide_annualisation.repere_li3' => "CP, demi-CP, Repos et jour férié <i>non travaillé</i> ne sont pas dus (0h). Pour le CP/demi-CP/férié, c'est parce qu'ils sont déjà déduits du seuil de 1607h ; le Repos, lui, est simplement le repos hebdomadaire d'une rotation variable, jamais « acheté » par un surplus d'heures. Un jour férié <i>réellement travaillé</i> redevient un jour normal comparé à 7h — travailler un jour férié n'est plus un bonus automatique, seules les heures au-delà de 7h ce jour-là comptent en avance.",
    'aide_annualisation.repere_li4' => "<b>Le RTT, à l'inverse, reste dû (7h)</b> : le poser consomme un crédit d'heures déjà accumulé, donc il débite votre avance de 7h ce jour-là — ne confondez pas avec le Repos ci-dessus, qui lui reste neutre.",
    'aide_annualisation.repere_li5' => "La maladie reste comptée comme due (7h), puisqu'elle est de toute façon créditée à l'identique dans votre total réel — l'écart reste donc neutre.",
    'aide_annualisation.repere_p_avance_retard' => "« Avance » signifie que votre total réel dépasse ce que le rythme légal de 35h/semaine attendait de vous à cette date (le plus souvent parce que vos journées durent 8h et non 7h). « Retard » signifie l'inverse. Aucun des deux n'est un jugement — c'est un simple indicateur de rythme, à comparer à l'objectif annuel final (1607h), qui est la seule échéance qui compte vraiment.",
    'aide_annualisation.callout_tip_badge_jour' => "Dans le <b>Planning annuel</b>, chaque jour déjà passé affiche un petit badge « +Xh » (vert) ou « -Xh » (rouge) à côté des heures saisies, montrant l'écart de ce jour précis par rapport à ce qui était dû. Un récapitulatif du même type apparaît sous le total de chaque mois.",
    'aide_annualisation.faq1_q' => "Mon total d'heures a changé après une mise à jour de l'application, pourquoi ?",
    'aide_annualisation.faq1_a' => "Avant août 2026, l'outil créditait automatiquement 7h par jour de CP posé (en plus des heures éventuellement saisies), pour éviter que prendre des congés ne fasse « reculer » par rapport à l'objectif. Cette logique partait d'une bonne intention mais était incorrecte : les congés payés sont <b>déjà déduits</b> dans le calcul des 1607h (voir la formule plus haut), donc les créditer en plus faisait gonfler artificiellement le total réalisé. Un CP compte désormais pour 0h, ce qui est la valeur légalement correcte.",
    'aide_annualisation.faq2_q' => "Pourquoi la maladie n'est-elle pas traitée comme le CP ?",
    'aide_annualisation.faq2_a' => "Parce que ce n'est pas la même situation juridique. Le CP est un droit <i>prévu</i> et déjà retiré du seuil des 1607h. La maladie est une absence <i>subie</i>, non prévue — la jurisprudence impose de la neutraliser « comme si » le salarié avait travaillé son horaire habituel, pour ne pas créer une dette d'heures qu'il ne pourrait pas rattraper.",
    'aide_annualisation.faq3_q' => "Le RTT, c'est la même chose qu'un congé payé ?",
    'aide_annualisation.faq3_a' => "Non, et leur effet sur votre compteur diffère aussi. Le CP est un droit fixé par la loi (25 jours minimum par an) déjà déduit du seuil de 1607h : il n'est jamais dû, quoi qu'il arrive. Le RTT n'existe pas dans le Code du travail : c'est un mécanisme propre à l'accord d'entreprise, qui compense un temps de travail hebdomadaire supérieur à 35h en vous laissant « reprendre » les heures en trop sous forme de jour de repos — poser un RTT reste donc compté comme un jour dû (7h), ce qui débite votre avance d'autant.",
    'aide_annualisation.faq4_q' => "Quelle est la différence entre RTT et Repos ?",
    'aide_annualisation.faq4_a' => "Le RTT consomme un crédit d'heures que vous avez déjà accumulé en travaillant plus de 35h en moyenne : le jour reste dû (7h), donc le poser réduit votre avance. Le Repos est la contrepartie légale du repos hebdomadaire — pour une équipe en rotation variable (matin/après-midi/nuit, avec des jours de repos qui tombent n'importe quel jour de la semaine selon le cycle), ce repos n'a jamais été « gagné » par un surplus d'heures, donc il n'est jamais dû (0h), sans toucher à votre solde RTT.",
    'aide_annualisation.faq5_q' => "Je suis en avance / en retard sur le repère, dois-je m'inquiéter ?",
    'aide_annualisation.faq5_a' => "Non — c'est un simple indicateur de rythme intermédiaire, pas une obligation. Ce qui compte réellement, c'est le total sur l'année complète (1er avril au 31 mars) comparé à l'objectif de 1607h, affiché en haut de la fenêtre Planning annuel.",
    'aide_annualisation.gloss1_dt' => "Annualisation",
    'aide_annualisation.gloss1_dd' => "Décompte du temps de travail sur une période d'un an (ici : 1er avril au 31 mars) plutôt que semaine par semaine.",
    'aide_annualisation.gloss2_dt' => "CP (congé payé)",
    'aide_annualisation.gloss2_dd' => "Jour de congé légal, acquis à raison de 2,5 jours ouvrables par mois travaillé, soit 25 jours/an minimum.",
    'aide_annualisation.gloss3_dt' => "RTT",
    'aide_annualisation.gloss3_dd' => "Réduction du Temps de Travail : jour de repos compensant un horaire hebdomadaire supérieur à 35h, défini par accord d'entreprise (pas par la loi directement). Consomme un crédit d'heures déjà acquis : reste compté comme dû (7h) dans l'outil.",
    'aide_annualisation.gloss4_dt' => "Repos",
    'aide_annualisation.gloss4_dd' => "Contrepartie légale du repos hebdomadaire pour une rotation variable (jours de repos qui tombent n'importe quel jour de la semaine selon le cycle matin/après-midi/nuit). Contrairement au RTT, jamais dû (0h) et ne consomme aucun crédit.",
    'aide_annualisation.gloss5_dt' => "Jour férié",
    'aide_annualisation.gloss5_dd' => "Jour listé par la loi (1er janvier, 1er mai, 14 juillet…) où le travail n'est en principe pas dû, sauf activité exceptionnellement maintenue.",
    'aide_annualisation.gloss6_dt' => "Neutralisation « comme si »",
    'aide_annualisation.gloss6_dd' => "Principe jurisprudentiel : une absence justifiée et rémunérée (maladie) est comptée comme si l'horaire prévu avait été travaillé, pour ne pas pénaliser le salarié.",
    'aide_annualisation.gloss7_dt' => "Journée de solidarité",
    'aide_annualisation.gloss7_dd' => "7h de travail supplémentaires non rémunérées par an, ajoutées au calcul des 1607h, destinées au financement de l'autonomie des personnes âgées et handicapées.",
    'aide_annualisation.gloss8_dt' => "Repère 35h/semaine",
    'aide_annualisation.gloss8_dd' => "Indicateur de rythme intermédiaire sur la carte de progression : ce que vous « devriez » avoir accumulé à ce jour en suivant un rythme régulier.",
    'aide_annualisation.gloss9_dt' => "Fractionnement",
    'aide_annualisation.gloss9_dd' => "Jours de repos supplémentaires accordés quand le congé principal est pris en continu sur 12 jours ouvrables ou plus (Art. 6) : 1 ou 2 jours selon les conditions, à la discrétion de la RH.",
    'aide_annualisation.sources_lede' => "Les règles décrites dans cet article s'appuient sur le calcul officiel des 1607h et la jurisprudence de la Cour de cassation en matière d'annualisation/modulation du temps de travail.",
    'aide_annualisation.source1' => "Calcul des 1607 heures et annualisation — guide DRH 2026",
    'aide_annualisation.source2' => "RTT et congés payés : quelles différences ?",
    'aide_annualisation.source3' => "Absence maladie et heures supplémentaires — méthode de calcul (Cour de cassation)",
    'aide_annualisation.source4' => "Arrêt maladie et annualisation : les heures supplémentaires",
    'aide_annualisation.callout_lock_pedagogique' => "Cet article est une explication pédagogique, pas un document contractuel. En cas de doute sur votre situation personnelle, rapprochez-vous de la RH ou de votre responsable maintenance.",
    'aide_annualisation.devnote_li1' => "Calcul du total réel : <code>planning.php</code>, <code>annualisation.php</code>, <code>stats_tech.php</code> — <code>SUM(heures) + 7h si poste='maladie'</code>. CP/RTT/férié ne créditent plus rien depuis la correction d'août 2026 (auparavant +7h/+3,5h, incorrect car déjà déduits du seuil 1607h).",
    'aide_annualisation.devnote_li2' => "Repère 35h/semaine : <code>calculerReferenceHeures35h(tech)</code> dans <code>planning.php</code>, jour par jour via <code>referenceDuJour(shift, dStr, isWeekend)</code>. Lundi-vendredi : 7h dû par défaut, 0h si CP/Repos ou <code>jour_ferie</code> coché <i>et non travaillé</i> (<code>estTravaille()</code> vérifie que le poste n'est pas un poste réellement travaillé), 3,5h si demi-congé. <b>Le RTT n'est plus dans cette liste d'exclusion depuis la correction d'août 2026</b> : il reste dû à 7h comme un jour normal, ce qui débite bien l'avance quand il est posé (il consomme un crédit d'heures déjà acquis, contrairement au Repos qui n'en consomme aucun). Samedi-dimanche : 0h par défaut (<code>ligneVide()</code>), sauf si réellement posé/travaillé, auquel cas mêmes règles qu'un jour de semaine. Un jour férié travaillé (poste + heures, <code>jour_ferie=1</code>) n'est donc plus « non dû » : il est comparé à 7h comme un jour normal. La maladie reste due normalement (pas dans la liste d'exclusion) car elle est de toute façon créditée à l'identique côté total réel. Le même <code>referenceDuJour()</code> alimente aussi les badges « +Xh/-Xh » par jour (affichés dès que la ligne n'est pas <code>ligneVide()</code>, donc y compris un RTT sans heures saisies) et le récap mensuel de <code>renderAnnualGrid()</code>.",
    'aide_annualisation.devnote_li3' => "« Repos » (poste <code>repos</code>, catégorie <code>evenement</code>, migré automatiquement dans <code>planning_postes</code> par <code>planning.php</code> et <code>parametres.php</code>) : ajouté en août 2026 pour les équipes en rotation variable, où le repos hebdomadaire ne tombe pas systématiquement le week-end. Traité comme CP dans <code>referenceDuJour()</code> (0h dû, semaine et week-end), mais reste une catégorie distincte du RTT dans le récapitulatif (<code>recap.repos</code>) — les deux ne partagent aucun compteur.",
    'aide_annualisation.devnote_li4' => "Depuis la correction d'août 2026, « Jour férié » n'est plus une valeur exclusive de <code>poste</code> mais une case indépendante (colonne <code>planning_shifts.jour_ferie</code>, même mécanique que <code>demi_conge</code>) : cochable en plus d'un poste réellement travaillé (matin/après-midi/nuit/journée) sans l'effacer. Migration automatique au chargement : les anciennes lignes <code>poste='jour_ferie'</code> deviennent <code>poste=NULL, jour_ferie=1</code>.",
    'aide_annualisation.devnote_li5' => "Quotas CP fixes (25 jours/an + 5 samedis dédiés, soit 30, additifs et non un sous-ensemble) : encodés dans le récapitulatif de <code>renderAnnualGrid()</code>, pas une règle légale générique. Un CP posé un samedi ne consomme que le quota <code>cpSamedi</code>, jamais le quota <code>cp</code>. Les demi-congés n'ont plus de tuile séparée depuis la correction d'août 2026 : ils créditent 0,5 jour directement dans <code>cp</code> ou <code>cpSamedi</code> selon le jour.",
    'aide_annualisation.devnote_li6' => "Objectif effectif (<code>getObjectifEffectif(tech)</code> dans <code>planning.php</code>) = <code>utilisateurs.objectif_heures_annuel</code> − 7h/jour de fractionnement (<code>planning_fractionnement</code>, table par période de référence, éditable par le technicien concerné ou un admin via <code>maintenance.php?action=save_fractionnement</code>) − 4h par semaine ISO où <code>SUM(heures)</code> ≥ 48 (<code>calculerSemaines48h()</code>, détection automatique, aucune saisie dédiée). L'objectif de base est éditable directement depuis Planning annuel par le technicien concerné ou un admin (<code>action=save_objectif</code>), en plus de Paramètres. Le repère 35h/semaine (<code>calculerReferenceHeures35h</code>) déduit lui aussi le fractionnement et les semaines à 48h, pas seulement l'objectif final.",
    'aide_annualisation.devnote_li7' => "Alerte plafond CP (Art. 6, 12 jours ouvrables continus max entre le 15/07 et le 30/09) : détectée dans <code>renderAnnualGrid()</code> en comptant les jours calendaires consécutifs à <code>poste='cp'</code>, un dimanche sans CP ne rompant pas la série (jour de repos hebdo, jamais travaillé). Badge affiché uniquement sur la tuile « Congés payés » du récapitulatif.",

    'aide_parc_machine.page_title_tag' => "Gérer le Parc Machine - Aide GMAO",
    'aide_parc_machine.hero_tagline' => "L'arborescence complète du site — la base sur laquelle reposent toutes les autres pages.",
    'aide_parc_machine.pill_version' => "Version <b>1.2</b>",
    'aide_parc_machine.pill_updated' => "Mis à jour le <b>30/08/2026</b>",
    'aide_parc_machine.pill_ecrans' => "Écran concerné <b>Parc Machine</b>",
    'aide_parc_machine.pill_lecture' => "Lecture pour tous, édition admin",
    'aide_parc_machine.toc_vue_ensemble' => "Vue d'ensemble",
    'aide_parc_machine.toc_explorer' => "Explorer l'arbre",
    'aide_parc_machine.toc_ajouter' => "Ajouter une machine",
    'aide_parc_machine.toc_modifier' => "Modifier, déplacer, réordonner",
    'aide_parc_machine.toc_renommer' => "Renommer un site, secteur, ligne ou zone",
    'aide_parc_machine.toc_supprimer' => "Supprimer une machine",
    'aide_parc_machine.toc_selection_multiple' => "Sélection multiple",
    'aide_parc_machine.toc_schema_usine' => "Schéma Usine C & fiches de vie",
    'aide_parc_machine.toc_categories_schema' => "Catégories visuelles du schéma",
    'aide_parc_machine.toc_source_verite' => "Pourquoi cette page est centrale",
    'aide_parc_machine.toc_droits' => "Qui peut faire quoi",
    'aide_parc_machine.toc_astuces' => "Astuces & pièges",
    'aide_parc_machine.toc_glossaire' => "Glossaire",
    'aide_parc_machine.vue_lede' => "Le <b>Parc Machine</b> est l'arborescence complète de tous les équipements du site, organisée en 5 niveaux. C'est la <b>référence unique</b> : c'est elle qui alimente les menus déroulants de localisation partout ailleurs dans l'application (création d'un bon d'intervention, plan préventif, planning...).",
    'aide_parc_machine.tree_usine' => "Usine",
    'aide_parc_machine.tree_secteur' => "Secteur",
    'aide_parc_machine.tree_ligne' => "Ligne",
    'aide_parc_machine.tree_zone' => "Zone",
    'aide_parc_machine.tree_machine' => "Machine",
    'aide_parc_machine.vue_p2' => "En haut de la page, un sous-titre récapitule les totaux : <i>« X site(s) · X secteurs · X lignes · X zones · X machines »</i>, et chaque nœud de l'arbre affiche un badge avec le nombre de machines qu'il contient.",
    'aide_parc_machine.shot_arbre_alt' => "Arbre du Parc Machine avec recherche et filtres par type d'équipement",
    'aide_parc_machine.shot_arbre_cap' => "L'arbre complet du Parc Machine : recherche, chips de filtre par type, et les nœuds Usine (violet) / Zone (orange) avec leur compteur.",
    'aide_parc_machine.callout_tip_lecture_seule' => "Un technicien ou un membre de la maintenance voit exactement le même arbre qu'un admin (consultation complète), mais en <b>lecture seule</b> — un badge <b>« Lecture seule »</b> remplace le bouton d'ajout en haut à droite.",
    'aide_parc_machine.explorer_lede' => "Tous les rôles disposent des mêmes outils de navigation.",
    'aide_parc_machine.card_recherche_titre' => "Recherche",
    'aide_parc_machine.card_recherche_desc' => "Tape le nom d'une machine, d'une zone, d'une ligne... Les résultats se surlignent en jaune, et les nœuds parents se déplient automatiquement pour les révéler.",
    'aide_parc_machine.card_filtrer_titre' => "Filtrer par type d'équipement",
    'aide_parc_machine.card_filtrer_desc' => "Des chips sous la recherche (Mécanique, Électrique, Froid...) permettent d'isoler les machines d'un seul type. Se combine avec la recherche.",
    'aide_parc_machine.card_deplier_titre' => "Tout déplier / replier",
    'aide_parc_machine.card_deplier_desc' => "Deux boutons dédiés. L'état de chaque nœud (ouvert/fermé) est mémorisé sur votre poste d'une visite à l'autre.",
    'aide_parc_machine.card_chevrons_titre' => "Chevrons cliquables",
    'aide_parc_machine.card_chevrons_desc' => "Chaque nœud se déplie/replie individuellement d'un clic sur son chevron.",
    'aide_parc_machine.ajouter_lede' => "Bouton <b>« + Ajouter une machine »</b> en haut à droite, ou icône <b>« + »</b> au survol d'une zone dans l'arbre (pré-remplit directement son emplacement). Ouvre un panneau latéral.",
    'aide_parc_machine.a_step1_titre' => "Choisissez l'emplacement",
    'aide_parc_machine.a_step1_desc' => "Usine/lieu → Secteur → Ligne → Zone, en cascade. Chaque liste propose les valeurs déjà existantes <b>+ une option « + Nouveau... »</b> qui ouvre un champ libre pour créer un nœud à la volée. Un aperçu du chemin complet s'affiche en direct sous les champs.",
    'aide_parc_machine.a_step2_titre' => "Nommez la machine",
    'aide_parc_machine.a_step2_desc' => "Champ obligatoire.",
    'aide_parc_machine.a_step3_titre' => "Choisissez un type d'équipement (optionnel)",
    'aide_parc_machine.a_step3_desc' => "Présenté en tuiles cliquables plutôt qu'en menu déroulant — une tuile par type déjà connu, plus une tuile <b>« Autre »</b> pour en créer un nouveau à la volée.",
    'aide_parc_machine.a_step4_titre' => "Enregistrez",
    'aide_parc_machine.a_step4_desc' => "Les 4 champs de localisation et le nom sont tous obligatoires — sinon : « Veuillez remplir tous les champs. »",
    'aide_parc_machine.callout_tip_reouvre' => "Après l'enregistrement, le panneau <b>se rouvre automatiquement pré-rempli sur le même emplacement</b> — pratique pour ajouter plusieurs machines d'affilée dans la même zone sans tout ressaisir.",
    'aide_parc_machine.card_modifier_titre' => "Modifier une machine",
    'aide_parc_machine.card_modifier_desc' => "Icône crayon au survol d'une ligne machine, ou clic direct sur la machine. Même formulaire que l'ajout, pré-rempli.",
    'aide_parc_machine.card_glisser_titre' => "Glisser-déposer",
    'aide_parc_machine.card_glisser_desc' => "Réorganisez librement l'ordre des machines, zones, lignes et secteurs par glisser-déposer. Déplacer une machine vers une autre zone change réellement son emplacement en base.",
    'aide_parc_machine.callout_tip_historique_suit' => "Modifier une machine (nom, ou emplacement) <b>répercute automatiquement le changement sur son historique d'interventions</b> (table des BI) : l'historique suit la machine, il ne se casse pas.",
    'aide_parc_machine.renommer_lede' => "Icône crayon au survol de la ligne du nœud concerné (pas une machine, mais un niveau de regroupement). Ouvre la fenêtre <b>« Renommer »</b>.",
    'aide_parc_machine.callout_tip_renommage_masse' => "Renommer une usine, un secteur ou une zone <b>renomme d'un coup toutes les machines qu'elle contient</b>, et met à jour l'historique d'interventions correspondant. C'est un renommage en masse, pas juste cosmétique.",
    'aide_parc_machine.renommer_p2' => "Un nœud (secteur, ligne, zone) qui n'a plus aucune machine rattachée <b>disparaît automatiquement</b> de l'arbre — il n'y a pas besoin de le supprimer explicitement.",
    'aide_parc_machine.supprimer_lede' => "Icône poubelle au survol d'une ligne machine, puis confirmation dans une fenêtre dédiée.",
    'aide_parc_machine.callout_warn_suppression' => "<b>Aucune vérification n'est faite</b> sur l'historique lié : supprimer une machine ne supprime pas ses interventions ni ses plans préventifs passés, mais ceux-ci deviennent « orphelins » — la machine n'existera plus dans les listes déroulantes des autres pages, alors que son historique reste consultable là où il a déjà été enregistré. Réfléchissez avant de supprimer une machine qui a un historique actif : un simple renommage est presque toujours préférable.",
    'aide_parc_machine.selection_lede' => "Bouton <b>« Sélection multiple »</b> en haut de page : fait apparaître une case à cocher devant chaque machine.",
    'aide_parc_machine.selection_p2' => "Cocher une ou plusieurs machines fait apparaître une barre flottante en bas de l'écran, avec le bouton <b>« Assigner un type... »</b> — pratique pour reclasser d'un coup toutes les machines d'un même type qui n'en avaient pas encore, plutôt que de les modifier une par une. Là aussi, une tuile <b>« Autre »</b> permet de saisir un nom de type qui n'existe pas encore dans un petit champ qui apparaît juste en dessous.",
    'aide_parc_machine.schema_lede' => "Bouton <b>« Schéma Usine C »</b> en haut de page (visible par tous, admin comme technicien) : ouvre une vue interactive de la ligne C, avec chaque machine et chaque vis/tapis numéroté cliquable.",
    'aide_parc_machine.card_tri_titre' => "Salle de tri",
    'aide_parc_machine.card_tri_desc' => "Herse, batteurs, Sinex, Aéro 1/2, vibrants, broyeur, et les 36 vis numérotées, présentées en deux lignes de flux : « ligne produit » (vis 1 à 25) et « ligne déchets » (vis 26 à 36).",
    'aide_parc_machine.card_cond_titre' => "Conditionnement / Palettisation",
    'aide_parc_machine.card_cond_desc' => "Doseur, ensacheuse, fermeuses, détecteur à métaux, balance, étiqueteuse, robot, filmeuse... et les 19 tapis Pattyn (T1 à T19).",
    'aide_parc_machine.schema_p2' => "Cliquer sur une machine ou un numéro ouvre sa <b>fiche de vie</b>, avec 6 onglets :",
    'aide_parc_machine.li_fiche_technique' => "<b>Fiche technique</b> : en haut, un encart affiche le nom de la machine du Parc Machine rattachée ainsi que sa localisation complète (usine / secteur / ligne / zone), récupérés automatiquement — jamais ressaisis à la main. Suivent les références moteur, réducteur, courroie, roulements avant/arrière, numéros de moteur et de câble, et <b>repère automate</b> (le numéro utilisé côté schémas électriques/automatisme, ex. <code>201052</code>) — distinct du numéro mécanique (vis/tapis).",
    'aide_parc_machine.li_historique_bi' => "<b>Historique BI</b> : si la fiche est rattachée à une machine du Parc Machine, la liste des bons d'intervention déjà réalisés s'affiche automatiquement, avec sur chaque carte le type d'intervention, une éventuelle casse ou intervention sous-traitée, et un aperçu du compte-rendu. Cliquer sur une carte ouvre le rapport d'intervention complet ; un admin peut y réouvrir un bon déjà terminé.",
    'aide_parc_machine.li_interventions' => "<b>Interventions</b> : un journal en saisie libre, pour noter une intervention même sans passer par un BI formel.",
    'aide_parc_machine.li_documentation' => "<b>Documentation</b> : upload de documents techniques (PDF, images, Word, Excel) depuis n'importe quel poste du réseau — stockés par élément. Réservé aux admins. Fichiers jusqu'à 300 Mo.",
    'aide_parc_machine.li_devis' => "<b>Devis</b> : même principe que Documentation (mêmes formats, mêmes 300 Mo), pour centraliser les devis reçus sur cette machine — réservé aux admins également.",
    'aide_parc_machine.li_aide_pannes' => "<b>Aide / Pannes connues</b> : mémos libres (panne constatée + solution) pour garder trace des pannes récurrentes et de leur remède, consultables par toute l'équipe.",
    'aide_parc_machine.callout_tip_plan_reprend' => "Le plan reprend la position, la forme et la couleur exactes des schémas techniques PowerPoint d'origine.",
    'aide_parc_machine.callout_lock_droits_fiche' => "Admin et technicien voient tous les deux la machine du Parc Machine rattachée (nom + localisation) et peuvent tous les deux remplir la fiche technique et ajouter une intervention. Seul l'<b>admin</b> peut envoyer ou supprimer un document/devis, et rattacher/détacher une fiche à une machine du Parc Machine (pour l'historique BI automatique).",
    'aide_parc_machine.h3_modifier_plan' => "Modifier le plan lui-même (admin)",
    'aide_parc_machine.modifier_plan_p' => "Bouton <b>« Modifier le plan »</b> en haut du schéma (admin uniquement) : chaque forme devient déplaçable et redimensionnable directement à la souris (ou au doigt sur tablette). Un <b>clic gauche</b> sélectionne une forme pour la déplacer/redimensionner ; un <b>clic droit</b> (ou l'ajout d'une nouvelle forme) ouvre en plus le panneau <b>« Propriétés de la forme »</b> :",
    'aide_parc_machine.li_texte_forme' => "<b>Texte</b> affiché sur la forme, et <b>Forme</b> (large bibliothèque : rectangles, cercles, triangles, polygones, flèches, symboles d'organigramme...).",
    'aide_parc_machine.li_categorie' => "<b>Catégorie</b> : <code>Propriétés libres</code> (par défaut, tous les réglages ci-dessous restent visibles et modifiables directement) ou une des catégories créées dans <a href=\"#categories-schema\">Paramètres</a> (Vis, Convoyeur...). Choisir une catégorie applique aussitôt ses couleurs et ses valeurs de départ, puis <b>replie les réglages détaillés</b> derrière un bouton <b>« Afficher les réglages avancés »</b> — à ouvrir pour ajuster cette forme précise sans toucher aux autres. L'icône <i class=\"fa-solid fa-rotate\"></i> à côté du menu réapplique les valeurs de la catégorie déjà sélectionnée (utile si ses couleurs ont été modifiées entretemps dans Paramètres).",
    'aide_parc_machine.li_couleurs' => "<b>Couleurs</b> : fond / bordure / texte, case « Sans bordure », case « Dégradé » (2 couleurs, avec un choix de sens) et <b>Effet</b> (Aucun, Ombre, Relief, Creux, Lueur).",
    'aide_parc_machine.li_taille_rotation' => "<b>Taille &amp; rotation</b> : largeur, hauteur, taille du texte, <b>Rotation forme</b> et <b>Rotation texte</b> (deux réglages indépendants).",
    'aide_parc_machine.li_comportement' => "<b>Comportement</b> : <b>Cliquable</b> (décoche pour transformer une machine en simple élément décoratif, ou coche l'inverse sur un élément de fond pour lui donner une fiche de vie) et l'ordre avant/arrière-plan.",
    'aide_parc_machine.li_supprimer_forme' => "<b>Supprimer cette forme</b> — retire aussi sa fiche de vie, ses interventions et ses documents.",
    'aide_parc_machine.p_ajouter_forme' => "Bouton <b>« + Ajouter une forme »</b> pour créer un nouvel élément de toutes pièces. Chaque changement s'enregistre automatiquement (pas de bouton « Enregistrer » séparé).",
    'aide_parc_machine.callout_tip_rotation_texte' => "Le texte d'une forme <b>plus haute que large</b> (une vis, par exemple) pivote automatiquement pour se lire de bas en haut (tête penchée à gauche), que ce soit en tapant une largeur/hauteur ou en redimensionnant à la souris — et repasse à l'horizontale si la forme redevient plus large que haute. Cet automatisme ne touche jamais une rotation de texte choisie manuellement.",
    'aide_parc_machine.categories_lede' => "Dans <b>Paramètres → Catégories du schéma</b> (ou via l'icône <i class=\"fa-solid fa-gear\"></i> à côté de « + Ajouter une forme » dans le schéma, qui y mène en un clic), l'admin peut créer des catégories réutilisables — <i>Vis</i>, <i>Vis déchets</i>, <i>Convoyeur</i>... — pour habiller d'un coup toutes les formes d'un même type plutôt que de régler chaque forme une par une.",
    'aide_parc_machine.categories_p2' => "Une catégorie regroupe deux types de réglages, avec un comportement volontairement différent pour chacun :",
    'aide_parc_machine.li_apparence' => "<b>Apparence</b> (couleur de fond, dégradé, bordure, effet) : <b>toujours synchronisée</b>. Modifier ces couleurs dans Paramètres répercute aussitôt le changement sur toutes les formes déjà assignées à cette catégorie.",
    'aide_parc_machine.li_valeurs_depart' => "<b>Valeurs de départ</b> (forme, taille, rotation, texte par défaut, cliquable) : appliquées <b>une seule fois</b>, au moment où la catégorie est choisie sur une forme dans le schéma. Un changement ultérieur de ces valeurs dans Paramètres ne modifie jamais les formes déjà assignées — leurs réglages individuels (taille ajustée à la main, rotation, texte propre à chaque machine...) sont donc toujours préservés.",
    'aide_parc_machine.callout_tip_exemple_vis' => "Utile en pratique : change la couleur d'une catégorie « Vis déchets » dans Paramètres, et les 36 vis déjà en « Vis déchets » sur le schéma changent de couleur d'un coup — sans perdre les tailles et rotations réglées individuellement pour chacune.",
    'aide_parc_machine.source_lede' => "Le Parc Machine est la <b>source unique</b> des listes déroulantes de localisation utilisées ailleurs dans l'application.",
    'aide_parc_machine.route_tag' => "Utilisé par",
    'aide_parc_machine.route1_titre' => "Création d'un BI / demande",
    'aide_parc_machine.route1_desc' => "La cascade Usine → Secteur → Zone → Machine, dans <a href=\"aide_ot.php\">Saisie &amp; Historique</a> et le portail de demande, vient directement d'ici.",
    'aide_parc_machine.route2_titre' => "Préventif & Planning",
    'aide_parc_machine.route2_desc' => "Les plans de maintenance préventive et certains formulaires du Planning s'appuient sur la même liste de machines.",
    'aide_parc_machine.callout_warn_absente' => "Si une machine <b>n'apparaît pas</b> dans un menu déroulant ailleurs dans l'application, c'est presque toujours parce qu'elle n'existe pas — ou plus — dans le Parc Machine. La solution est de venir la créer ici en premier.",
    'aide_parc_machine.tbl_th_action' => "Action",
    'aide_parc_machine.tbl_th_technicien' => "Technicien",
    'aide_parc_machine.tbl_th_admin' => "Admin",
    'aide_parc_machine.droit1_action' => "Consulter l'arbre, rechercher, filtrer",
    'aide_parc_machine.droit2_action' => "Ajouter / modifier / déplacer une machine",
    'aide_parc_machine.droit3_action' => "Renommer un site / secteur / ligne / zone",
    'aide_parc_machine.droit4_action' => "Supprimer une machine",
    'aide_parc_machine.droit5_action' => "Assigner un type en masse",
    'aide_parc_machine.astuces_li1' => "<b>Préférez renommer plutôt que supprimer + recréer</b> une machine ou une zone : le renommage conserve tout l'historique, la suppression le déconnecte.",
    'aide_parc_machine.astuces_li2' => "<b>« + Nouveau... »</b> dans les champs de localisation crée un vrai nœud dès qu'une machine y est rattachée — pas besoin de créer un « secteur vide » à l'avance.",
    'aide_parc_machine.astuces_li3' => "<b>Un nœud sans machine disparaît tout seul</b> de l'arbre — normal, ce n'est pas un bug.",
    'aide_parc_machine.astuces_li4' => "<b>La sélection multiple</b> ne sert qu'à assigner un type d'équipement en masse — il n'existe pas de suppression groupée.",
    'aide_parc_machine.gloss1_dt' => "Nœud",
    'aide_parc_machine.gloss1_dd' => "Un niveau de l'arborescence (une usine, un secteur, une ligne ou une zone).",
    'aide_parc_machine.gloss2_dt' => "Type d'équipement",
    'aide_parc_machine.gloss2_dd' => "Une catégorie technique (Mécanique, Électrique...), configurable depuis Paramètres.",
    'aide_parc_machine.gloss3_dt' => "Source de vérité",
    'aide_parc_machine.gloss3_dd' => "La donnée de référence dont dépendent les autres pages — ici, le Parc Machine pour toute localisation.",
    'aide_parc_machine.devnote_intro' => "Points relevés en analysant le code, à garder en tête côté administration :",
    'aide_parc_machine.devnote_li1' => "Il n'existe aucune clé étrangère réelle entre <code>machines</code> et <code>taches</code>/plans préventifs — la liaison se fait par correspondance de texte (usine+secteur+zone+nom). La suppression d'une machine ne casse donc rien techniquement, mais rend son historique orphelin du référentiel.",
    'aide_parc_machine.devnote_li2' => "Renommer une <b>ligne</b> ne met pas à jour <code>taches</code> (cette table n'a pas de colonne <code>ligne</code>) — seuls usine/secteur/zone/machine sont propagés.",
    'aide_parc_machine.devnote_li3' => "Un type d'équipement créé « à la volée » via la tuile « Autre » n'est pas ajouté à la table de référence <code>types_equipement</code> — il n'apparaît que tant qu'au moins une machine l'utilise, avec une icône générique.",

    'aide_sous_traitants.page_title_tag' => "Gérer les Sous-traitants - Aide GMAO",
