    'aide_sous_traitants.toc_astuces' => "Astuces & pièges",
    'aide_sous_traitants.toc_glossaire' => "Glossaire",
    'aide_sous_traitants.vue_lede' => "L'écran <b>Sous-traitants</b> est le tableau de bord de toutes les entreprises extérieures qui interviennent sur le site : qui est planifié, qui est physiquement présent en ce moment, et l'historique de ce qui a déjà été fait. Une intervention sous-traitée reste un <b>bon d'intervention (BI)</b> comme un autre — elle apparaît avec les mêmes numéros et le même détail que ceux créés depuis <a href=\"aide_ot.php\">Saisie &amp; Historique</a>, avec juste une étiquette « sous-traité » en plus.",
    'aide_sous_traitants.vue_p2' => "Trois zones structurent la page :",
    'aide_sous_traitants.card_planification_titre' => "Planification",
    'aide_sous_traitants.card_planification_desc' => "Le tableau des interventions à venir ou en pause, avec leur Plan de Prévention.",
    'aide_sous_traitants.card_sursite_titre' => "Actuellement sur site",
    'aide_sous_traitants.card_sursite_desc' => "Des cartes en temps réel pour chaque entreprise physiquement présente.",
    'aide_sous_traitants.card_historique_titre' => "Historique",
    'aide_sous_traitants.card_historique_desc' => "Les interventions déjà clôturées (accessible via un bouton dédié).",
    'aide_sous_traitants.vue_p3' => "Trois compteurs en haut de page donnent un état des lieux immédiat : <b>Entreprises sur site</b>, <b>Interventions planifiées</b>, et <b>PdP Manquants / Expirés</b> (une alerte à surveiller de près, voir plus bas).",
    'aide_sous_traitants.shot_dashboard_alt' => "Tableau de bord des sous-traitants : compteurs, planification et présence sur site",
    'aide_sous_traitants.shot_dashboard_cap' => "Le tableau de bord complet : les 3 compteurs, la planification, et le panneau « Actuellement sur site ».",
    'aide_sous_traitants.planifier_lede' => "Bouton <b>« NOUVELLE INTERVENTION »</b> en haut du tableau de planification.",
    'aide_sous_traitants.p_step1_titre' => "Cochez une ou plusieurs entreprises",
    'aide_sous_traitants.p_step1_desc' => "La liste « Entreprise Extérieure » propose des cases à cocher. Cocher plusieurs entreprises crée <b>une intervention distincte par entreprise</b>, chacune avec son propre numéro de BI.",
    'aide_sous_traitants.p_step2_titre' => "Renseignez le type, la date et l'heure",
    'aide_sous_traitants.p_step2_desc' => "Type (Chantier / Préventif / Curatif), date de l'intervention, heure d'arrivée prévue (8h par défaut).",
    'aide_sous_traitants.p_step3_titre' => "Choisissez la localisation",
    'aide_sous_traitants.p_step3_desc' => "Cascade Usine → Secteur → Zone → Machine, chaque menu se débloquant quand le précédent est rempli (alimentée par le <a href=\"aide_parc_machine.php\">Parc Machine</a>).",
    'aide_sous_traitants.p_step4_titre' => "Désignez le technicien responsable du suivi",
    'aide_sous_traitants.p_step4_desc' => "Un membre de l'équipe maintenance qui reste le point de contact interne pour cette intervention.",
    'aide_sous_traitants.p_step5_titre' => "Décrivez la nature des travaux",
    'aide_sous_traitants.p_step5_desc' => "Champ obligatoire, ex. « Remplacement du moteur tapis... ». Cochez « CASSE » si l'intervention fait suite à un bris accidentel.",
    'aide_sous_traitants.p_step6_titre' => "Validez avec « CRÉER LE BON D'INTERVENTION »",
    'aide_sous_traitants.p_step6_desc' => "Sans entreprise cochée, sans date ou sans description, l'application refuse et affiche : « Veuillez cocher au moins une entreprise, et remplir la date et la description ! »",
    'aide_sous_traitants.callout_tip_numero_bi' => "Le <b>numéro de BI</b> (ex. <code>BI26-014</code>) est généré automatiquement, comme pour n'importe quelle intervention. Le technicien responsable désigné reçoit aussi, dès la création, un <b>pointage à 0h</b> qui le rattache officiellement à ce BI — il apparaîtra dans son planning dès ce moment-là, même avant d'avoir réellement pointé du temps.",
    'aide_sous_traitants.planifier_p2' => "Le crayon sur une ligne du tableau ouvre la même fenêtre en mode <b>« Modifier la Planification »</b>, pré-remplie.",
    'aide_sous_traitants.presence_lede' => "Une intervention sous-traitée suit un cycle de présence, distinct du statut du BI lui-même.",
    'aide_sous_traitants.cy_planifie_label' => "Planifié",
    'aide_sous_traitants.cy_planifie_trig' => "Créé via « NOUVELLE INTERVENTION »",
    'aide_sous_traitants.cy_who_vous' => "Vous",
    'aide_sous_traitants.cy_sursite_label' => "Sur site",
    'aide_sous_traitants.cy_sursite_trig' => "Bouton « FAIRE ENTRER » dans le tableau",
    'aide_sous_traitants.cy_pause_label' => "En pause",
    'aide_sous_traitants.cy_pause_trig' => "Bouton « SORTIR (PAUSE) » sur la carte",
    'aide_sous_traitants.cy_termine_label' => "Terminée",
    'aide_sous_traitants.cy_termine_trig' => "Bouton « CLÔTURER » + compte-rendu",
    'aide_sous_traitants.presence_p2' => "Une entreprise « sur site » apparaît en carte verte pulsante dans le panneau « Actuellement sur site ». Le bouton <b>« SORTIR (PAUSE) »</b> ne clôture rien : le technicien quitte simplement l'usine, l'intervention repasse dans le tableau de planification avec un badge orange <b>« EN PAUSE »</b>, prête à être « refait entrer » plus tard.",
    'aide_sous_traitants.cloturer_lede' => "Depuis une carte « sur site », le bouton vert <b>« CLÔTURER »</b> ouvre la fenêtre de clôture.",
    'aide_sous_traitants.callout_warn_compte_rendu' => "Le champ <b>« Compte-rendu d'intervention »</b> est obligatoire. Si vous essayez de clôturer sans rien écrire : <i>« Oups ! Le compte-rendu est obligatoire pour pouvoir clôturer l'intervention de l'entreprise extérieure. »</i>",
    'aide_sous_traitants.cloturer_p2' => "Une fois confirmée, l'intervention passe au statut <b>Terminée</b> et bascule dans l'historique.",
    'aide_sous_traitants.pdp_lede' => "Le PdP est le document de sécurité qui encadre l'intervention d'une entreprise extérieure. Son état est calculé automatiquement à partir de la date de fin de validité renseignée dans l'annuaire.",
    'aide_sous_traitants.tbl1_th_badge' => "Badge",
