    'aide_sous_traitants.badge_expire' => "PdP Expiré",
    'aide_sous_traitants.cond_expire' => "La date de fin de validité est dépassée.",
    'aide_sous_traitants.badge_attente' => "En attente",
    'aide_sous_traitants.cond_attente' => "Aucune date de fin renseignée pour l'entreprise.",
    'aide_sous_traitants.pdp_p2' => "Chaque entreprise a un <b>type de PdP</b> dans l'annuaire, qui change la logique d'affichage :",
    'aide_sous_traitants.route_tag_annuel' => "Type annuel",
    'aide_sous_traitants.route_annuel_titre' => "PdP Annuel",
    'aide_sous_traitants.route_annuel_desc' => "Le statut suit réellement la date de fin de validité (badge vert/rouge/orange).",
    'aide_sous_traitants.route_tag_ponctuel' => "Type ponctuel",
    'aide_sous_traitants.route_ponctuel_titre' => "PdP Ponctuel",
    'aide_sous_traitants.route_ponctuel_desc' => "Refait à chaque chantier : le statut est toujours forcé à « ok » (pas de fausse alerte rouge), affiché avec un badge orange spécifique et la mention « Lié au chantier en cours » à la place d'une date.",
    'aide_sous_traitants.callout_tip_bouclier' => "Depuis l'annuaire, l'icône <b>bouclier violet</b> génère un <b>PdP vierge</b> pré-rempli avec les coordonnées de l'entreprise, prêt à faire signer (nouvel onglet). Une fois signé et scanné, le PDF s'attache à la fiche entreprise (icône PDF rouge) et devient consultable en un clic depuis le tableau de planification.",
    'aide_sous_traitants.pdp_p3' => "Le compteur <b>« PdP Manquants / Expirés »</b> en haut de page surveille <i>toutes</i> les entreprises de l'annuaire, pas seulement celles ayant une intervention en cours — c'est un indicateur de conformité globale à consulter régulièrement.",
    'aide_sous_traitants.annuaire_lede' => "Accessible via le bouton <b>« Gérer l'annuaire des entreprises »</b>, <b>réservé aux administrateurs</b>.",
    'aide_sous_traitants.annuaire_p2' => "Chaque fiche entreprise regroupe : nom, contact, téléphone, email, type de PdP, date de fin de validité, et le fichier PDF du PdP signé.",
