    'aide_sous_traitants.callout_warn_suppression_entreprise' => "Supprimer une entreprise de l'annuaire est <b>définitif</b>, avec une simple confirmation. Les interventions déjà réalisées avec cette entreprise restent visibles dans l'historique, mais la fiche entreprise associée n'existe plus.",
    'aide_sous_traitants.historique_lede' => "Bouton <b>« HISTORIQUE »</b> en haut du tableau de planification : les 100 dernières interventions sous-traitées clôturées, avec numéro de BI (cliquable), date, entreprise, machine, techniciens ayant pointé, et le compte-rendu.",
    'aide_sous_traitants.historique_p2' => "Depuis la fiche détail d'une entreprise dans l'annuaire, un même tableau d'historique est filtré <b>pour cette entreprise uniquement</b> — pratique pour retrouver rapidement tout ce qu'un prestataire a fait sur le site.",
