    'aide_sous_traitants.astuces_li1' => "<b>Le filtre « Cette semaine / Ce mois-ci / Toutes »</b> en haut du tableau de planification n'est pour l'instant pas actif — il n'a aucun effet sur l'affichage.",
    'aide_sous_traitants.astuces_li2' => "<b>Surveillez régulièrement le compteur « PdP Manquants / Expirés »</b> — c'est le seul endroit qui vous alerte sur les entreprises en défaut de conformité sécurité, même sans intervention en cours.",
    'aide_sous_traitants.astuces_li3' => "<b>Ne confondez pas « SORTIR (PAUSE) » et « CLÔTURER »</b> : le premier garde l'intervention ouverte pour une reprise plus tard, le second la termine définitivement et exige un compte-rendu.",
    'aide_sous_traitants.astuces_li4' => "<b>Un PdP « Ponctuel »</b> n'a pas besoin d'une date de fin à jour en permanence — c'est normal qu'il reste toujours affiché comme valide.",
