    'aide_sous_traitants.devnote_li2' => "La protection de l'annuaire (bouton masqué aux non-admins) est <b>uniquement visuelle côté PHP</b> : le traitement serveur <code>action_entreprise</code> ne revérifie pas le rôle.",
    'aide_sous_traitants.devnote_li3' => "Seule l'extension <code>.pdf</code> est acceptée à l'upload du PdP, contrôlée côté serveur — bonne pratique à conserver.",
